INSERT INTO resources (source_id, resources_id, name, name_en, description, detailed_description, resource_type, resource_type_name, template_name, subjects, keywords, authors, organization_name, region, data_time, doi, license, privacy_type, privacy_condition, storage_num, file_count, structured_count, visit_num, download_num, follow_num, status, release_type, version, logo_url, file_formats, suffix_storage, corresponding_author_name, corresponding_author_email, unit_name, unit_address, unit_postal_code, approve_time, create_time) VALUES
  ('5689a08e6b884e759fe354021d0e8575', 'a23a03b4fce74882bf150d89ab0d0438', '全球陆地水文地貌属性数据集', 'Global Terrestrial Hydrological and Geomorphological Attributes Dataset', '数据采用全球单机大内存 HPC 节点一次性遍历所有 75.17 亿个3 arcsec 网格 (其中 22.26 亿个有效陆地像素) 生成，无需切片拼接，全球拓扑严格一致。生产流程包含三步: (1) 全球流域统一勘界，一次性划出 24,587,290 个拓扑闭合流域 (其中上游面积 ≥ 1 km² 的有 340,991 个)，按 96 个 region (HydroBASINS Level-02 人工整理)切分存储，每个流域完整落在单一 region 内；(2) 对每个 region 构建深度优先遍历 (DFS) 区间索引 (dfs_in, dfs_out)，把"任意像素的上游集水区"压缩为一对整数区间表示，避免后续上游 query 时的图遍历或反向追溯；(3) 在全球上游面积 ≥ 10 km² 的约 4.4 亿个像素上，通过 boundary walk 沿上游边界一次扫描、配合上游聚合算法，逐像素计算 16 个形态学与地形属性。
主要记录了全球 basin ID 栅格、region ID 栅格、Basin AttributeTable (BAT) / Region Attribute Table (RAT)、每个像素的 DFS 区间索引 (dfs_in, dfs_out)，以及每个像素当作流域出口时其上游集水区的 16 个属性观测值——包括上游平均/最小/最大/标准差海拔，平均/标准差坡度，流域起伏 (relief)，高程积分 (hypsometricintegral)，流域周长、轴长 (basin length)、宽度 (basin width)、平面凸度 (convexity)，以及拉长比、Gravelius 紧凑度、圆度比、Lemniscate 比共 4 个无量纲形态指数。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['水文地理学'], ARRAY['水文地貌','流域尺寸','形态指数','平面几何','高程','全球90m'], '[{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"姜璐璐","en_name":"","@id":"62610f879674475e8e259a64","email":"lulu_jiang@pku.edu.cn"}]'::jsonb, '南京信息工程大学', NULL, NULL, NULL, 'CC BY-ND 4.0', 'open', NULL, 138224318071, 2015, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"tif","count":1914},{"name":"rar","count":3},{"name":"csv","count":98}]'::jsonb, '[{"storageNum":127151725573,"name":"tif"},{"storageNum":2037048770,"name":"rar"},{"storageNum":9035543728,"name":"csv"}]'::jsonb, '吴欢', 'huanwu_flood@nuist.edu.cn', NULL, NULL, NULL, '2026-05-21', '2026-05-20'),
  ('479a1e9de36a4cb0bd47923f0035f46b', '1d1aa6d9a2a54a90a26cb62132955055', '西昆仑造山带沉积物中碎屑锆石 U-Pb 同位素数据集', NULL, '数据集来源：论文《西昆仑造山带沉积物中碎屑锆石 U-Pb 年龄与 Eu 异常：对原特提斯洋演化的启示》
数据类型：西昆仑库地地区页岩和杂砂岩样品主量、微量与同位素数据
原特提斯洋的洋壳残片以库地蛇绿岩的形式保存在西昆仑造山带（WKOB）中，其演化历史主要基于对区内火成岩或变质岩的研究而建立。相比之下，西昆仑造山带中的沉积岩过去受到的关注较少，然而它们可为洋壳演化提供重要约束。本文对分布于西昆仑库地地区的一系列页岩和杂砂岩进行了研究，以限定其沉积时代并探讨其在原特提斯洋洋壳演化中的意义。对杂砂岩夹层中的碎屑锆石开展了U-Pb定年和铕异常（Eu/Eu*）分析，同时测定了页岩样品的全岩稀土元素和钇（REY）含量。碎屑锆石U-Pb年龄结果表明，杂砂岩和黑色页岩的最大沉积年龄为436 Ma；黑色页岩的REY配分模式与塔里木地区奥陶纪萨尔干页岩相似。据此认为，研究区西昆仑黑色页岩形成于晚奥陶世—早志留世的原特提斯洋环境中。436 Ma的最大沉积年龄可能代表原特提斯洋闭合时间的最小限制，这也得到晚奥陶世—早志留世期间Eu/Eu值未出现升高现象的支持。此外，碎屑锆石的Eu/Eu值显示，从太古代至中元古代造山作用减弱，而在新元古代则表现为与罗迪尼亚超大陆边缘俯冲相关的增生作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['碎屑锆石 U-Pb 年龄'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨涛","en_name":"","@id":"013ccc88-ae1e-4da6-b78e-01b97bb214fe","email":"yangtao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 122386, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":122386,"name":"xlsx"}]'::jsonb, '杨涛', 'yangtao@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('c88b03700109474183cbeec8d472a2d5', '50770b18abee4e8cb35008dce66dc491', '中国天山康古尔—黄山剪切带构造演化数据集', NULL, '数据集来源：《中国天山康古尔—黄山剪切带构造热演化：综合年代学与低温热年代学的启示》
数据集类型：中国天山康古尔—黄山剪切带锆石U-Pb同位素数据、磷灰石微量元素数据等；
数据集研究摘要：结合地质热年代学与构造分析，可以为康古尔-黄山剪切带（KHSZ）——中亚东天山造山带中一条重要的走滑断裂和成矿带——的变形与剥露过程提供深入认识。以往研究主要集中于构造、年代学和地球化学等方面，常忽视剥露动力学过程。本研究采用锆石U-Pb、(U-Th)/He（ZHe）、磷灰石裂变径迹（AFT）及(U-Th)/He（AHe）定年方法，结合野外观察与显微构造分析，揭示了KHSZ西段的剥露过程。同构造岩石的新锆石U-Pb年龄为280–260 Ma，U-Th/He年龄为215–180 Ma，与已发表的Ar/Ar数据相结合，指示伸展背景下岩浆期后快速冷却和剪切作用。随后，该区域发生构造反转，转为压扭性并经历剥露，剪切带内部的块体遭受更强的剥露，并形成正花状构造，该过程持续至约200 Ma。晚侏罗世至早白垩世最早期获得的AFT年龄（165–145 Ma）及重叠的AHe年龄（155–145 Ma）表明，在侏罗纪差异性埋藏之后，样品经历了快速冷却，随后逐渐剥露至近地表。对现有数据的综合归纳表明，中生代中等的冷却作用、侏罗纪的再埋藏以及白垩纪-新生代的构造沉寂，是KHSZ西段的主要特征。这一地质历史对该区域斑岩型铜矿床以及浅成低温热液型金矿和铁铜矿床的保存至关重要。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['构造热演化'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"朱文斌","en_name":"","@id":"3d046902-f1b3-4f9a-b09e-8d437c1ae7c8","email":"zwb@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 22395, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":22395,"name":"xlsx"}]'::jsonb, '朱文斌', 'zwb@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('1cf380c41de84cee81a73108eaabdfe6', '09e6faf5be7a44bd8b1e09c640837ff2', '熔体-橄榄岩相互作用引发的玄武岩Mg-Fe同位素数据集', NULL, '数据集来源：《熔体-橄榄岩相互作用引发的玄武岩Mg-Fe同位素数据集》
数据集类型：中国东部玄武岩中碱性玄武岩橄榄岩包体的主量、微量与同位素含量数据
数据集研究摘要：尽管镁和铁同位素常被用于示踪玄武岩的源区不均一性（例如地幔中再循环的碳酸盐化物质或榴辉岩），但在岩浆从源区迁移至地表的过程中，它们也可能因地质作用而发生分馏。最近，在高钛月球玄武岩中观察到的轻镁和重铁同位素组成被归因于熔体与周围方辉橄榄岩堆晶岩相互作用过程中发生的动力学分馏。由于岩石圈地幔较厚，熔体-橄榄岩相互作用常被用来解释地球上大陆玄武岩所观察到的化学变化。然而，这一过程中镁-铁同位素的分馏行为尚未得到很好的研究。为此，我们对中国东部南京玄武岩中的碱性玄武岩及其所携带的橄榄岩包体进行了镁-铁同位素组成分析，以评估在该特定条件下的潜在同位素分馏。前人岩相学证据表明，这些橄榄岩包体曾与寄主玄武岩发生过显著的相互作用。橄榄岩包体具有均一的、正常地幔样的δ²⁶Mg值（-0.243‰ 至 -0.281‰），但δ⁵⁷Fe值变化很大且偏低（0.156‰ 至 -0.057‰），这表明部分熔融反应并未改变这些包体的镁同位素组成，但改变了其铁同位素组成。寄主玄武岩具有重的铁同位素组成（δ⁵⁷Fe = 0.218‰–0.366‰）和极轻的镁同位素组成（δ²⁶Mg = -0.641‰ 至 -0.389‰）。这些富含包体的玄武岩的δ²⁶Mg值与其δ⁵⁷Fe值、Hf同位素以及某些元素比值（如Lu/Hf、La/Sm、Ca/Al、Na/Ti）呈良好相关性。这些相关性可通过寄主玄武质岩浆与源自橄榄岩包体的某种熔体之间的混合来解释。这些源自包体的熔体具有比正常地幔明显更轻的镁同位素和更重的铁同位素组成。由于近固相线熔融导致其Mg/Fe比值极低，它们与残留固相之间在镁或铁上并未达到平衡。因此，推断在熔体与橄榄岩相互作用过程中发生了动力学镁-铁同位素分馏。综上所述，我们的结果为表征自然体系中化学扩散导致的镁-铁同位素分馏提供了一个代表性样本，并突显了熔体-橄榄岩相互作用对那些富含包体的玄武岩（以低熔体/橄榄石比例为特征）中镁-铁同位素不均一性的重要影响。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['镁-铁同位素分馏'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"曾罡","en_name":"","@id":"37a018f1-2231-4f3d-ba66-8dc636533ace","email":"zgang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 41374, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":41374,"name":"docx"}]'::jsonb, '曾罡', 'zgang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('a1fb6a55ea794739b66c51482ceb635a', '40082d8442f542c1bea6f30bcfa23ad9', '古新世-始新世海相浅水碳酸盐岩锂同位素数据集', NULL, '数据集来源：《大陆风化机制变化抑制了古新世—始新世极热事件期间全球海洋缺氧化》
数据集类型：沉积型海相浅水碳酸盐岩的锂同位素等数据
数据集研究摘要：在全球快速变暖背景下，古新世-始新世极热事件（PETM，~55.9 Ma）期间海洋氧化还原状态和生物多样性的变化相对温和，这与地球历史上的其他极热事件形成对比，其成因尚不明确。本研究利用锂同位素（δ7Li）示踪和地球系统模型模拟，重建了PETM期间大陆风化体制的变化。海相浅水碳酸盐岩中δ7Li值出现3–4‰的负偏移，指示全球范围内物理侵蚀速率增加而化学风化强度降低。此外， siliciclastic序列中4–5‰的显著负δ7Li偏移，反映的是先前存在的富粘土沉积岩剥蚀所释放的碎屑粘土的累积增加，而非岩浆岩风化直接产物的增多。大陆风化体制的改变及其向海洋输送的营养盐通量的变化，为解释PETM期间海洋缺氧范围扩大有限以及总体生物多样性损失较小的现象提供了依据。物理侵蚀和粘土输入的同时增加也提升了有机碳的埋藏效率，从而促使全球气候快速回归扰动前状态。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['全球海洋缺氧'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张飞飞","en_name":"","@id":"170e7cf6-034f-4bac-af34-3918b0c3aa77","email":"fzhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 2635496, 2, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":2}]'::jsonb, '[{"storageNum":2635496,"name":"pdf"}]'::jsonb, '张飞飞', 'fzhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('f6141004015747c58bc9f04c9cac3fe5', 'b527ce80d7914b6684bbafbaace6bb20', '全新世岛屿碳酸盐铀同位素数据集', NULL, '数据集来源：论文《基于晚渐新世至全新世岛屿碳酸盐连续记录推进碳酸盐铀同位素作为古氧化还原指标的研究》
数据集类型：全新世岛屿碳酸盐与海水中238U/235U，δ238U等铀同位素数据集
数据集研究摘要：理解碳酸盐岩成岩过程中铀同位素（238U/235U，通常表示为δ238U）的分馏行为，对于利用海相碳酸盐岩定量重建地球历史时期全球海底缺氧范围的变化至关重要。现有的成岩作用研究框架主要基于巴哈马碳酸盐岩台地，其稳健性和适用性需要在其他地区进行验证。由于缺乏对成岩阶段、环境和氧化还原条件如何影响铀同位素分馏的系统研究，目前用于识别成岩过程中铀同位素改造的替代指标的可靠性仍然不足。本研究从南海两口深钻（XK-1孔，约600米；NK-1孔，约1000米）中连续采集了岛礁碳酸盐岩样品，其年代跨度从晚渐新世至全新世（约25 Ma至今）。这些经历了强烈大气淡水和海相成岩作用的样品基本不含有机质，为验证巴哈马成岩框架和探索识别成岩过程中铀同位素改造的新地球化学工具提供了绝佳机会。观测到的南海样品δ238U值与同期海水的显著正偏移（0.24‰ ± 0.24‰, 1SD, n = 152）与巴哈马地区的结果（0.24‰ ± 0.15‰, 1SD）相似，表明早期成岩过程中的铀同位素分馏可能在全球尺度上具有一致性。南海同沉积成岩作用相关的δ238U值显示出0.25‰ ± 0.07‰（1SD）的均一偏移，与巴哈马地区观测结果（0.26‰ ± 0.10‰, 1SD）一致，表明同沉积成岩过程中的铀同位素分馏在浅水碳酸盐岩中广泛存在，且在不同氧化还原环境下具有一致性。然而，在沉积后成岩过程中δ238U值会进一步发生改造，其中海相沉积后成岩过程中的δ238U值主要取决于成岩流体的氧化还原条件。根据钒（V）-铀（U）浓度的顺序富集特征，我们将南海海相成岩环境中的成岩流体氧化还原条件划分为上次氧化和下次氧化两种状态。在上次氧化条件下，δ238U值与同期海水的偏移几乎可以忽略；而在下次氧化条件下，由于自生U(IV)的富集，偏移量逐渐增加约1‰。然而，早成岩期大气淡水成岩过程中的δ238U偏移（0.18‰ ± 0.12‰, 1SD）主要继承自早期同沉积成岩作用。来自南海的新数据证实，碳酸盐岩与海水之间普遍存在0.24‰ ± 0.24‰（1SD）的成岩偏移量，而单个样品的具体偏移值由其成岩阶段、环境和氧化还原条件决定，这些可以通过碳酸盐岩中的V-U顺序富集特征进行定量评估。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['碳酸盐铀同位素'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张飞飞","en_name":"","@id":"170e7cf6-034f-4bac-af34-3918b0c3aa77","email":"fzhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 93660, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":93660,"name":"xlsx"}]'::jsonb, '张飞飞', 'fzhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('a04e30a9a735491aaa6a25aabb5df71d', '3027360272d5409c81541e6be3640dd9', '成冰纪斯图特冰期与马里诺冰期数据集', '', '数据集来源：《利用铊同位素重建成冰纪间冰期海洋氧化还原格局》
数据集类型：南华盆地两钻孔剖面中ε²⁰⁵Tl等高分辨率铊同位素数据集
数据集研究摘要：成冰纪斯图特冰期与马里诺冰期之间（约663–654 Ma）海洋氧化还原化学条件的变化，对于理解环境条件与早期动物出现及多样化的潜在关系至关重要。华南的南华盆地提供了近乎完整的成冰纪间冰期沉积记录，即大塘坡组。本研究利用南华盆地（华南）两个钻孔的剖面，对大塘坡组底部进行了高分辨率铊同位素（ε²⁰⁵Tl）分析，以约束成冰纪间冰期海洋氧化还原条件的变化。获得的ε²⁰⁵Tl值介于-4.9至-0.7之间，平均值为-2.8，低于上地壳的ε²⁰⁵Tl值（-2.1 ± 0.3），但高于现代海水的ε²⁰⁵Tl值（-6 ± 0.6）。我们在两个钻孔的下部均观测到负漂移，指示大塘坡组底部存在一期海洋充氧事件。在膏地和长兴坡两个钻孔中，ε²⁰⁵Tl值自下而上均由较低值转变为较高值，表明海洋又恢复到大范围的缺氧条件。一个简单的质量平衡模型表明，富含氧化锰的沉积物是南华盆地中铊的重要汇（膏地：氧化相占比7-14%；长兴坡：氧化相占比13-20%）。我们的ε²⁰⁵Tl数据也为解释大塘坡组底部黑色页岩中的锰碳酸盐矿床提供了新视角，其中含锰碳酸盐层段的ε²⁰⁵Tl值支持这些锰碳酸盐是斯图特冰期之后由氧化锰前体转变而来。铊同位素数据表明，富含氧化锰的沉积物是成冰纪间冰期海洋中铊的一个重要汇；如果这反映了海洋氧化条件，那么这一瞬时充氧事件恰好与藻类的首次显著辐射事件相吻合，很可能为多细胞生物的出现奠定了生态基础。这些发现突显了成冰纪间冰期海洋氧化还原波动与早期生物演化之间的复杂联系。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['成冰纪间冰期'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张飞飞","en_name":"","@id":"170e7cf6-034f-4bac-af34-3918b0c3aa77","email":"fzhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 13855084, 4, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"csv","count":3},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":593492,"name":"csv"},{"storageNum":13261592,"name":"docx"}]'::jsonb, '张飞飞', 'fzhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('b8762b26c64e4847bf3cc8678dfd7163', 'c7c3c791289d454bbb8b2c00957c114b', '安特勒前陆盆地中图尔奈阶钡同位素数据集', NULL, '数据集来源：《增强的海洋生物泵作用触发晚古生代冰期的开始》
数据集类型：安特勒前陆盆地中图尔奈阶δ138Ba等钡同位素数据集
数据集研究摘要：中图尔奈阶碳同位素漂移事件（TICE）是晚古生代最大的正碳同位素漂移事件，与晚古生代冰期（LPIA）的起始同步发生。为探究TICE期间海洋生物泵的变化，本研究对美国安特勒前陆盆地两个海相石灰岩剖面进行了钡同位素（δ138Ba）分析。我们发现了地质历史上最显著的正δ138Ba偏移，指示安特勒前陆盆地在TICE期间海洋输出生产力升高，随后发生了生产力驱动的缺氧扩张。两个剖面之间δ138Ba的地层变化趋势几乎一致，但绝对值存在差异，表明早密西西比世海洋生物泵强度存在空间差异性。地球系统模型模拟结果显示，要解释观测到的变化，全球海洋输出生产力需要整体提高30%。我们的研究结果支持以下观点：增强的海洋生物泵促进了有机碳埋藏的增加，并推动了从温室气候向晚古生代冰期的转变。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['晚古生代冰期'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张飞飞","en_name":"","@id":"170e7cf6-034f-4bac-af34-3918b0c3aa77","email":"fzhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 4616006, 2, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1},{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":42309,"name":"zip"},{"storageNum":4573697,"name":"pdf"}]'::jsonb, '张飞飞', 'fzhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('64df4d211f99449fa94047da5312fc71', '65daea4f1b534842a64715067fb5ba98', '华北克拉通九龙山剖面碳酸盐岩数据集', NULL, '数据集来源：论文《锂—钡同位素组合揭示晚寒武世 SPICE 事件中风化与生产力的控制作用》
数据集类型：晚寒武世SPICE事件中华北克拉通九龙山剖面碳酸盐岩的高分辨率锂（δ7Li）和钡（δ138Ba）同位素数据集
数据集研究摘要：晚寒武世SPICE（斯蒂普托阶正碳同位素漂移）事件（约497–494 Ma）是显生宙最大的碳酸盐岩碳同位素正漂移事件之一，与三叶虫的快速更替事件同步发生。已有研究提出，SPICE事件由有机碳埋藏增加所驱动，而有机碳埋藏的增加可能源于海洋生产力提高、海洋缺氧范围扩大和/或大陆化学风化作用增强。本研究基于华北克拉通九龙山剖面碳酸盐岩的高分辨率锂（δ7Li）和钡（δ138Ba）同位素分析，重建了SPICE事件期间大陆风化和海洋生产力的演变过程。钡同位素在SPICE事件开始之前显示出约0.8‰的正漂移，随后在SPICE上升期迅速下降至低至0.2‰，表明区域海洋生产力在SPICE事件之前就已升高，并在SPICE上升期出现生产力驱动的海洋缺氧。锂同位素在SPICE事件起始阶段呈现出约4‰的负漂移，随后在SPICE下降期出现约5.5‰的正漂移。锂同位素的变化趋势表明，在SPICE上升期发生了一期大陆风化作用增强事件，该事件可能进一步促进了海洋生产力的提高，从而导致有机碳埋藏增加、海洋缺氧范围扩大，并最终形成了全球广泛记录的正碳同位素漂移。因此，我们的δ7Li与δ138Ba配对数据为深入理解SPICE事件的具体机制及其与同期生物群变化之间的潜在联系提供了新的认识。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['晚寒武世 SPICE 事件'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张飞飞","en_name":"","@id":"170e7cf6-034f-4bac-af34-3918b0c3aa77","email":"fzhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 287330, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":287330,"name":"docx"}]'::jsonb, '张飞飞', 'fzhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('d1b238da1fcf4d35820099bb15dda03a', 'f6a5c11296c24b99926996f9419e4575', '后冰期钱塘江钻孔沉积序列数据集', NULL, '数据集来源：论文《后冰期钱塘江切割河谷体系的海平面与气候演化：来自粒度端元模型与地球化学特征的证据》
数据集类型：冰后期钱塘江下切河谷沉积序列与碳酸盐岩微相数据
数据集研究摘要：气候和海平面波动通过调控不同时空尺度的水文过程和沉积物搬运模式，对海岸系统产生深远影响。冰后期钱塘江下切河谷充填体由于记录了末次盛冰期以来的连续沉积，且与邻近的长江和东海陆架存在复杂的耦合关系，成为揭示这些影响的天然实验室。本研究基于一根60米长的沉积序列（SE3孔），通过地球化学分析和粒度端元（EM）建模，详细研究了沉积物来源、搬运格局及其对海平面和气候变化响应。结果表明，相对海平面与气候变化共同控制了钱塘江体系中5个粒度端元的时空分布以及沉积物搬运路径。其中，最细端元（EM1）的含量和最粗端元（EM5+EM4）的总量对相对海平面变化敏感：EM1含量最高、EM5+EM4总量最低指示最大海侵范围。随着海水侵入，自古河口湾形成以来，长江来源的沉积物开始进入钱塘江体系，以EM1和EM2的总量为代表，该总量与基于地球化学数据定量计算获得的长江沉积物贡献呈正相关关系。进一步地，在浅海相和现代河口湾靠海侧的形成过程中，长江来源的EM1和EM2成为主导组分。它们在浅海和现代河口湾环境中的总量垂向变化及相关的地球化学特征，主要反映了浙闽沿岸流与间歇性增强的东亚冬季风的共同作用，这些作用显著改变了长江来源悬浮沉积物在输运至钱塘江体系过程中的性质。此外，在河流相及古河口湾近陆侧识别出三个以最粗端元中EM5相对含量（即EM5/(EM5+EM4)）和TOC/TN值正偏为特征的古洪水事件集中段。这些古洪水可归因于新仙女木期（YD，13–11 ka BP）、10.6–10.3 ka和9.3 ka冷事件期间的异常气候变化。综上所述，高分辨率的粒度端元与地球化学特征相结合，能够评估海岸带下切河谷充填体对气候和海平面变化的响应，即使在具有复杂沉积物搬运路径和物理过程的体系中亦如此。本研究应为全球类似海岸带环境重建和预测气候与海平面演化提供新的启示。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['气候演化'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张霞","en_name":"","@id":"b78dd799-e6eb-4f48-855b-386248b1960c","email":"zhangxia@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通许作者', 11149079, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":11149079,"name":"pdf"}]'::jsonb, '张霞', 'zhangxia@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('5ca8bd2bcfa8454c84ea311edb8b75ee', '1bc52a0f9b2c49d5a20355b53f3b279e', '中国东部钱塘江口磷含量数据集', NULL, '数据集来源：论文《沿海体系中磷埋藏与沉积后成岩作用对后冰期气候变化的响应》
数据集类型：中国东部钱塘江口铁结合态磷形态、铁（氢氧）氧化物、主量元素、营养元素（碳和氮）含量的变化数据
数据集研究摘要：沿海系统中的磷埋藏与成岩作用决定了向海洋输送的反应性磷通量，从而影响初级生产力和营养元素循环。为揭示沿海地区磷的归宿及其与冰后期气候变化的关系，我们对中国东部钱塘江口沉积柱中的磷形态、铁（氢氧）氧化物、主量元素、营养元素（碳和氮）以及蓝铁矿矿物特征进行了系统分析。研究结果表明，在钱塘江口湾系统中，磷循环主要受冰后期海平面变化的控制。铁结合态磷在河流相和古河口湾相沉积物中占主导地位，约占总磷库的79%，主要以蓝铁矿形式存在，尤其在河口-海相过渡带以下层位中富集。这种富集与约8.5 ka BP海侵引起的底层海水硫酸盐浓度升高和沉积速率降低有关，从而促进了甲烷的持续厌氧氧化和铁氧化物的还原溶解。相比之下，在浅海相和现代河口湾沉积物中，钙结合态磷（主要为碳酸盐氟磷灰石）以消耗铁结合态磷和有机磷的方式形成，成为高海平面时期主要的磷汇。高强度的铁结合态磷沉积事件与发生在新仙女木-全新世转换期的古洪水事件有关。洪水驱动的表层沉积物氧化作用促进了铁氧化物与磷的共沉淀，显著降低了铁结合态磷中的Fe/P比值。我们的研究突显了冰后期气候变化通过海平面波动、环境扰动和气候突变事件对沿海磷循环产生的长期影响。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['后冰期'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张霞","en_name":"","@id":"b78dd799-e6eb-4f48-855b-386248b1960c","email":"zhangxia@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 32658, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":32658,"name":"xlsx"}]'::jsonb, '张霞;', 'zhangxia@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('bb3b99dea9fe476faad1d8e9857700d0', '7dbeae8e40874c4a8a44bc734c894ba1', '塔里木克拉通东南部阿克塔什塔格太古宙基底岩石热构造演化数据集', NULL, '数据集来源：论文《塔里木克拉通东南部阿克塔什塔格太古宙基底岩石热构造演化史：来自锆石 U-Pb、锆石与磷灰石裂变径迹定年的约束》
数据集类型：塔里木克拉通东南缘阿克塔什塔格杂岩锆石U-Pb定年、磷灰石矿物定年和锆石裂变径迹热年代学数据
数据集研究摘要：稳定的克拉通岩石圈边缘因周缘构造活动影响，可经历复杂的构造事件。本研究对塔里木克拉通东南缘阿克塔什塔格杂岩进行了锆石U-Pb定年、磷灰石和锆石裂变径迹热年代学的综合分析。获得的磷灰石裂变径迹年龄介于~219 Ma至~104 Ma之间，锆石裂变径迹年龄则介于~1,400 Ma至~100 Ma之间。通过对261颗锆石进行双定年分析，获得的锆石U-Pb年龄范围约为3.6 Ga至1.9 Ga。锆石裂变径迹年龄的复杂性归因于同时存在高封闭性和低封闭性两类锆石。高封闭性锆石表明，自约1.0 Ga以来，样品未经历过高于锆石裂变径迹封闭温度（~350°C）的热事件。在研究区可以识别出~2.0–1.9 Ga及1.4 Ga之后的再加热事件，以及~1.9–1.8 Ga、~1.4 Ga和~1.0 Ga的冷却事件。利用QTQt软件进行的热历史反演模拟揭示了两次重要的构造热事件：（a）中-晚侏罗世的快速岩石冷却；（b）从渐新世至今的再次快速冷却。前一期冷却事件可能与拉萨地块与亚洲大陆南缘的碰撞有关，而后一期冷却事件则通常与印度-欧亚大陆碰撞的远程效应相联系。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['热构造演化'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"朱文斌","en_name":"","@id":"3d046902-f1b3-4f9a-b09e-8d437c1ae7c8","email":"zwb@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 69265, 3, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":3}]'::jsonb, '[{"storageNum":69265,"name":"xlsx"}]'::jsonb, '朱文斌', 'zwb@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('93571c3578b6499995a12f8d248b97ad', '5f87608fed4c45b391c5954166a59559', '郯庐断裂带韧性组构年代学数据集', NULL, '数据集来源：论文《通过锆石与榍石 U-Pb 年代学限定肥东杂岩亚水平韧性构造：对郯庐断裂带南段中三叠世走滑挤压变形的启示》
数据集类型：郯庐断裂带肥东杂岩东部高应变岩石的U-Pb年代学数据
数据集研究摘要：三叠纪扬子板块与华北板块的碰撞导致了苏鲁-大别造山带中超高压变质岩的形成、郯庐断裂带的发育，以及下扬子前陆褶皱冲断带内地壳尺度的滑脱层的建立。郯庐断裂带南段张八岭-肥东杂岩中出露的韧性组构记录了该碰撞过程中积累的应变。本文通过对肥东杂岩东部高应变岩石（包括显微构造和石英晶体学优选方位）的野外观察和构造分析，结合变形温压条件的估算，揭示了角闪岩相（600–700°C，4.0–6.6 kbar）的顶部向SSW方向近水平韧性组构，该组构叠加于古元古代肥东杂岩之上。锆石边部和同构造榍石的U-Pb年代学表明，叠加变形发生于中三叠世（约246–242 Ma）。对横穿郯庐断裂带和下扬子前陆褶皱冲断带的地震反射剖面的重新解释，识别出沉积盖层下方存在一个大型近水平的滑脱层，该滑脱层可能影响了下扬子前陆褶皱冲断构造的形成。这些新观测结果和年代学数据支持一个压扭性构造模型，即早-中三叠世扬子板块向北楔入华北板块，驱动了郯庐断裂带南段内部的变形。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['走滑挤压变形'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张岳桥","en_name":"","@id":"170a25aa-19f2-4da5-8eda-ca4122cfc535","email":"zhangyq@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 108187, 4, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":4}]'::jsonb, '[{"storageNum":108187,"name":"xlsx"}]'::jsonb, '张岳桥', 'zhangyq@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('9db6dae1176c4c549228272864cbdb82', '3e29c2e747da4790a5c75b35370ddbf3', '华北克拉通西部古元古代造山事件：来自阿拉善地块北大山变沉积岩锆石 U-Pb-Lu-Hf 同位素与地球化学的证据', NULL, '数据集来源：论文《华北克拉通西部古元古代造山事件：来自阿拉善地块北大山变沉积岩锆石 U-Pb-Lu-Hf 同位素与地球化学的证据》
数据集类型：阿拉善地块内古元古代岩浆碎屑锆石U-Pb-Lu-Hf同位素分析以及全岩主量和微量元素数据
数据集研究摘要：近期研究揭示了阿拉善地块内古元古代岩浆和变质事件，但这些地质记录通常被认为与古元古代造山事件相关，而该潜在造山带的性质和位置尚不明确。本文通过对北大山杂岩中一套古元古代变表壳岩进行系统的碎屑锆石U-Pb-Lu-Hf同位素分析以及全岩主量和微量元素分析，为该造山事件提供了新的认识。变表壳岩上部序列的形成时代被限定在1.89~1.83 Ga，其碎屑锆石呈现以~1.96 Ga为中心的单峰分布，Hf模式年龄峰值约为2.4 Ga和2.6~2.7 Ga；下部序列的沉积时代则被限定在2.08~2.05 Ga，其碎屑锆石年龄峰值约为2.20 Ga、2.30 Ga和2.41 Ga，Hf模式年龄峰值约为2.95 Ga。地球化学分析表明，上部序列中的斜长角闪岩富集轻稀土元素（LREE），并具有Nb、Ta负异常；而下部序列中的斜长角闪岩则表现出相对较低的稀土元素分异程度，并亏损高场强元素（HFSE）。两个序列均显示出Nb-Ta槽的特征，这是典型的大陆弧玄武岩和安山岩的标志。上部序列斜长角闪岩的轻稀土元素富集程度更高，可能指示其形成于晚造山环境。北大山杂岩中碎屑锆石的年龄分布和Lu-Hf同位素组成与阿拉善地块出露的太古代-古元古代岩浆岩相吻合，表明阿拉善地块南部的北大山、龙首山和巴彦乌拉山地区可能是下部序列的物源区，而北部的叠布斯格地区则可能是上部序列的物源区。这种约1.9 Ga发生的物源转变可能反映了研究区北侧增生造山带的隆升，该过程不仅向沉积记录中引入了新的年轻地壳物质，同时切断了来自南部的原始物源供给。因此，我们认为阿拉善地块在2.1~1.8 Ga期间，于北大山杂岩以北经历了一次造山事件，该事件可能与一个未知大陆沿阿拉善地块北缘发生的俯冲和碰撞作用有关，并促成了哥伦比亚超大陆的形成。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['华北克拉通'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"朱文斌","en_name":"","@id":"3d046902-f1b3-4f9a-b09e-8d437c1ae7c8","email":"zwb@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1060272, 6, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":4},{"name":"docx","count":2}]'::jsonb, '[{"storageNum":223316,"name":"xlsx"},{"storageNum":836956,"name":"docx"}]'::jsonb, '朱文斌', 'zwb@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('5aed40a61ec848ccb54d51d0489c472c', '25e7dc30fdb240f0a84f7389298dd65d', '地幔过渡带条件石榴子石氢退火实验数据集', NULL, '数据集来源：论文《地幔过渡带条件下石榴子石中的水赋存：一种独特的红外吸收带》
数据集类型：地幔过渡带条件下石榴子石水的种类和含量数据
数据集研究摘要：石榴子石是地幔过渡带中的关键矿物组分，通常以富镁铝榴石（pyrope）为主（但含有富 Si 的 majorite 组分）。关于地幔过渡带中石榴子石的水（羟基）储存能力，已有多项实验研究，但其水的赋存机制仍不清楚。本文在 15–21 GPa、1300–1500 °C 及 Fe–FeO 缓冲氧逸度条件下开展了氢退火实验，系统研究了地幔过渡带条件下石榴子石中水的引入机制。实验选取了三件不同化学成分的天然宝石级富镁铝榴石单晶作为起始样品，并对实验中的共存矿物组合和流体条件进行了控制。通过红外光谱分析测定样品中水的种类和含量。回收样品的红外光谱均显示在约 3630 cm⁻¹ 处存在一个相似的单一不对称吸收带，尽管其化学组成、初始光谱形态（如峰位或谱带形态）及实验条件存在显著差异。该吸收带被认为是地幔过渡带条件下石榴子石中水的特征峰，其形态与端元纯镁铝榴石中观察到的吸收带基本一致，可能主要由广泛接受的“水石榴子石”类质同象替代引起。对比低压低温退火实验结果（其中不同石榴子石样品中水的峰位与其初始晶体基本一致）表明，压力和温度是影响谱带形态的两个关键因素。地幔过渡带对应的高压高温条件可能以不同于低压低温环境的方式重塑石榴子石中氢的局部键合环境，从而形成约 3630 cm⁻¹ 的特征单峰。在其他条件相当的情况下，不同石榴子石样品的含水量与其他化学组分之间呈现复杂相关性，反映出成分控制的水引入机制，其中与 FeO 和 MgO 含量的相关性最为显著，而与其他组分的相关性较弱或不明显。这表明 Fe 和 Mg 很可能在水的引入过程中也发挥重要作用；然而，约 3630 cm⁻¹ 的单一吸收带说明，由 Fe 和 Mg 类质同象替代引起的红外信号可能与水石榴子石替代机制的信号发生叠加。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['Garnet',' Water incorporation'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨晓志","en_name":"","@id":"1cd7d3ff-8199-497c-be2e-372431cb4bc0","email":"xzyang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 238212, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":238212,"name":"pdf"}]'::jsonb, '杨晓志', 'xzyang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('83225bbe1314496694a7dc724a66e6b6', 'fc270021d7064a41a6cae9a88253a008', '中亚造山带南部镁铁质弧岩浆地球化学数据集', NULL, '数据集来源：《中亚造山带南部镁铁质弧岩浆揭示的早古生代大规模俯冲后撤与板片回卷》
数据集类型：中国西北部喀拉塔什塔格地区镁铁质岛弧岩石主量元素、微量元素和同位素数据
数据集研究摘要：中亚造山带（Central Asian Orogenic Belt）塔里木—华北拼贴体（Tarim–North China collage）北缘广泛发育早古生代岛弧岩浆作用，但其岩石成因及构造意义长期存在争议。本文以中国西北部喀拉塔什塔格（Kalatashtagh）地区镁铁质岛弧岩石为研究对象，揭示其形成时代为450–420 Ma。全岩地球化学特征显示，这些岩石具有高铝岛弧玄武岩（high-Al arc basalts）特征。俯冲板片示踪指标表明，其源区亏损地幔中约有5%的板片来源沉积物熔体加入。热力学—地球化学模拟进一步表明，该类岩浆形成于约120 km深度条件下石榴子石二辉橄榄岩（garnet lherzolite）约20%的部分熔融，并在岩浆演化过程中经历了单斜辉石、橄榄石、尖晶石及斜长石的分离结晶作用。
结合区域资料，研究认为该时期在塔里木—华北拼贴体北缘形成了一条长度超过1500 km的大陆弧体系。地球化学证据表明，在弧下地幔楔中，板片来源沉积物熔体对地幔交代作用的贡献明显强于含水流体。这可能与板片后撤（slab rollback）过程中软流圈上涌导致板片表面温度升高有关。该过程同时诱发了拼贴体北缘边缘地体的裂解以及弧后盆地（back-arc basins）的形成。研究进一步提出，这种退缩型俯冲带（retreating-type subduction zone）可能在全球尺度上相互连接形成环状构造体系，从而促进了冈瓦纳大陆（Gondwana）的长期裂解与古特提斯洋（Palaeotethys）的开启。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['镁铁质弧岩浆'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"朱文斌","en_name":"","@id":"3d046902-f1b3-4f9a-b09e-8d437c1ae7c8","email":"zwb@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"葛荣峰","en_name":"","@id":"ca465377-51e5-4d0c-9a1d-242e2a75957d","email":"gerongfeng@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1074798, 3, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1},{"name":"docx","count":2}]'::jsonb, '[{"storageNum":80393,"name":"xlsx"},{"storageNum":994405,"name":"docx"}]'::jsonb, '朱文斌', 'zwb@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('f423a762db9d4dbdb6cfe2d717d7b284', 'c9a0110f0df2488582492233a7c0f89c', '化石化过程黑色毛发转变特征数据集', NULL, '数据集来源：论文《毛发梯度成熟实验揭示化石毛发的埋藏成岩变化》
数据集类型：黑色毛发在化石化过程中形态结构、酰胺特征峰等显微特征及化学组成分析的数据
数据集研究摘要：哺乳动物毛发作为与内温性、防护及伪装密切相关的重要特征，其地质历史可追溯至中生代。然而，由于关于毛发埋藏学（taphonomy）过程的研究相对有限，制约了人们对其深时演化意义的理解。为此，本文通过埋藏模拟实验研究黑色毛发在化石化过程中的转化机制。研究利用扫描电子显微镜（SEM）、傅里叶变换红外光谱（FTIR）及拉曼光谱（Raman spectroscopy）系统记录了毛发在模拟化石化过程中形态结构、显微特征及化学组成的变化。结果表明，毛发形态在较低温度（150–175°C）条件下即开始发生破坏，而在较高温度（约200°C）时则逐渐转变为流体状物质。与此同时，黑素体（melanosomes）的形态结构相比角蛋白（keratins）具有更高的保存潜力，其显微结构特征在实验过程中始终保持较高稳定性。
拉曼与FTIR光谱结果显示，随着温度升高，黑色素与角蛋白的特征峰均发生明显变化。尽管化学信号并未完全消失，但FTIR中酰胺特征峰（amide bands）的变化表明，角蛋白在高温条件（>200°C）下发生了强烈降解；相比之下，拉曼光谱中的黑色素特征峰即使在高温条件下（>200°C）仍然可以被识别，说明黑色素信号具有更强的热稳定性。主成分分析（PCA）及主成分—线性判别分析（PCA–LDA）进一步验证了上述结果。
此外，实验样品的拉曼信号均可与常见地质碳质物（如腐殖酸，humic acid）明显区分，表明拉曼光谱技术能够有效识别化石中的黑色素成分。该研究为理解毛发在化石化过程中的保存机制及利用黑色素重建古生物颜色与生态特征提供了重要实验依据。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['化石毛发'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"泮燕红","en_name":"","@id":"c33ef7c0-6a77-4dbf-827f-92a44e03262d","email":"panyanhong@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 559099, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":559099,"name":"docx"}]'::jsonb, '泮燕红', 'panyanhong@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('b8b7715e86d34329b17e1f4535eb0a99', 'a18586e9ed3b411d92fa94d8be8a110d', '黑素体几何形态特征与环境变量相关性数据集', NULL, '数据集来源：论文《黑素体高多样性与兽类早期演化中的颜色及环境变量相关性较弱》
数据集类型：影响哺乳动物黑素体几何形态的颜色因素及环境因素的统计数据
数据集研究摘要：黑素体（melanosome，含黑色素细胞器）几何形态研究曾基于侏罗纪哺乳动物毛发化石提出：早期哺乳动物普遍具有深色体色，这与“夜行性瓶颈”（nocturnal bottleneck）假说相一致。本文利用一个独立的数据集，对约8000个黑素体进行系统分析，涵盖60个现生及化石物种（涉及11个哺乳动物目，并包括一种侏罗纪物种），以进一步探讨影响哺乳动物黑素体几何形态的颜色因素及环境因素。研究结果再次证实，侏罗纪哺乳动物黑素体形态变化范围较小，支持其可能具有相对单一且偏深色的体色特征。与此同时，真兽类（crown therian mammals）中的胎盘类谱系则表现出与鸟类相当的高黑素体多样性。
统计分析表明，相较于颜色变量，更多环境变量能够在一定程度上解释黑素体几何形态特征，但无论是环境变量还是颜色变量，其总体解释能力均较有限。研究指出，由于不同哺乳动物谱系之间存在明显的演化差异，基于黑素体形态直接预测化石哺乳动物体色应保持谨慎。此外，哺乳动物中黑素体几何形态与颜色之间可能受到相对较弱的自然选择约束，或与其他生活史特征存在相关性，这些因素均可能共同影响黑素体形态的演化过程。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['黑素体'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"泮燕红","en_name":"","@id":"c33ef7c0-6a77-4dbf-827f-92a44e03262d","email":"panyanhong@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 90042, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":90042,"name":"zip"}]'::jsonb, '泮燕红', 'panyanhong@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('b61da5b0121c4a7a81b3e2d459e8d647', 'd7c6b349015147b2a28efd955f1f9111', '石炭纪—二叠纪烃源岩U–Pb同位素数据集', '', '数据集来源：论文《准噶尔盆地及其周缘石炭纪—二叠纪烃源岩高分辨率年代地层格架与时空演化》
数据集类型：准噶尔盆地的石炭纪—二叠纪烃源岩火山灰层中锆石U–Pb年代学数据
数据集研究摘要：准噶尔盆地及邻区广泛发育的石炭纪—二叠纪烃源岩记录了古亚洲洋最终闭合的重要地质信息。该套地层形成于海相向陆相过渡环境，并因缺乏典型海相标准化石而导致年代地层对比长期存在较大不确定性。精确时间框架的缺失不仅制约了含油气层系之间的区域对比，也限制了盆地构造—地层演化过程的深入认识。为此，本文针对准噶尔盆地西北缘、南缘及东缘，以及邻区吐哈盆地、三塘湖盆地和伊犁盆地关键石炭纪—二叠纪剖面与钻孔中的火山灰层，系统开展了锆石U–Pb年代学研究。通过高精度CA-ID-TIMS、SIMS及LA-ICP-MS等定年技术，共获得53组火山灰层U–Pb年龄数据，首次为多套关键烃源岩层段建立了可靠的年代地层约束。
研究结果表明：（1）准噶尔盆地玛湖凹陷主要烃源岩——风城组形成于晚石炭世卡西莫夫期（Kasimovian）至早二叠世阿瑟尔期（Asselian）；（2）准南地区、吐哈盆地及三塘湖盆地主力烃源岩——芦草沟组/桃东沟组形成于萨克马尔期（Sakmarian）至阿尔丁斯克期（Artinskian），即早二叠世乌拉尔统（Cisuralian）；（3）伊犁盆地伊宁凹陷主要烃源岩——塔木其萨依组形成于Kungurian早期（晚乌拉尔世）；（4）准噶尔盆地东部平地泉组时代最可能为吴家坪期（Wuchiapingian，晚二叠世乐平统）。上述研究据此厘定出三个主要烃源岩发育阶段：Kasimovian–Asselian期、Sakmarian–Kungurian期及Wuchiapingian期。
新的高精度年代地层框架揭示出研究区海陆过渡过程具有明显穿时性特征，其发生时代自西北部（Kasimovian）向东逐渐变年轻（Gzhelian）', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['烃源岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"沈树忠","en_name":"","@id":"d2845e4a-e43f-48c5-8cb1-8c09d25a7fd1","email":"szshen@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 4322065, 4, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":4}]'::jsonb, '[{"storageNum":4322065,"name":"pdf"}]'::jsonb, '沈树忠', 'szshen@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('e81cca526e344eae9913b4e80d29468e', 'fd703cbaccd340bca5a92c5d81919bf9', '石炭纪—二叠纪䗴类有孔虫多样化数据集', NULL, '数据集来源：《全球降温驱动石炭纪—二叠纪䗴类有孔虫多样化，而变暖导致其灭绝》
数据集类型：石炭纪—二叠纪䗴类有孔虫全球尺度多样性重建数据
数据集研究摘要：化石记录是揭示地球生物多样性随时间演化的唯一直接证据。然而，在更高阶分类单元（如科、目）尺度上，由于不同演化谱系中生物性状与环境条件之间的复杂相互作用，多样性演化模式往往更加复杂。本文利用超级计算与人工智能算法，对石炭纪至二叠纪（约340–252 Ma）期间全球高分辨率纺锤虫（fusuline foraminifera）数据库进行了系统分析。纺锤虫是该时期最为多样化的海洋化石类群之一，本研究首次实现了时间分辨率优于4.5万年的全球尺度多样性重建。
研究结果显示，在这一保存极为完整的化石类群中，其未分箱（unbinned）多样性演化模式出乎意料地表现出较为简单的特征。研究识别出两次（可能还有第三次）被截断的指数型生物多样化过程，以及四次主要生物多样性衰退事件。在此期间，长期气候降温持续促进生物多样化，而气候变暖事件则与生物灭绝密切相关。上述结果表明，当前由人为CO2排放驱动的快速全球变暖，可能对现代生态系统构成严重威胁。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['有孔虫'], '[{"Organization":{"@type":"Organization","name":"南京大学","en_name":"Nanjing University","@id":"4dcddfe8b797476f9e75e381379d3849"},"@type":"Person","name":"史宇坤","en_name":"","@id":"87588ddd-3c3a-4e46-a030-b760cef7e07a","email":"ykshi@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"沈树忠","en_name":"","@id":"d2845e4a-e43f-48c5-8cb1-8c09d25a7fd1","email":"szshen@nju.edu.cn"}]'::jsonb, '南京大学', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 3573601, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":3573601,"name":"pdf"}]'::jsonb, '沈树忠', 'szshen@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('81c671929d60425da1164f36412ef9da', 'f78d846adc4a4c4d9f6d93a0cd99d69f', '水圈中N2团簇同位素组成数据集', NULL, '数据集来源：论文《基于赛默飞超高分辨率同位素比质谱仪的 N₂ 团簇同位素测量及其在水圈中的应用》
数据集类型：大气N2中的15N15N丰度团簇同位素特征（Δ30）数据
数据集研究摘要：由于大气N2中的15N丰度相较于随机分布显著富集，其团簇同位素特征（Δ30）可作为示踪氮循环过程的重要指标。尽管该指标在环境与地质研究中具有重要意义，但由于15N15N在N2中含量极低，且传统同位素比值质谱（IRMS）无法有效分辨质量数30处的典型同量异位素干扰，因此Δ30的高精度测定长期面临技术挑战。本文利用新一代高分辨率同位素比值质谱仪（Thermo Fisher Scientific Ultra HR-IRMS）对N2团簇同位素组成进行了系统测试，并评估了同量异位素干扰效应。结果表明，在质量分辨率（MRP）约46,000条件下，当12C16O+/14N14N+与14N16O+/15N15N+强度比分别高于6.4 × 10−4和8时，测得Δ30值会出现明显正偏移，表明高纯度N2样品对于获得可靠测量结果至关重要。
为此，研究建立了一套结合冷阱与气相色谱（GC）的纯化系统，用于从不同样品基体中分离纯化N2气体。利用该系统与Ultra HR-IRMS，研究分别分析了三种方法制备N2的Δ30值，包括：（1）Sr3N2催化重排反应；（2）Sr3N2热分解；（3）KN3热分解。结果显示，尽管三种方法均能够产生同位素随机分布的N2，但KN3热分解获得的Δ30值最为稳定。基于随机分布N2标准，本文测得大气N2的Δ30值为19.4 ± 0.3‰（1SD），与此前利用Nu Instruments Panorama质谱仪获得的数据一致。
此外，研究还测定了湖泊溶解N2的Δ30值，其范围为12.9 ± 0.5‰至20.5 ± 0.5‰。相较于大气N2，湖泊溶解N2较低的Δ30值可能反映了其受到细菌反硝化作用（denitrification）和/或厌氧氨氧化作用（anammox）产生的生物成因N2混合影响。通过简单混合模型，研究进一步估算了生物成因N2的比例及其氮同位素组成（δ15N），从而为揭示水体中生物成因N2形成机制提供了新的约束。研究结果表明，溶解N2的团簇同位素组成有望成为追踪水圈氮循环过程的有效新指标。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['N₂ 团簇同位素'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"仝凤台","en_name":"","@id":"a49398fe-95d6-4b61-a1d7-190c6e9b5177","email":"tongft@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 632793, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":632793,"name":"pdf"}]'::jsonb, '仝凤台', 'tongft@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('d1951df3d0384834b000b70bc0f431a4', '55ae0ec77df048689af81cb43f191eac', '达克质与低 Sr/Y 花岗岩地球化学数据集', NULL, '数据集来源：论文《东天山三叠纪陆内地壳再造：来自博格达地区晚三叠世埃达克质与低 Sr/Y 花岗岩的新认识》
数据集类型：埃达克质斑岩与低Sr/Y花岗斑岩的主量元素、微量元素、U–Pb定年的数据
数据集研究摘要：大陆板内岩浆作用（continental intraplate magmatism）一直是板块构造理论中的重要科学问题。三叠纪岩浆活动作为中亚造山带（Central Asian Orogenic Belt）演化过程中的关键阶段，其形成构造背景至今仍存在广泛争议。本文针对博格达山（Bogda Range）新发现的两类三叠纪花岗质岩石——埃达克质斑岩（adakitic porphyry）与低Sr/Y花岗斑岩（low-Sr/Y granite porphyry）——开展了系统的野外地质、岩相学、年代学、地球化学及同位素研究。锆石U–Pb定年结果显示，两类岩石形成时代接近，分别为221–220 Ma与219–217 Ma。
两类花岗质岩石均具有高SiO2与高K2O含量、低MgO（Mg#）及低Ni含量，同时表现出较高K2O/Na2O与Th/Nb比值；其全岩Sr–Nd及锆石Hf同位素组成整体表现为亏损特征，指示其主要来源于年轻地壳物质。埃达克质斑岩具有高Sr/Y与高(La/Yb)N比值、低Rb/Sr比值及弱Eu负异常，表明其源区为石榴子石稳定条件下的镁铁质下地壳；相比之下，低Sr/Y花岗斑岩则具有较低Sr/Y与(La/Yb)N比值，指示其来源于斜长石稳定条件下的源区。
结合区域已有研究成果，本文认为东天山地区三叠纪岩浆作用的多样性主要源于不同深度与温度条件下年轻地壳与古老地壳的再造（reworking）过程，从而形成具有岛弧特征的地球化学组成。这一过程与大陆板内环境下的走滑构造活动（transcurrent tectonics）及不同程度地幔物质参与密切相关。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['花岗岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王博","en_name":"","@id":"ff693092-329d-4c02-8450-aa710451abaa","email":"bwang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 2172297, 7, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":6},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":546344,"name":"xlsx"},{"storageNum":1625953,"name":"docx"}]'::jsonb, '王博', 'bwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('75882c5ecdb540c59b234edde7c7b103', '3a124e956faf40b58798895beb6962c4', '中国西北部中天山地区混合岩古地磁数据集', NULL, '数据集来源：论文《磁组构与磁剩磁的解耦：来自中天山混合岩的启示》
数据集类型：中国西北部中天山地区混合岩的岩相学、年代学、岩石磁学、磁化率各向异性（AMS）及古地磁数据
数据集研究摘要：磁组构（magnetic fabrics）与磁剩磁（magnetic remanences）之间的耦合关系，对于古地磁数据解释具有重要意义。为了评估原生磁组构是否对应原生磁剩磁，并探讨变质岩在磁学研究中的适用性，本文针对中国西北部中天山地区混合岩（migmatites）开展了系统的岩相学、年代学、岩石磁学、磁化率各向异性（AMS）及古地磁研究。岩石学观察表明，混合岩形成后未经历显著的动力重结晶作用。原位独居石U–Pb定年结果显示，混合岩化作用发生于约314–297 Ma。岩石磁学结果表明，混合岩磁性主要由黑云母控制，并伴有少量钛磁铁矿贡献。尽管混合岩具有复杂的结构与矿物组成，但其磁组构表现出较为简单的特征，即磁面理高度集中而磁线理相对分散。磁各向异性强度及形态参数从浅色体（leucosome）、中间体（mesosome）到暗色体（melanosome）发生显著变化，表明磁组构形成于混合岩化过程中。
古地磁分析从约四分之一样品中分离出特征剩磁方向，其表现出异常浅的磁倾角。结合中天山及邻区已有年代学与古地磁资料，研究认为混合岩中的磁剩磁形成于约314–303 Ma，晚于磁组构形成时间，可能与后期热剩磁重置（thermal remagnetization）或混合岩构造折返过程中长期渐进式磁化作用有关。该研究提供了一个较为罕见但重要的实例，揭示磁组构与磁剩磁之间可能发生解耦现象。同时，研究结果也表明，混合岩可作为开展磁组构与古地磁研究的有效研究对象。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['磁剩磁'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王博","en_name":"","@id":"ff693092-329d-4c02-8450-aa710451abaa","email":"bwang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 103074, 3, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":2},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":48580,"name":"xlsx"},{"storageNum":54494,"name":"docx"}]'::jsonb, '王博', 'bwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('f44a3c3afeaa452388336a7892f5d30c', '96bc7e88fbe547899070ca94bd06426f', '非克拉通大陆岩石圈地幔水含量数据集', NULL, '数据集来源：《部分熔融控制的非克拉通大陆岩石圈地幔水含量——以蒙古塔里亚特地区为例》
数据集类型：非克拉通大陆岩石圈地幔橄榄石等矿物的水含量数据
数据集研究摘要：部分熔融作用对岩石圈地幔中水分布的影响，常常会被后期交代作用（metasomatism）所掩盖。本文针对蒙古中部晚新生代Shavaryn-Tsaram喷发中心的16件二辉橄榄岩捕虏体，系统测定了其中名义无水矿物（NAMs）的氢含量。已有大量研究表明，这些样品几乎未受到后期熔融后过程（如交代作用）的影响，或仅受到极弱改造。研究发现，各NAMs矿物核部均表现出均一的氢扩散剖面，能够较好记录其源区原位水含量：橄榄石中H含量为0.6–13 ppm（平均6 ± 4 ppm），斜方辉石为41–140 ppm（平均100 ± 32 ppm），单斜辉石为80–320 ppm（平均190 ± 63 ppm）。这些样品经历了不同程度的部分熔融（F），并在随后于岩石圈地幔亚固相条件下达到矿物间化学平衡（包括水的再平衡）。
研究结果显示，对于相对亏损样品（F > 0.05），NAMs中水含量与部分熔融指标之间具有明显相关性；而对于相对肥沃样品（F < 0.05），这种相关关系则并不明显。平衡熔融模拟表明，亏损样品形成于3–4 GPa条件下、初始含水量为330–750 ppm的地幔源区部分熔融；而肥沃样品则代表约1 GPa条件下、初始含水量为50–200 ppm的大洋中脊玄武岩（MORB）源区地幔的熔融残余。部分Shavaryn-Tsaram捕虏体经历了交代作用导致的Fe富集，但这一过程并未显著扰动其水含量。基于此，研究认为，不同程度的部分熔融作用能够叠加并改造地幔中原始非均一水分布，而增生造山带中非克拉通型岩石圈地幔整体可能属于贫水地幔。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['大洋俯冲带'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王勤","en_name":"","@id":"f65912ea-c6f1-4201-8f71-b33533ccb08b","email":"qwang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 65912, 3, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":3}]'::jsonb, '[{"storageNum":65912,"name":"xlsx"}]'::jsonb, '王勤', 'qwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('471ab9aac7e243b6b0787f1a53ca4bb5', '991b865a35794182904664e28de12534', '橄榄岩蛇纹石化地震反射特征数据集', NULL, '数据集来源：论文《快速与中速扩张洋脊壳幔边界的结构、蛇纹石化与地震反射特征》
数据集类型：不同蛇纹石化类型条件下尖锐型或层状壳幔边界的地震速度与密度模型数据
数据集研究摘要：快速扩张与中等扩张洋中脊下方复杂莫霍面（Moho）反射机制长期尚不明确，其中热液活动可能是关键控制因素之一。在洋中脊环境下，热液作用可导致地幔橄榄岩发生蛇纹石化，并在不同温度条件下形成不同类型蛇纹石矿物：400–600°C条件下主要形成抗蛇纹石（antigorite），而低于400°C时则以温石棉—利蛇纹石（chrysotile-lizardite）为主。本文在200 MPa条件下标定了橄榄岩蛇纹石化程度与其密度、地震波速度之间的关系，并基于洋壳—岩石圈典型岩石物性参数，建立了不同蛇纹石化类型条件下尖锐型或层状壳幔边界的地震速度与密度模型。合成地震记录结果表明，洋壳莫霍面反射特征同时受壳幔边界结构及蛇纹石化作用共同控制。脉冲型（impulsive）Moho反射可对应于蛇纹石化程度低于10%的尖锐镁铁质—超镁铁质边界（即岩石学Moho），或对应于60%–80%抗蛇纹石化橄榄岩底界；当尖锐壳幔边界之下上地幔顶部抗蛇纹石含量由60%–80%逐渐降低至0%时，Moho反射会逐渐消失。除层状壳幔边界外，弥散型（diffusive）Moho反射还可能由尖锐镁铁质—超镁铁质边界伴随10%–60%或80%–100%抗蛇纹石化橄榄岩形成，或者由温石棉—利蛇纹石化橄榄岩覆盖于抗蛇纹石化橄榄岩之上所导致。结合合成地震记录分析，东太平洋海隆（East Pacific Rise）9°44′N以西6–9 km范围内观测到的弥散型Moho，可由约30%抗蛇纹石化橄榄岩解释，指示快速扩张洋中脊附近存在局部化热液循环过程。研究表明，洋中脊地区的Moho反射及广角PmP波形能够为揭示洋壳岩石圈中岩浆作用、构造活动与热液过程之间的耦合关系提供新的地球物理约束。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['扩张洋脊'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王勤","en_name":"","@id":"f65912ea-c6f1-4201-8f71-b33533ccb08b","email":"qwang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 5414880, 3, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":3}]'::jsonb, '[{"storageNum":5414880,"name":"docx"}]'::jsonb, '王勤', 'qwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('4f4fe8f1dcf74887ba6101b8e7002a28', 'accdd504ec3843628dc9282bb37b2547', '华北白云鄂博超大型 Fe-Nb-REE 矿床矿物数据', NULL, '数据集来源：论文《华北白云鄂博超大型 Fe-Nb-REE 矿床中的锡石与锡成矿作用》
数据集类型：中国北方白云鄂博Fe–Nb–REE矿床矿物U–Th–Pb定年结果数据
数据集研究摘要：关键稀有金属矿床是支撑高技术产业发展的重要战略资源。其中，锡（Sn）作为关键稀有金属之一，自然界中主要以锡石（cassiterite，SnO2）形式存在，并通常与花岗岩或伟晶岩密切相关；相比之下，碳酸岩及碱性岩则更易富集稀土元素（REE）和铌（Nb）等关键金属。本文首次在中国北方白云鄂博Fe–Nb–REE矿床——全球最大的稀土矿床——中发现显著锡富集现象及大量锡石矿物，为碳酸岩型稀土矿床中存在Sn矿化提供了新的证据。研究表明，白云鄂博REE–Fe矿石中普遍含有数十至数百ppm的Sn，而脉状矿石中Sn含量最高可达1500 ppm。原位微区矿物学分析识别出两类锡石及多种富Sn矿物：在条带状和块状REE–Fe矿石中，磁铁矿内部发育大量早期纳米级锡石包裹体；而在脉状REE–Fe矿石中，则广泛出现晚期粒状锡石、富Sn金红石、榍石及钡铁硅钛矿（bafertisite）等矿物。与锡石共生的独居石及锰铌铁矿（columbite-Mn）U–Th–Pb定年结果分别获得425 Ma及419 ± 18 Ma峰值年龄，表明Sn与Nb矿化基本同期形成。研究认为，Sn主要来源于碳酸岩岩浆，磁铁矿中高密度锡石包裹体记录了白云鄂博矿床Sn的早期预富集过程，而后续早古生代热液事件则导致Sn再次活化并进一步富集成矿。类似于Nb，Sn在白云鄂博矿床中也可能形成具有经济价值的重要资源，研究进一步揭示了碳酸岩型REE矿床具有潜在Sn矿化的重要找矿前景。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['白云鄂博'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王汝成","en_name":"","@id":"58f498c1-134c-4542-9a73-6eb163da04c6","email":"rcwang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1275396, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":1275396,"name":"xlsx"}]'::jsonb, '王汝成', 'rcwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('b3c0ebb202a2437c8a4e28147bf72e17', 'fa9cb8ba721440efb52c10ed3bef321e', '中国积雪特性时空分布电子地图数据集', 'Electronic map data set of temporal and spatial distribution of snow cover characteristics in China', '本数据集基于地面和遥感调查数据以及积雪类型划分的成果数据，编制中国积雪类型系列图件，包括积雪密度（2017-2020年）、积雪日数（1980-2020年）、积雪深度/雪水当量（1980-2020年）和积雪反照率（2000-2020年）。所有图件均以1:100万/1:50万的数字地形图为基础地理底图，根据需要叠置中国气候区划图或土地利用/覆盖图作为背景图层。设计分级与制图符号表示方法，编制1:100万（积雪密度、积雪深度/雪水当量）/1:50万（积雪日数、积雪反照率）的中国积雪类型系列图件。数据集采用分层设色的分级方式定量表达积雪专题要素的时空分布特征，分层以积雪要素的特征和统计直方图为标准，以成图信息量最大为原则；为了更好地进行表达，设计积雪密度为紫色系、积雪日数为绿色系、积雪深度/雪水当量为蓝色系、积雪反照率为红色系。数据集以CGCS2000为坐标系统，采用正轴等角圆锥投影，参照国家测绘地理信息部门公布的标准地图（审图号：GS（2019）1815号）绘制国界。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['积雪密度','时空分布','积雪反照率'], '[{"Organization":{"@type":"Organization","name":"南京大学","en_name":"Nanjing University","@id":"4dcddfe8b797476f9e75e381379d3849"},"@type":"Person","name":"张学良","en_name":"","@id":"6e6540aa-8aa2-4c7b-8ab5-054d36fc02ef","email":"zxl@nju.edu.cn"}]'::jsonb, '南京大学', NULL, NULL, NULL, 'CC BY 4.0', 'open', NULL, 29931776830, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/b3c0ebb202a2437c8a4e28147bf72e17.png', '[{"name":"rar","count":1}]'::jsonb, '[{"storageNum":29931776830,"name":"rar"}]'::jsonb, '张学良', 'zxl@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('6cc5dfbdbede45298c33fb9d16f1c582', '344cdfc0b14846c7a4155fbacc2cbc52', '越南东北部晚白垩世花岗岩地球化学数据集', NULL, '数据集来源：论文《越南东北部晚白垩世花岗质岩浆作用与 W-Sn 成矿：与华南西南部的异同》
数据集类型：越南东北部天溪花岗岩的主量元素、微量元素、同位素比值数据
数据集研究摘要：越南东北部广泛发育晚白垩世花岗质岩浆活动及与之成因相关的W–Sn矿化。锆石U–Pb年代学结果表明，天溪（Thien Ke）花岗岩形成于89–87 Ma，大连（Da Lien）花岗岩形成于89–88 Ma，其时代与越南东北部漂凹（Pia Oac）花岗岩及中国华南西南部大量晚白垩世花岗岩基本同期。锡石U–Pb定年进一步限定天溪钨矿床成矿时代约为82 Ma，表明从高温岩浆活动到低温矿化过程经历了约5–7 Ma的演化；相比之下，Nui Phao钨多金属矿床的形成则与大连花岗岩侵位几乎同期，反映其属于高温岩浆热液成矿作用。
这些花岗岩均具有较高A/CNK值（>1.1）、较高K2O/Na2O、Rb/Sr及Rb/Ba比值，以及较低CaO/Na2O比值（<0.3），并表现出变化范围较大的锆石Hf同位素组成［εHf(t) = −6.0至−14.2］，整体显示典型S型花岗岩特征。结合基底变质岩地球化学与Hf同位素组成分析，研究认为越南东北部晚白垩世花岗岩主要来源于新元古代泥质沉积岩（metapelitic sedimentary rocks）的部分熔融。
尽管越南东北部晚白垩世花岗岩在S型花岗岩地球化学特征、形成时代及相关稀有金属矿化方面与中国华南西南部同期花岗岩具有相似性，但后者在整体岩石成分上更加复杂，岩浆活动持续时间更长，且矿床类型存在明显差异。越南东北部晚白垩世花岗岩通常与钨多金属矿化有关，而中国华南西南部同期花岗岩则主要与大型锡多金属矿化相关。研究认为，两地区矿床类型差异主要受源区Sn、W丰度、源岩类型（泥质岩/砂质岩）及部分熔融条件不同所控制。华南西南部富Sn砂质源岩在高温条件下部分熔融，形成富Sn岩浆；而越南东北部富W泥质源岩则在较低温度条件下发生部分熔融，从而形成富W熔体。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['花岗质岩浆作用'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王汝成","en_name":"","@id":"58f498c1-134c-4542-9a73-6eb163da04c6","email":"rcwang@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"于津海","en_name":"","@id":"52222868-f181-4ca2-84a6-5a8bffd96230","email":"jhyu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 571552, 7, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":2},{"name":"xls","count":4},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":169269,"name":"xlsx"},{"storageNum":378368,"name":"xls"},{"storageNum":23915,"name":"docx"}]'::jsonb, '王汝成', 'rcwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('dafc31f299f44851a0c39eaef77a4c95', '1719e4b22c45447d96180c090ae7bb22', '地球硅酸盐材料离子扩散系数与电导率数据集', NULL, '数据集来源：论文《通过地球硅酸盐材料的扩散性和电导率实验区分离子迁移率》
数据集类型：地球硅酸盐材料的Na、F和H三种典型离子中活化能、各向异性行为以及扩散系数与电导率特征数据
数据集研究摘要：离子扩散系数（ionic diffusivity）与电导率（electrical conductivity）是地球硅酸盐物质（包括熔体与矿物）两种重要的输运性质，被广泛用于约束地球内部的多种化学与物理过程。由于两者均与离子迁移能力密切相关，长期以来通常认为它们之间存在内在成因联系，即其输运机制与相关参数具有相似性或可比性。本文系统研究了Na、F和H三种典型离子在一系列地球硅酸盐物质中的活化能、各向异性行为以及扩散系数与电导率特征，结果表明这两类输运性质之间实际上存在显著差异。
作者进一步评估了物理学与材料科学中常用于建立扩散与导电关系的理论模型，指出该类理论主要适用于组成简单且理想化的材料，而地球内部硅酸盐体系成分复杂、化学键类型多样且组分间相互作用强烈，因此这些模型并不总适用于天然硅酸盐物质。此外，对已有扩散与导电实验研究的系统分析表明，两类实验在样品性质与分析方法上存在本质区别。扩散实验中，为获得可测扩散剖面，样品通常具有成分非均一性，并存在明显化学势或同位素势梯度，在实验过程中带电离子会发生净迁移；而电导实验中，样品通常保持成分均一，不涉及势梯度，也不存在带电离子的净迁移，例如广泛应用于硅酸盐导电研究的阻抗谱分析即属于此类情况。
因此，地球硅酸盐物质扩散与导电行为之间实验上所观察到的差异，更可能源于理论基础及实验条件本身的不同，而非简单反映同一离子迁移机制。在硅酸盐样品中，同一种带电离子在扩散实验与导电实验中的迁移行为实际上存在显著差异。基于此，作者认为实验获得的扩散系数与电导率不能被简单直接地进行比较或建立线性关联。同时，文章还简要讨论了在特定条件下两种输运性质可能建立联系的潜在情形，为理解地球深部硅酸盐物质的输运机制提供了新的认识。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['硅酸盐材料'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨晓志","en_name":"","@id":"1cd7d3ff-8199-497c-be2e-372431cb4bc0","email":"xzyang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 689231, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":689231,"name":"pdf"}]'::jsonb, '杨晓志', 'xzyang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('4f25f04ff0f544a28d65db303cd42d77', '4b081b9f3e334d03a69cd73854db9de1', '南海新生代碳酸盐岩地球化学同位素数据', NULL, '数据集来源：论文《矿物组成与早期成岩作用对南海新生代碳酸盐 Ca-Mg 同位素记录的影响》
数据集类型：海相碳酸盐岩中的主量元素、微量元素与δ44/40Ca与δ26Mg值等同位素数据
数据集研究摘要：海相碳酸盐岩中的δ44/40Ca与δ26Mg值被广泛用于重建古海水化学组成。然而，沉积后成岩作用常会改变其原始地球化学信号，从而导致古海洋环境解释产生偏差。本文以南海NK-1钻孔晚新生代碳酸盐岩为研究对象，通过C–O–Mg–Ca多同位素体系分析，系统评估了大气淡水成岩作用与海相成岩作用对Ca、Mg同位素组成的影响。
研究结果表明，钻孔顶部未固结碳酸盐沉积物（0–20 m）主要由文石与高镁方解石组成，其平均δ44/40Ca值为0.84‰（相对于NIST SRM-915a），δ26Mg值为−3.07‰（相对于DSM-3）。在淡水成岩带（20–120 m、443–503 m及539–670 m）内，石灰岩δ44/40Ca值介于0.57‰–1.46‰之间，δ26Mg值介于−5.02‰至−2.98‰之间，并与δ13C和δ18O值呈明显正相关关系。早期成岩数值模拟结果表明，在淡水成岩过程中，石灰岩δ44/40Ca与δ26Mg值整体降低，其变化主要受淡水与海水混合比例控制。相比之下，海相成岩带（670–700 m）内石灰岩表现出较高且相对稳定的δ44/40Ca（约1.48‰）与δ26Mg（约−4.08‰）值，同时伴随较高δ13C和δ18O值，指示其形成于受海水缓冲控制的成岩环境。
白云岩样品则表现出较高的δ44/40Ca值（1.39 ± 0.15‰）及相对一致的δ26Mg值（−2.85 ± 0.12‰），表明白云石化作用发生于流体缓冲条件下。基于NK-1钻孔白云岩重建的晚新生代海水Ca与Mg同位素组成，与全球同期白云岩及其他代用指标（如碳酸盐软泥、有孔虫及重晶石）记录结果高度一致。这表明准同生白云岩（penecontemporaneous dolomite）能够较好保存古海水Ca与Mg同位素组成信息，是重建古海洋化学演化的重要可靠载体。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['Ca-Mg 同位素'], '[{"Organization":{"@type":"Organization","name":"南京大学","en_name":"Nanjing University","@id":"4dcddfe8b797476f9e75e381379d3849"},"@type":"Person","name":"王向东","en_name":"","@id":"ea0aec2b-32a9-4ddd-9616-12fed0bb681c","email":"xdwang@nju.edu.cn"}]'::jsonb, '南京大学', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 12796, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":12796,"name":"docx"}]'::jsonb, '王向东', 'xdwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('722de4e0452743a594ac99c2c74a7244', '39a8bfabb65745ee879721ecfa745819', '碎屑磷灰石单颗粒双重定年技术数据集', NULL, '数据集来源：论文《碎屑磷灰石裂变径迹年龄反转模式：活动盆山体系中断层驱动沉积再循环的诊断标志》
数据集类型：碎屑磷灰石裂变径迹（AFT）与U–Pb年代学分析数据
数据集研究摘要：沉积物再循环过程对于示踪物源演化及揭示盆—山系统构造演化具有重要意义，并能够为造山带动力学过程提供关键约束。然而，在构造响应迅速的盆—山系统中，由于沉积物再循环通常具有搬运距离短、源区变化有限等特征，传统岩石学与地球化学方法往往难以有效区分再循环物质来源。本文以中国中北部构造持续沉降的渭河盆地连续沉积地层为研究对象，利用高分辨率沉积记录重建区域构造活动过程。研究结合碎屑磷灰石单颗粒双重定年技术，即裂变径迹（AFT）与U–Pb年代学分析，在盆地始新世地层中识别出一种特征性的AFT“年龄反转趋势”模式。该年龄结构贯穿整个沉积阶段，并显示出碎屑矿物冷却历史与盆地演化之间良好的时空耦合关系。
研究发现，尽管碎屑磷灰石U–Pb年龄组分整体保持稳定，但在约38 Ma年龄反转趋势的拐点处，年轻年龄组分比例明显下降。这一变化与沉积速率显著增加同步发生，表明新的断裂活动是驱动沉积物再循环的重要机制。盆地控边断裂系统中新生断裂的形成，引发盆地边缘断块上升及剥蚀作用增强，从而导致邻近边缘沉积物再次进入盆地沉积体系。基于此，研究提出由碎屑低温热年代学记录的AFT“年龄反转趋势”可作为不同构造背景下断裂控制型沉积物再循环的有效识别标志。该成果不仅为断裂系统演化建立了可靠时间框架，也进一步揭示了盆—山耦合演化的复杂机制，为区域盆地—造山带相互作用研究提供了新的认识。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['碎屑磷灰石'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李广伟","en_name":"","@id":"6ec5af19-641f-4f9d-b6e9-ae65ae2aa06b","email":"guangweili@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 2611895, 5, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":4},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":669708,"name":"xlsx"},{"storageNum":1942187,"name":"docx"}]'::jsonb, '李广伟', 'guangweili@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('8468acbd36fa4127a24da199df1013bc', '739b651ea3034d26ba3e36072656a78f', '华南四川盆地中部埃迪卡拉纪白云岩储层流体包裹体数据集', NULL, '数据集来源：《流体包裹体记录高温储层中异常低成熟度原油及烃演化过程》
数据集类型：华南四川盆地中部埃迪卡拉纪白云岩储层中的流体包裹体镜质体反射率当量等演变数据
数据集研究摘要：烃类演化是全球有机碳循环的重要组成部分，并控制着地壳中不同烃类相态的分布。然而，由于缺乏可靠地质记录，烃类相态演化路径及其边界条件长期以来仍缺乏有效约束。本文针对华南四川盆地中部埃迪卡拉纪白云岩储层中的流体包裹体开展研究，识别出一套依次捕获的油包裹体、湿气包裹体［C1/ΣC1−5 = 0.74 ± 0.03–0.91 ± 0.01］及干气包裹体［C1/ΣC1−5 = 0.96 ± 0.01–1］组合，从而为原位烃类相态演化路径及形成条件提供了直接证据。
值得注意的是，早期捕获的油包裹体（约247 Ma）表现出异常低成熟度（0.75%–0.97%），明显低于储层固体沥青（pyrobitumen）的镜质体反射率当量（2.67%–2.79% VRE）。研究认为，该类油包裹体的形成主要受三种过程共同控制：（1）包裹体内原油裂解导致压力持续升高；（2）挥发性组分在包裹体爆裂（decrepitation）过程中发生泄漏；（3）重新平衡后的油包裹体中保留了较重烃组分。与此同时，储层原油则经历原位热裂解，并随着温度升高依次演化为湿气（约197 Ma）及干气（约116 Ma）。在这一过程中，识别出一种由流体超压形成与释放构成的自调节机制，例如197–182 Ma期间超压约为59–86 MPa，而116–109 Ma期间可达114–151 MPa，该机制有效促进了含烃流体运移。
结合共生水溶液包裹体分析及埋藏史恢复研究，进一步限定了长期持续加热条件下油藏与湿气藏的保存窗口，其中原油保存温度上限约为156°C，湿气保存温度上限约为213°C。上述研究成果为理解深部储层中烃类相态演化机制及深层油气勘探提供了新的认识与理论依据。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['异常低成熟度原油'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王小林","en_name":"","@id":"ed1dcde6-6b2c-46c5-9b02-89fb8621a9b0","email":"xlinwang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 949940, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":949940,"name":"docx"}]'::jsonb, '王小林', 'xlinwang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('b9ab490347cf45b8867addfd7d38d5c3', '7572549e756d489cb8dc6efc47c37850', '磷灰石离子质谱标准物质组成数据集', NULL, '数据集来源：论文《利用 CAMECA 1300HR3 LG-SIMS 原位微束磷灰石 U-Pb 定年》
数据集类型：三种磷灰石标准物质（BR5、AFG2和Otter Lake）的二次离子质谱微束原位分析与设置条件数据
数据集研究摘要：磷灰石（apatite）是一种常见于行星物质中的含U矿物，已被广泛应用于年代学研究。然而，由于微小粒径磷灰石（<15 μm）通常具有较低的U及放射成因Pb含量，对其开展高精度原位U–Pb定年仍面临较大挑战。为解决这一问题，本研究基于三种磷灰石标准物质（BR5、AFG2和Otter Lake），利用CAMECA IMS 1300HR3大几何二次离子质谱（LG-SIMS），建立了两种微束原位分析方法，即5 nA与500 pA初级离子束分析方案。
其中，5 nA方法（mono模式）形成较大的溅射坑（约12.5 × 12.5 × 4.1 μm），可获得更高定年精度：BR5年龄误差（n = 20）小于0.5%（1σ），AFG2小于2.5%（1σ），Otter Lake小于0.7%（1σ）。相比之下，500 pA方法（multi模式）形成较小的溅射坑（约5.3 × 5.3 × 1.4 μm），虽具有更高空间分辨率，但定年精度相对较低，其年龄误差（n = 25）分别为：BR5小于1.3%（1σ），AFG2小于4.1%（1σ），Otter Lake小于1.8%（1σ）。两种方法均可在误差范围内获得准确年龄结果，适用于磷灰石U–Pb定年分析。
在数据处理方面，研究建议采用Pb/U–UO2/U校准方案，因为相比Pb/U–UO/U及Pb/UO–UO2/UO校准方法，该方案能够显著降低年龄偏差。本文建立的方法体系实现了微小磷灰石高精度原位U–Pb定年，为LG-SIMS技术在地外及地球磷灰石年代学研究中的应用拓展提供了重要技术支撑。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['磷灰石 U-Pb 定年'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王孝磊","en_name":"","@id":"fc5a07cc-2bb1-4abc-8b7f-07b59b9cd52f","email":"wxl@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1065494, 2, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":2}]'::jsonb, '[{"storageNum":1065494,"name":"pdf"}]'::jsonb, '王孝磊', 'wxl@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('d4c4562e7d88444a9023c6a76676e282', '54d77d8e7beb44e785f753c6851433cb', '重晶石二次离子质谱标准物质数据集', NULL, '数据集来源：论文《两种用于 SIMS 硫同位素分析的新重晶石标准物质：晶体学取向效应与均一性评估》
数据集类型：重晶石标准物质在二次离子质谱微区分析下硫同位素等标准条件的数据
数据集研究摘要：重晶石（barite）是重建地质历史时期硫循环演化的重要载体，其硫同位素组成（δ34S）的微尺度空间变化能够为重晶石沉淀过程提供关键约束。近年来，二次离子质谱（SIMS）微区分析技术已成为开展此类研究的重要手段，但高质量标准物质的建立仍是保证测试准确性的基础条件。尽管已有若干重晶石标准物质被用于SIMS分析，但晶体学取向对硫同位素测量结果潜在影响尚未得到系统评估；此外，开发具有不同硫同位素组成的新型原位重晶石标准物质，也将有助于不同实验室之间数据的对比与统一。
本研究结合电子背散射衍射（EBSD）与SIMS分析，对晶体学取向效应进行了系统研究。结果表明，在当前SIMS分析精度水平下，晶体学取向不会对重晶石硫同位素测定产生显著分析偏差。此外，研究建立了两种新的重晶石潜在标准物质——NJU-Ba-1与NJU-Ba-2，专门用于微束硫同位素分析。纹理学及主量元素组成表征显示，两种样品磨碎颗粒内部均不存在明显环带结构。气源同位素比值质谱（GS-IRMS）测试结果表明，NJU-Ba-1与NJU-Ba-2分别具有6.18 ± 0.34‰（2SD，N = 17）和14.16 ± 0.26‰（2SD，N = 9）的δ34SV-CDT标准值，从而扩展了微区分析研究中δ34S的校准范围。大量SIMS测试进一步显示，两种标准物质在颗粒间及颗粒内部均具有极高均一性，其中NJU-Ba-1的δ34S变化范围为0.36‰（2SD，N = 328），NJU-Ba-2为0.45‰（2SD，N = 343）。上述结果表明，NJU-Ba-1与NJU-Ba-2具有优异的均一性与稳定性，可作为高精度重晶石硫同位素微区分析研究的理想标准物质。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['重晶石'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王孝磊","en_name":"","@id":"fc5a07cc-2bb1-4abc-8b7f-07b59b9cd52f","email":"wxl@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 234521, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":234521,"name":"xlsx"}]'::jsonb, '王孝磊', 'wxl@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('c22ce2de20a64ad49c1a9d56f4d1188c', '4b86cdaf450348e38fc8f9f675b83283', '卡普瓦尔克拉通富钾花岗岩氧逸度与水含量数据集', NULL, '数据集来源：论文《停滞盖层向活动盖层转变过程中的构造增厚促进太古宙克拉通稳定化》
数据集类型：卡普瓦尔克拉通英云闪长岩—奥长花岗岩—花岗闪长岩的锆石氧逸度—含水量数据
数据集研究摘要：太古宙克拉通是地球上最古老且构造稳定的大陆地壳单元，其形成过程伴随着广泛的富钾花岗岩侵位，反映了大陆地壳组成的重要重组。然而，控制地壳组成转变及克拉通稳定化的机制仍存在较大争议。本文以卡普瓦尔克拉通（Kaapvaal Craton）东部约3.51–3.22 Ga的英云闪长岩—奥长花岗岩—花岗闪长岩（TTG）及约3.11–3.10 Ga富钾花岗岩为研究对象，利用新建立的锆石氧逸度—含水量计（zircon oxybarometer-hygrometer），揭示了岩浆fO2值与H2O含量自约3.51 Ga至3.22 Ga持续升高，并在3.10 Ga达到峰值，其数值不仅高于已知大多数太古宙花岗质岩石，而且接近现代造山带花岗岩水平。同时，岩浆结晶深度及地壳厚度也在3.11–3.10 Ga达到最大值。上述变化趋势反映出卡普瓦尔克拉通东部构造体制由“停滞盖层”（stagnant lid，3.66–3.23 Ga）向“活动盖层”（mobile lid，3.22–3.10 Ga）转变，这一认识还得到Hf–O同位素由亏损型向演化型特征转变的支持。热力学与地球化学模拟结果进一步表明，广泛发育的约3.11–3.10 Ga富钾花岗岩形成于地壳增厚背景下中—下地壳物质的部分熔融。研究认为，卡普瓦尔克拉通可能是全球最早经历由停滞盖层向活动盖层转换并发生构造增厚的克拉通之一，而这一过程可能对早期克拉通的稳定化与成熟化发挥了关键作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['太古宙克拉通'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王孝磊","en_name":"","@id":"fc5a07cc-2bb1-4abc-8b7f-07b59b9cd52f","email":"wxl@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1653965, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":1653965,"name":"xlsx"}]'::jsonb, '王孝磊', 'wxl@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('4fd95063ca7444aca024383ec5f77723', '4a6c402f70cf47ff836b28e9b7a026a7', '嫦娥五号月壤地球化学元素数据集', NULL, '数据集来源：论文《嫦娥五号月壤高 Mg 冲击玻璃珠前驱岩石可能具有地幔来源》
数据集类型：嫦娥五号月壤高 Mg 冲击玻璃珠的主量元素、微量元素等数据
数据集研究摘要：大多数月球撞击玻璃珠的化学组成通常反映了多种月壳组分的混合特征，包括月海玄武岩、高地岩石以及KREEP组分（富含K、REE〔稀土元素〕和P）。然而，在嫦娥五号（Chang’e-5）月壤样品中发现的少量玻璃珠具有异常高的MgO含量，表明其来源于一种不同于常见月壳岩石的特殊靶岩成分。这些高MgO玻璃珠形成时代较年轻，暗示其可能来源于富含辉石和橄榄石的超镁铁质靶岩在撞击作用下发生熔融形成。尽管这些靶岩可能代表月海玄武岩堆晶体、撞击熔融岩或Mg-suite岩石，但其组成特征与目前已采集的任何月球岩石类型均不完全一致。另一种可能性是，这些高Mg玻璃珠记录了月幔浅部物质，而这些地幔物质可能在雨海盆地（Imbrium Basin）形成事件过程中被撞击作用带至月球表面。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['嫦娥五号月壤'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王孝磊","en_name":"","@id":"fc5a07cc-2bb1-4abc-8b7f-07b59b9cd52f","email":"wxl@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 157068, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":157068,"name":"zip"}]'::jsonb, '王孝磊', 'wxl@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('795346b909c94765aa6eb437272ceafe', 'a242ec167e954795965dd034b99d6f00', '华南晚中生代岩浆活动二维地球动力学数值模拟数据集', NULL, '数据集来源：论文《岩石圈拆沉的长期演化控制华南晚中生代岩浆作用与盆地演化》
数据集类型：华南晚中生代岩浆活动二维地球动力学数值模拟岩石圈拆沉等活动的数据
数据集研究摘要：华南地块在晚中生代经历了复杂的构造活动，形成了类似“盆岭构造”（Basin and Range-style）的岩浆省以及广泛的岩石圈减薄现象。然而，其岩浆活动与盆地演化机制长期存在争议。本文利用二维地球动力学数值模拟，揭示了岩石圈拆沉（lithospheric delamination）对华南岩浆活动及地表响应过程的控制作用。研究表明，初始拆沉表现为两个拼合大陆块体汇聚边界处的下沉滴状体（downwelling drip），其形成受洋壳俯冲作用触发。在下沉滴状体周围，地幔上涌流提供了充足热源及伸展构造环境，从而促进长英质岩浆活动的形成。同时，下沉滴状体对岩石圈产生向下牵引作用，导致局部区域发生沉降，而周缘区域则因上涌地幔流导致地表隆升，从而形成典型的盆岭式构造格局。随着上涌地幔流持续扰动，后续拆沉滴状体逐渐向沿海地区迁移，并诱发大规模岩浆活动及地形变化。最终，华南岩石圈地幔下部（>70 km）被大规模拆除，并被高温软流圈物质所置换。拆沉作用的时空迁移特征与华南晚中生代岩浆活动及盆地演化的时空分布高度一致，表明华南岩石圈减薄主要通过长期持续的岩石圈拆沉过程完成。该“渐进式岩石圈拆沉模型”较好解释了伊泽奈岐板块（Izanagi Plate）长期俯冲背景下华南广泛发育盆岭式岩浆省的形成机制。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['岩石圈拆沉'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王孝磊","en_name":"","@id":"fc5a07cc-2bb1-4abc-8b7f-07b59b9cd52f","email":"wxl@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 39628, 2, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":2}]'::jsonb, '[{"storageNum":39628,"name":"docx"}]'::jsonb, '王孝磊', 'wxl@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('f68185ad091241ff880eca7fafcc1b9d', '2183cf52f8b4460cbe6e8684d3e3d716', '海盆环境铁锰结核钼同位素数据集', NULL, '数据集来源：论文《铁锰氧化物与海水之间的钼同位素分馏影响古代沉积同位素记录》
数据集类型：全球不同海盆的铁锰结核δ98Mo同位素分馏数据
数据集研究摘要：钼同位素（δ98Mo）作为古氧化还原环境（paleo-redox）示踪指标的有效应用，依赖于对各类钼汇（Mo sinks）中物质通量及同位素分馏过程的准确认识。然而，受限于早期研究中分析精度及样品数量不足，不同氧化性沉积物中δ98Mo变化规律尚缺乏系统检验。为此，本研究对采自全球不同海盆的铁锰结核开展了系统δ98Mo分析。结果显示，铁锰结核δ98Mo值变化范围较大（−0.95‰至−0.51‰），且δ98Mo与Mn/Fe比值之间存在明显负相关关系。经历海洋沉积物早期成岩过程中锰氧化物溶解—再沉淀作用的成岩型结核，相较于氢成型结核，表现出约0.3‰更低的δ98Mo值以及更高的Mo含量。研究认为，氧化性沉积环境中Mn氧化物与Fe氧化物相对比例的变化，以及海洋沉积物早期成岩作用，是控制氧化性Mo汇总体同位素分馏的重要因素。因此，古海洋Mn–Fe地球化学循环的演化能够显著影响沉积物δ98Mo记录，尤其在低氧的新元古代以前海洋环境中，这种影响可能更加突出。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['铁锰氧化物'], '[{"Organization":{"@type":"Organization","name":"南京大学","en_name":"Nanjing University","@id":"4dcddfe8b797476f9e75e381379d3849"},"@type":"Person","name":"魏广祎","en_name":"","@id":"5264007c-4070-4334-9fc2-9b658c0b0614","email":"guangyiwei@nju.edu.cn"}]'::jsonb, '南京大学', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 513854, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":513854,"name":"pdf"}]'::jsonb, '魏广祎', 'guangyiwei@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('f852d6612e13402a9f0b4564cc293fe7', 'ec74dc2f5bae456e84d6461d67836bd5', '东喜马拉雅透锂长石型伟晶岩地球化学数据集', NULL, '数据集来源：论文《东喜马拉雅发现透锂长石型伟晶岩及其对稀有金属成矿的意义》
数据集类型：喜马拉雅造山带伟晶岩锆石Hf含量、石榴子石锰铝榴石组分以及CGMs的Mn#值等数据
数据集研究摘要：喜马拉雅造山带广泛发育与Li矿化相关的淡色花岗岩岩体，包括普斯拉（Pusila）、吉隆（Gyirong）、洛扎（Lhozhag）及库曲（Kuqu）等地区。这些岩体相关伟晶岩通常富含锂辉石、透锂长石、锂云母及电气石等含Li矿物。近年来，在东喜马拉雅高乌（Gaowu）伟晶岩中也识别出明显Li富集现象。高乌地区发育两类伟晶岩，即以电气石伟晶岩（Tur Peg）为主、石榴子石伟晶岩（Grt Peg）为辅，它们同时侵入高乌花岗岩体及围岩——特提斯喜马拉雅沉积序列中的若切村群（Rouqiecun Group）。不同于喜马拉雅淡色花岗岩体系中常见的Li矿物类型，高乌电气石伟晶岩中发现了透锂长石（petalite），且其为唯一原生含Li矿物，而铁锂云母（zinnwaldite）及富Li白云母则属于次生含Li矿物。
从淡色花岗岩经电气石伟晶岩至石榴子石伟晶岩，电气石含量逐渐减少，而石榴子石与绿柱石含量逐渐增加，反映岩浆分异程度不断增强；这一过程同时伴随着锆石Hf含量（最高达18 wt% HfO2）、石榴子石锰铝榴石组分以及CGMs的Mn#值［Mn/(Mn+Fe)］显著升高，即逐渐接近锰铌铁矿端元组成。透锂长石的多种产状记录了岩浆—热液演化过程中不同阶段的结晶作用。依据Li铝硅酸盐矿物（如锂辉石、透锂长石及锂霞石等）受温压条件控制的结晶规律，研究认为高乌含透锂长石电气石伟晶岩形成于低压环境，并可能在STDS构造活动背景下浅部侵位。晚阶段出现的铁锂云母及富Li白云母则表明岩浆演化后期存在富Li–F热液流体。此外，绿柱石中较高的Li含量（最高约3800 ppm）显示其可作为喜马拉雅地区Li矿化潜力的重要指示标志，因为绿柱石是该区伟晶岩中最常见的副矿物之一。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['伟晶岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"谢磊","en_name":"","@id":"30c7b79e-dcb7-4a39-abd2-88dd775a82cf","email":"xielei@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 359700, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":359700,"name":"xlsx"}]'::jsonb, '谢磊', 'xielei@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('7aa6e0d982ee4328a8cb5349804be383', '4f791c1ded0f4ad99c0fed3e1afe457c', '基于OCO-2卫星XCO2观测反演的全球1°×1°陆地生态系统和海洋碳通量产品', 'Global 1°×1° terrestrial ecosystem and ocean carbon fluxes inferred from OCO-2 XCO2 retrievals', '本数据集是南京大学开发的基于卫星遥感的我国新一代全球碳同化系统（GCASv2）生产的产品。该系统采用集合卡尔曼滤波（EnSRF）同化算法，MOZART-4全球大气化学输送模型，1周的同化窗口和两步优化策略，通过同化OCO-2 XCO2 v11.2的数据，反演生成了全球1°×1°的每月的全球陆地生态系统和海洋碳通量产品。数据时间跨度从2014年9月到2024年12月，共124个月数据。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['陆地碳汇','海洋碳通量','卫星XCO2观测'], '[{"Organization":{"@type":"Organization","name":"南京大学","en_name":"Nanjing University","@id":"4dcddfe8b797476f9e75e381379d3849"},"@type":"Person","name":"江飞","en_name":"","@id":"48e635bb-31e4-4bf8-8e35-42a98a877ddc","email":"jiangf@nju.edu.cn"}]'::jsonb, '南京大学', NULL, NULL, NULL, 'CC BY 4.0', 'open', NULL, 96696320, 1, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/7aa6e0d982ee4328a8cb5349804be383.png', '[{"name":"posterior","count":1}]'::jsonb, '[{"storageNum":96696320,"name":"posterior"}]'::jsonb, '江飞', 'jiangf@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('8f6df7ba2ffb4480bcb3749d609e9380', '193f50af87af4f54be2b168d04853c63', '安徽黄山花岗岩矿物地球化学特征数据', NULL, '数据集来源：论文《安徽黄山花岗岩矿物学特征及其对稀有金属成矿的指示意义》
数据集类型：中国安徽南部黄山岩体粗粒斑状黑云母花岗岩（CPG）、中粒斑状黑云母花岗岩（MPG）及细粒斑状黑云母花岗岩的主量元素、微量元素等地球化学数据
数据集研究摘要：中国安徽南部黄山岩体由粗粒斑状黑云母花岗岩（CPG）、中粒斑状黑云母花岗岩（MPG）及细粒斑状黑云母花岗岩（FPG）三种主要岩性单元组成。依据其构造背景及地球化学特征，黄山岩体属于高度演化的A型花岗岩。尽管此前尚未报道该岩体存在稀有金属矿化，但本研究在黄山花岗岩中识别出显著的稀有金属元素与矿物富集现象。其典型副矿物包括富Li云母（主要为锂铁黑云母 Li-siderophyllite）、黄玉、Nb–Ta–W–Sn氧化物矿物及绿柱石等，均为稀有金属花岗岩的重要标志矿物。锆石U–Pb定年结果表明，三类岩石均形成于131–128 Ma。结合全岩微量元素地球化学变化趋势，即从CPG经MPG至FPG，Li、Rb、Cs及Nb含量逐渐升高，而稀土元素整体亏损，表明黄山岩体经历了连续的岩浆分异演化过程。其中，FPG表现出最高程度的岩浆演化特征，其依据包括：富Li–F的锂铁黑云母、高Ta#值［Ta/(Nb+Ta)原子比］的铌钽铁矿族矿物（CGMs）以及大量黄玉的出现。通过单晶X射线衍射、电子探针及拉曼光谱分析，在黄山岩体中识别出一系列Nb–Ta–W–Sn氧化物矿物，包括黑钨矿（ferberite）、罗斯沃斯基石（rossovskyite）、铌铁矿-（Fe）及锡石等。其中，罗斯沃斯基石具有较高Feox值［Fe3+/(Fe3++Fe2+)原子比］，最高可达0.70，此前仅见于蒙古阿尔泰伟晶岩；相比之下，CGMs具有较低Feox值（CPG和MPG中<0.2，FPG中<0.31），而黑钨矿和锡石则具有较高Feox值（分别为0.33–0.47和0.34–1.00）。这些氧化物矿物形成于岩浆—热液演化过程中，并受到氧化还原条件变化的显著控制。晚阶段岩浆演化过程中首先结晶形成岩浆成因CGMs，随后富W氧化性热液流体促使Fe2+向Fe3+、Sn2+向Sn4+转变，从而诱发罗斯沃斯基石及锡石沉淀。与此同时，在含黑钨矿样品中广泛出现的低碱、贫H2O绿柱石，则记录了氧化性热液流体中Be的富集过程。上述结果证实黄山岩体不仅存在岩浆期Nb–Ta矿化，还发育后期热液W–(Sn)–Be矿化。此外，该岩体的矿物学与成矿证据为其与邻近黄石垱钨矿化之间潜在成因联系提供了重要支持。结合灵山岩体与苏州岩体，黄山岩体进一步丰富了江南造山带稀有金属矿化带的研究实例。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['花岗岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"谢磊","en_name":"","@id":"30c7b79e-dcb7-4a39-abd2-88dd775a82cf","email":"xielei@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 139483, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":139483,"name":"xlsx"}]'::jsonb, '谢磊', 'xielei@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('bccd3eb1a81b4dccbc9387875ba98e4f', 'b85468ff813e4b87afddf1c1b1b29e2f', '喜马拉雅 NYF 型花岗伟晶岩矿物数据集', NULL, '数据集来源：论文《喜马拉雅 NYF 型花岗伟晶岩成因：来自中国康马穹窿含绿柱石伟晶岩副矿物的约束》
数据集类型：喜马拉雅 NYF 型花岗伟晶岩Hf锆石206Pb/238U年龄、εNd(t)值等地球化学数据
数据集研究摘要：康马穹窿位于特提斯—喜马拉雅淡色花岗岩带东段，其显著特征在于地表缺乏典型淡色花岗岩出露，但大量含绿柱石花岗伟晶岩脉（以下简称绿柱石伟晶岩）侵入于花岗质片麻岩围岩之中。不同于喜马拉雅地区常见的LCT型伟晶岩，康马绿柱石伟晶岩（伟晶岩Ⅰ）富含Nb–Y–Ti氧化物矿物及萤石等典型NYF型伟晶岩矿物组合；而伟晶岩Ⅱ则以大量绿柱石（约16 vol%）及富Ta氧化物矿物为特征。伟晶岩Ⅰ中普遍发育富Hf锆石（0.1 < Hf# < 0.5），而铪锆石（hafnon，Hf# > 0.5）仅见于伟晶岩Ⅱ，表明后者经历了极端分离结晶作用及强烈热液流体活动。年代学结果显示，绿柱石伟晶岩获得锆石206Pb/238U年龄、独居石208Pb/232Th年龄及白云母Rb–Sr等时线年龄均为26–25 Ma。伟晶岩中的锆石通常保留古生代继承核（约499 Ma），与围岩花岗质片麻岩年龄一致。然而，绿柱石伟晶岩εNd(t)值变化范围较宽（−16.8至−7.7），明显大于花岗质片麻岩较窄的εNd(t)范围（−12.1至−10.6）。据此，研究认为康马NYF型伟晶岩与后造山伸展环境下深部隐伏A型花岗岩具有成因联系，该花岗岩可能主要来源于高喜马拉雅结晶基底，并伴有一种具有亏损同位素特征的未定源区物质贡献；岩浆在侵位过程中还受到围岩花岗质片麻岩的混染作用。研究结果揭示了特提斯喜马拉雅地区一种特殊类型稀有金属伟晶岩的存在及其独特成因机制。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['花岗伟晶岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"谢磊","en_name":"","@id":"30c7b79e-dcb7-4a39-abd2-88dd775a82cf","email":"xielei@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 600355, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":600355,"name":"xlsx"}]'::jsonb, '谢磊', 'xielei@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('771db6a033444bd1bb7f8913124c8bac', '2683586f9586440285507370c9a43f73', '北山造山拼贴体公婆泉岛弧花岗岩地球化学数据集', NULL, '数据集来源：《北山造山拼贴体弓婆泉岛弧早古生代埃达克岩及相关花岗岩：俯冲背景的证据》
数据集类型：公婆泉岛弧花岗质岩石锆石U–Pb年代学、锆石Hf同位素及全岩Sr–Nd同位素的数据
数据集研究摘要：通过对北山造山拼贴体（BOC）公婆泉岛弧花岗质岩石开展锆石U–Pb年代学、锆石Hf同位素及全岩Sr–Nd同位素研究，厘定了公婆泉岛弧岩浆活动的时限及演化过程。锆石U–Pb定年结果表明，公婆泉埃达克质花岗岩形成于约450 Ma，是月牙山—西长井（YX）蛇绿混杂岩以北公婆泉岛弧最早期的埃达克质岩浆活动记录。其地球化学与同位素特征显示，该类埃达克质花岗岩主要来源于俯冲YX洋壳的部分熔融，并在岩浆上升过程中与较老陆壳物质发生混染，因此晚奥陶世埃达克质花岗岩可能记录了YX洋初始俯冲事件。石英闪长岩样品获得约441–442 Ma的锆石U–Pb年龄，并具有富集型Nd-Hf同位素组成，指示其来源于古老镁铁质下地壳的部分熔融。与此同时，二长花岗岩样品形成于约446 Ma，具有最高达+12.1的εHf(t)值，表明其主要由古老中地壳部分熔融形成，同时存在俯冲背景下亏损地幔来源岩浆的加入。早泥盆世（约416 Ma）二长花岗岩则表现出A型花岗岩地球化学特征，来源于演化程度较高的岩浆源区，并经历强烈分离结晶作用，形成于后碰撞构造环境。综合研究认为，YX洋向北初始俯冲开始于约450 Ma，随后在晚奥陶世至晚志留世期间进入主俯冲阶段；而早泥盆世A型二长花岗岩的出现则标志着后碰撞伸展环境的建立，代表公婆泉岛弧演化的终结。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['埃达克岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"徐夕生","en_name":"","@id":"9a3a1881-dc83-46bf-b543-cb46f0b5e9c1","email":"xsxu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 863736, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":863736,"name":"docx"}]'::jsonb, '徐夕生', 'xsxu@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('98edad1147e74c439e01b5f2b2ce7f45', '260b850d84304c72b69515dccbcc165d', '富金属黑色页岩Ni-Mo 同位素数据集', NULL, '数据集来源：论文《Ni-Mo 同位素示踪早寒武世氧化还原转变期间海洋金属循环：富金属黑色页岩作为古环境档案》
数据集类型：华南早寒武世松林剖面δ98Mo–δ60Ni同位素数据
数据集研究摘要：富镍—钼（Ni-Mo）金属黑色页岩因富集Ni、Mo等痕量金属元素，是重建古海洋环境演化与金属循环过程的重要地质载体。尽管已有多种成矿模式被提出，但Ni-Mo矿化形成机制仍存在较大争议，尤其缺乏基于连续地层剖面及古环境背景约束的系统研究。为此，本研究针对华南早寒武世松林剖面开展δ98Mo–δ60Ni耦合同位素分析，并结合多指标地球化学参数，同时与遵义、纳雍及张家界等三个典型Ni-Mo富集沉积进行对比研究。结果显示，δ98Mo值介于−0.3‰至+2.1‰之间，δ60Ni值介于−0.4‰至+0.8‰之间，两者呈显著正相关关系（R² = 0.51）。矿层与围岩表现出一致的同位素变化趋势，表明Mo与Ni同位素在Fe-Mn（氢）氧化物吸附过程中发生协同分馏。地层序列变化揭示了三个阶段的古环境演化过程，其中第二段沉积时期更强烈的硫化（euxinia）环境及上升流活动有利于Ni-Mo元素沉淀富集。尽管缺氧—硫化环境及有机质埋藏促进了金属在沉积物中的保存，但这些因素不足以完全解释同位素组成变化。研究进一步提出，受氧化还原条件、上升流强度及初级生产力共同调控的Fe-Mn（氢）氧化物氧化还原循环，是控制Ni-Mo富集成矿的关键机制。华南其他富金属黑色页岩及地史时期类似沉积体系中观察到的相似同位素特征，暗示该机制可能代表全球氧化还原转变阶段广泛存在的共性过程。本研究表明，δ98Mo–δ60Ni耦合同位素体系可作为示踪海洋金属循环与古氧化还原环境演化的有效工具，并为理解地球关键氧化还原转型期海洋化学过程与金属沉积之间的耦合关系提供了新的认识。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['黑色页岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨涛","en_name":"","@id":"013ccc88-ae1e-4da6-b78e-01b97bb214fe","email":"yangtao@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"凌洪飞","en_name":"","@id":"f6fdcd49-79cb-4c4c-b28d-04ab2e940e33","email":"hfling@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 610723, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":610723,"name":"pdf"}]'::jsonb, '杨涛', 'yangtao@nju.edu.cn；', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('5a39ab90f43d4ac5b5462ebf4db368bc', '4d92ac95869a4804966e529e291c6ede', '上地幔橄榄石矿物高温高压实验数据集', NULL, '数据集来源：《深部上地幔氧逸度控制条件下橄榄石中的水溶解度：压力、温度与共存流体效应及其意义》
数据集类型：上地幔深部条件（10–13 GPa、1100–1450 ℃）下橄榄石中水的溶解度数据
数据集研究摘要：作为橄榄石中的结构羟基形式存在的水在决定上地幔水储量及其多种物理化学性质方面具有重要作用。然而，在上地幔深部（即300–410 km 深度）条件下橄榄石中水的溶解度——即特定条件下的最大含水量——仍需高精度确定。本研究在10–13 GPa、1100–1450 ℃条件下，在Fe-FeO缓冲体系和橄榄岩组合条件控制下，通过退火实验研究了水在橄榄石中的溶解度，采用具有代表性化学组成的初始橄榄石和不同流体材料。实验条件总体与上地幔深部环境相一致。通过氢扩散动力学、水含量剖面分析及时间序列实验，确保了H退火橄榄石样品中水的平衡进入。退火样品在3650–3000 cm−1范围内显示出红外羟基吸收带，但其相对谱带特征不同于此前在1–7 GPa、其他条件相近（包括起始材料相同）下获得的H退火实验结果。在实验条件范围内，水在橄榄石中的溶解度随温度和压力升高而增加，并且在不同流体条件（与上地幔及水溶解度研究相关）下表现出明显差异。总体而言，橄榄石中水的溶解度随上地幔深度非线性增加，可表示为：Cw = (290 ± 78) × exp[(0.0043 ± 0.0006) × 深度(km)] − (268 ± 89)（以H2O为共存流体）以及 Cw = (149 ± 72) × exp[(0.0046 ± 0.0011) × 深度(km)] − (132 ± 85)（以CH4-H2O为共存流体），其中Cw为水溶解度（ppm wt. H2O）。在真实上地幔条件下，应采用与CH4-H2O共存实验结果来界定橄榄石的水溶解度，其最高值仅约为800 ± 80 ppm wt. H2O，意味着上地幔中橄榄石的实际含水量大多（甚至几乎全部）低于该值。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['coexisting fluids'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨晓志","en_name":"","@id":"1cd7d3ff-8199-497c-be2e-372431cb4bc0","email":"xzyang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1159084, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":1159084,"name":"docx"}]'::jsonb, '杨晓志', 'xzyang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('47f6a1b57b80421bbd49e86739aebcb4', '319afce181a34d798261c6778a83bbaf', '无烟煤和石墨X射线光电子能谱特征数据集', NULL, '数据集来源：论文《无烟煤与石墨的纳米力学性质：杂原子官能团与结构演化的作用》
数据集类型：无烟煤和石墨的杨氏模量与微晶结构及杂原子官能团数据
数据集研究摘要：本研究以中国湖南省寒坡坳矿区的无烟煤和石墨样品为对象，探讨其结构变形特征及其与构造应力和岩浆侵入之间的关系。尽管既往研究已指出构造应力对有机质微晶结构具有重要影响，但对于多种因素之间的相互作用机制及其对煤和石墨力学性质的综合影响仍缺乏系统认识。为此，本研究综合采用偏光显微镜观察、镜质体反射率测定、拉曼光谱分析和高分辨率原子力显微镜表征，并结合粉末 X 射线衍射（XRD）和 X 射线光电子能谱（XPS）分析，对样品进行系统研究。结果表明，无烟煤和石墨的杨氏模量与煤级及石墨化程度均存在一定相关性，其中杂原子官能团，尤其是含硫官能团，在调控杨氏模量方面发挥关键作用。具体而言，噻吩硫含量与杨氏模量呈负相关，而砜类和亚砜类硫含量与杨氏模量呈正相关，表明不同赋存形态的含硫官能团对无烟煤和石墨的力学性能具有显著影响。本研究系统揭示了煤级、微晶结构及杂原子官能团对无烟煤和石墨纳米力学性质的耦合控制机制，为煤及煤基石墨力学性能评价提供了新的研究视角，也为煤炭资源的高效利用与深加工技术的发展奠定了重要理论基础。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['Anthracite and graphite'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"姚素平","en_name":"","@id":"fb34058e-e4e1-4e2e-94b6-eab9e77833aa","email":"spyao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1200342, 2, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1},{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":4595,"name":"zip"},{"storageNum":1195747,"name":"pdf"}]'::jsonb, '姚素平', 'spyao@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('af0776eb596748aca4c9565863ccb92a', 'a5545233ece14a4abf76d9c42d25aa29', '分异小行星球粒陨石硫化物数据集', NULL, '数据集来源：论文《部分分异小行星中核部硫脱气作用的岩石学证据》
数据集类型：类 Ornans 型球粒陨石中报道了硫化物交代白榴石和橄榄石的结构构造数据
数据集研究摘要：部分分异假说被认为是解释小行星内部结构及球粒陨石与非球粒陨石之间成因关系的重要模型，但迄今尚缺乏直接的岩石学证据支持。本文在类 Ornans 型球粒陨石中报道了硫化物交代白榴石和橄榄石的结构构造，其产出特征与宿主球粒陨石的热变质程度密切相关。交代结构中的矿物组合及其与岩石学亚型之间的对应关系，最合理的解释是硅酸盐矿物与富硫气体在高温条件下发生反应，而该富硫气体来源于正在固结的 Fe–Ni–S 金属核的脱气作用。类 Ornans 型球粒陨石中的硫化物交代结构可能构成支持部分分异假说的首个岩石学记录。鉴于类似硫化物交代结构在多类陨石中的广泛存在，我们提出核部硫的脱气作用可能是分异小行星中一种普遍发生的过程。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['chondrites.'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张爱诚","en_name":"","@id":"79c486b1-880d-44ca-8270-0938b825fa9d","email":"aczhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 7292250, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":7292250,"name":"pdf"}]'::jsonb, '张爱诚', 'aczhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('0c603c6bdb2b4d83b76b6451a0263a85', '7b32eaf93c074927b7be2c24c7114151', '未角砾化单斜辉石堆晶型玄武无球粒陨石地球化学数据集', NULL, '数据集来源：论文《未角砾化单斜辉石堆晶型玄武无球粒陨石 Northwest Africa 8326 的岩石成因：连接无球粒陨石与纯辉无球粒陨石之间的缺环》
数据集类型：未角砾化的灶神星陨石西北非 NWA 8326 的岩石学、矿物学、地球化学及年代学特征数据
数据集研究摘要：深入理解无球粒陨石的多样性及其岩石成因，对于揭示岩浆作用过程及行星和小行星的早期演化具有关键意义。本文系统报道了未角砾化的灶神星陨石西北非 NWA 8326 的岩石学、矿物学、地球化学及年代学特征。NWA 8326 主要由粗粒斜方辉石（约 74 vol%）、斜长石（约 19 vol%）、细粒普通辉石（约 5 vol%）组成，并含有多种副矿物，包括铬铁矿、钛铁矿、铁硫化物、二氧化硅矿物相、钾长石、钙磷酸盐矿物、锆石、斜锆石、金红石及原生富 Si、Al、K 玻璃，相较典型的霍华德岩–辉长无球粒陨石–纯辉长无球粒陨石（HED）陨石具有明显差异。根据辉石的结构特征和成分计算结果，我们认为粗粒斜方辉石为原生鸽辉石的反转产物，NWA 8326 应归类为鸽辉石累积型无球粒陨石（pigeonite cumulate eucrite），氧和铬同位素数据（Δ¹⁷O = −0.254 ± 0.009 ‰；ε⁵⁴Cr = −0.60 ± 0.06）支持这一分类。在样品中发现少量锆石集合体，其内部颗粒在阴极发光（CL）图像下表现出核–幔环带结构，核部呈暗色且富 Al，幔部呈亮色且贫 Al。我们认为 CL 暗色核为来自辉长无球粒陨石的捕虏晶锆石，其存在表明 NWA 8326 可能形成于灶神星地幔的部分熔融过程中，并同化了辉长质物质。捕虏晶锆石、原生富 Si、Al、K 玻璃以及斜长石成分的大幅度变化表明 NWA 8326 为未平衡的累积型无球粒陨石，因此锆石 ²⁰⁷Pb/²⁰⁶Pb 年龄 4559.2 ± 5.2 Ma（2σ）代表其结晶时代。综合累积结构特征与化学演化玻璃的存在，推测 NWA 8326 在结晶晚期被挖掘出，并逃逸了辉长无球粒陨石母体广泛发生的地壳热变质作用。其 Mg 同位素组成高于大多数纯辉长无球粒陨石，指示该类鸽辉石累积型无球粒陨石的母岩浆来源区具有相对较重的镁同位素组成（μ²⁵Mg：−90 至 −96 ppm）。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['Xenocrystic zircon'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张爱诚","en_name":"","@id":"79c486b1-880d-44ca-8270-0938b825fa9d","email":"aczhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 4079221, 9, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":8},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":127040,"name":"xlsx"},{"storageNum":3952181,"name":"docx"}]'::jsonb, '张爱诚', 'aczhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('a542d2977cea4141919e7d56b04cf4b4', '931764ea25c540a1a67d04922eed8462', '中国铌铁矿族矿物化学成分数据集', NULL, '数据集来源：《金属质-弱过铝质岩浆系统中的Nb-Ta成矿：来自中国铌铁矿族矿物化学成分和Hf同位素的约束》
数据集类型：Nb-Ta矿床中的CGMs的主量元素、微量元素以及Hf同位素数据
数据集研究摘要：近年来，与金属质-弱过铝质（MWP）岩浆系统相关的Nb-Ta成矿日益受到关注，特别是在认识到中国几个大型Nb-Ta矿床起源于MWP花岗岩之后。铌铁矿族矿物（CGMs）是Nb-Ta的关键矿石矿物，是理解该成矿作用机制的重要指示物。本研究对来自中国七个与MWP系统相关的Nb-Ta矿床中的CGMs进行了主量元素、微量元素以及Hf同位素的综合分析。我们将这些CGMs与来自强过铝质（SP）岩浆系统相关矿床的CGMs进行了对比，以揭示它们在成矿过程中的差异。统计分析，包括元素投图和偏最小二乘判别分析，揭示了MWP系统和SP系统之间CGMs的显著差异。来自MWP系统的最早结晶的CGMs显示出更高的Nb₂O₅含量，这是由于初始岩浆中Nb浓度较高，因此它们不需要像SP系统中的CGMs那样经历高程度的分异结晶。其他地球化学指标进一步区分了MWP岩浆源区，包括更高的Sc、总REE和Y含量，以及更高的Th/U原子比，同时具有更低的Li含量和Y/Ho原子比。随着岩浆演化，Zr/Hf原子比和总REE含量降低，而Ta/(Nb+Ta)原子比增加。此外，熔体-晶体-流体相互作用对晚期CGMs稀土元素特征的影响也不容忽视。CGMs的Hf同位素组成表明，华南早白垩世（~140–120 Ma）与MWP系统相关的Nb-Ta成矿归因于伸展构造背景下深部物源物质的贡献。两个系统之间CGMs的化学成分、U-Pb年龄和Hf同位素的差异，为区域勘探中通过重矿物找矿来定位与MWP花岗岩相关的Nb-Ta矿床提供了有价值的见解。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）','矿物学（包括放射性矿物学）'], ARRAY['铌铁矿','Nb-Ta成矿','金属质-弱过铝质花岗岩','偏最小二乘判'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"车旭东","en_name":"","@id":"5035da06-5f67-41ca-8b47-4b79835ba649","email":"xdche@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"王汝成","en_name":"","@id":"58f498c1-134c-4542-9a73-6eb163da04c6","email":"rcwang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 5833554, 3, NULL, 0, 0, 0, 'adopt', 'release', 'V2', NULL, '[{"name":"xlsx","count":1},{"name":"pdf","count":2}]'::jsonb, '[{"storageNum":800960,"name":"xlsx"},{"storageNum":5032594,"name":"pdf"}]'::jsonb, '车旭东', 'xdche@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('4bb7f28c6f6e422eadc71de811d69a33', 'a24511e467b64bbdb2fd86330e94735b', '大厂矿田高峰大型碳酸盐岩交代型锡矿石特征数据集', NULL, '数据集来源：论文《大厂矿田高峰大型碳酸盐岩交代型锡矿石中硫化物的地球化学：对沉淀条件和关键金属富集的启示》
数据集类型：大厂矿田高峰大型碳酸盐岩交代型锡矿石中铁闪锌矿、毒砂、磁黄铁矿和脆硫锑铅矿的主微量元素数据
数据集研究摘要：硫化物是多种关键金属的重要载体。碳酸盐岩交代型锡矿床中的含锡硫化物矿石通常含有可观的伴生关键金属资源。本研究利用EPMA和LA-ICP-MS分析了高峰矿床中铁闪锌矿、毒砂、磁黄铁矿和脆硫锑铅矿的主微量元素组成。高峰锡多金属矿床位于右江盆地大厂矿田，是典型的富硫化物碳酸盐岩交代型锡矿床，锡储量0.23 Mt、锑0.65 Mt、锌1.50 Mt、铅0.79 Mt、银2800 t、铟2000 t。100号矿体赋存于中泥盆统礁灰岩中，被成矿后花岗斑岩脉侵入。硫化物占矿石的90 wt%以上。
LA-ICP-MS和主成分分析显示，硫化物中微量元素含量具强空间一致性，与水平分布无明显相关性，表明各硫化物在整个矿体中沉淀速率较高，且花岗斑岩与未发现的成矿花岗岩基有关但未直接参与成矿。铁闪锌矿富集Cd（5479 ppm）和In（604 ppm），主要替代机制为Zn²⁺ ↔ (Fe²⁺, Mn²⁺, Cd²⁺)和2Zn²⁺ ↔ In³⁺ + Cu⁺。脆硫锑铅矿中Sn含量较高（平均814 ppm），Sn通过2Sb³⁺ + Fe²⁺ ↔ 2Sn⁴⁺ + □和2Sb³⁺ + □ ↔ Sn⁴⁺ + 2(Ag⁺, Cu⁺)进入。
成矿温度估算：毒砂353–372°C，六方磁黄铁矿254–约350°C，铁闪锌矿329±26°C，单斜磁黄铁矿<约180°C，表明流体冷却为硫化物沉淀关键机制。锡石与毒砂共沉淀受流体冷却和氧化还原反应控制。高成矿温度和“铟窗口”效应是铁闪锌矿中铟富集的主因。脆硫锑铅矿具有提取Sn的巨大潜力，Sn可能源于早期锡石的部分再活化。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）'], ARRAY['关键金属','铁闪锌矿','脆硫锑铅矿','LA-ICP-MS','高峰矿床'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"倪培","en_name":"","@id":"aba49fdb-93bd-4457-a903-74a7012012e5","email":"peini@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
