  ('2b08618c827a4f77a283371c5e408da5', '093b48511a22439298f24a3f1ff176d9', '福建东际金矿床高温热液流体数据集', NULL, '数据集来源：论文《福建东际金矿床通过岩浆蒸气收缩形成的高温热液流体记录》
数据集类型：福建东际金矿床的流体包裹体显微测温数据
数据集研究摘要：东际金矿床是华南政和地区最大的金矿床，探明黄金储量12.5吨、银136吨。矿体主要赋存于上侏罗统流纹斑岩中，部分产于火山碎屑岩内，受北东向角砾岩带控制。研究表明存在两个明显不同的金成矿阶段：阶段1以石英、黄铁矿和毒砂为主，含可见金-银矿物，呈单脉、裂隙网脉和角砾岩等多种构造样式；晚期阶段2以含金黄铁矿、伊利石、玉髓和磷灰石为特征，主要分布于角砾岩型矿石的胶结物中。矿体附近围岩发育强烈的伊利石化、硅化、弱绿泥石化。
阶段1多世代生长石英以及晚期与后期阶段相关的次生裂隙中的流体包裹体显微测温结果分别获得均一温度（320–411℃ 和 218–332℃）和盐度（0.4–4.2 wt% NaCl当量和0.7–3.9 wt% NaCl当量）。结合石英钛温度计结果，阶段1石英中富液两相流体包裹体的高温、低盐度范围表明成矿流体源于岩浆蒸气，在高于盐水流体系统临界曲线的静岩压力下通过冷却收缩为含水液体。阶段1石英的δDV-SMOW值介于−69.9‰至−60.9‰之间，δ¹⁸OH₂O值介于−0.9‰至1.4‰，暗示含金流体源自岩浆并混入少量大气降水。阶段1和阶段2黄铁矿的δ³⁴SV-CDT值范围为–0.3‰至8.0‰，显示硫主要来源于岩浆。显微测温数据和石英成分演化暗示流体混合对金属沉淀有贡献。结合地质、脉石和矿石矿物组合、蚀变、流体包裹体以及H–O–S同位素特征，认为东际金矿床含金成矿流体可能为岩浆蒸气在斑岩-浅成热液过渡型金系统中收缩迁移的产物。这些发现也指示深部存在斑岩型矿化的巨大找矿潜力。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）'], ARRAY['流体包裹体','蒸气收缩','亚浅成热液','东际金矿床','中国东南部'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"倪培","en_name":"","@id":"aba49fdb-93bd-4457-a903-74a7012012e5","email":"peini@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 25857, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":25857,"name":"docx"}]'::jsonb, '倪培', 'peini@nju.edu.cn；', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('19d80e977afa45a1ac1c5b8ea819187e', '304307353dea48728248ac5ee728733a', '和龙石英脉型钨铜矿床流体包裹体与地球化学数据集', NULL, '数据集来源：论文《和龙石英脉型钨铜矿床的流体演化与成矿机制：来自流体包裹体显微测温学和矿物原位地球化学分析的启示》
数据集类型：和龙石英脉型钨铜矿床流体包裹体显微测温和矿物原位地球化学数据
数据集研究摘要：位于南岭地区的和龙钨铜矿床发育石英脉型钨和铜矿化，是拥有显著且经济价值高的钨铜双金属资源的典型多金属矿床，其中WO₃储量达4万吨，铜储量达2000吨。本研究识别出三个成矿阶段，分别以黑钨矿-石英脉、白钨矿-石英脉和黄铜矿-石英脉为特征。采用流体包裹体显微测温学和矿物原位微量元素分析技术，揭示了钨和铜成矿流体的性质。
分析结果表明，黑钨矿、白钨矿以及与黄铜矿伴生的石英中均记录了以液相为主的水溶液流体包裹体。这些包裹体含有一个气泡，其余为NaCl-H₂O溶液。显微测温显示，早期黑钨矿中流体包裹体的均一温度为294–338°C，盐度为6.4–8.9 wt% NaCl当量，表明早期成矿流体具高温、中盐度特征。均一温度范围较宽，表明流体的自然冷却可能是触发黑钨矿沉淀的主要因素。从黑钨矿阶段到白钨矿阶段，包裹体均一温度和盐度持续降低，暗示白钨矿沉淀可能归因于流体混合作用，并可能伴随水岩反应。与黄铜矿伴生的石英中流体包裹体均一温度为194–233°C，盐度为4.4–6.1 wt% NaCl当量，表明晚期流体具低温、低盐度特征。未发现沸腾流体包裹体组合，且均一温度范围相对较宽，表明简单冷却（而非沸腾或混合）是黄铜矿沉淀的主要机制。
黑钨矿显著富集重稀土元素和高场强元素（如Nb、Ta），呈现典型的左倾配分模式。该模式结合稀土元素在黑钨矿中的晶体化学分配机制（即相对于轻稀土，重稀土优先进入其晶格），表明黑钨矿的成矿流体来源于高度分异的花岗质岩浆，这与分异花岗岩类出溶的富重稀土流体的地球化学特征一致。大多数白钨矿样品显示典型的正Eu异常和低Mo含量，指示还原性流体环境。然而，少数白钨矿样品显示负Eu异常，表明白钨矿结晶发生在动态氧化还原条件下。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）'], ARRAY['黑钨矿','流体包裹体','白钨矿','和龙矿床'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"倪培","en_name":"","@id":"aba49fdb-93bd-4457-a903-74a7012012e5","email":"peini@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 87124, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":87124,"name":"xlsx"}]'::jsonb, '倪培', 'peini@nju.edu.cn；', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('e8de5f2316194be2957060ba36a5e3be', '22edb61d1fba404cb584a349d08fd436', '中国鄂尔多斯盆地泾川砂岩型铀矿床地球化学数据集', NULL, '数据集来源：论文《中国鄂尔多斯盆地泾川砂岩型的铀矿源和成矿过程新认识：来自地质学、碳酸盐岩结构和地球化学的证据》
数据集类型：中国鄂尔多斯盆地泾川砂岩型的铀矿碳酸盐岩微相、主量元素、微量元素数据
数据集研究摘要：泾川砂岩型铀矿床位于鄂尔多斯盆地下白垩统洛河组灰色砂岩中，具有矿体厚（3–280 m）、分布广（约2000 km²）、品位高（4.3–17.4 kg/m²）的特点。铀矿化赋存于具钙铁硅胶结的还原性灰色砂岩带，而广泛分布的红层基本不含铀。碳酸盐岩贯穿成矿全过程，记录了流体性质和矿化条件。本研究通过岩相学和LA-ICP-MS分析，识别出三类碳酸盐岩：类型1为成矿前高度圆化的白云石和方解石碎屑；类型2为成矿阶段的贝壳状/自形微晶含铁白云石，与铀矿化密切共生；类型3为成矿后充填孔隙的亮晶方解石。类型2碳酸盐岩中U含量高、富U矿物包裹体普遍，且ΣREE和P含量升高，表明氧化性盆地流体与还原性含烃流体混合。类型1和类型2具有相似的REE配分和Th/U比，暗示类型1碎屑可能为成矿流体提供了U等金属来源。类型3则显示不同的地球化学特征。综上，提出成矿模型：氧化性盆地流体与含铀碳酸盐岩碎屑长期作用，使U、Fe、Mg等逐步富集；随后与沿深断裂上涌的还原性含烃流体混合，触发氧化还原反应，沉淀含铁白云石并形成铀矿床。成矿后以贫铀方解石沉淀为标志，反映热液活动减弱和大气降水混入。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）'], ARRAY['砂岩型铀矿床','鄂尔多斯盆地','碳酸盐岩地球化学','流体混合'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"倪培","en_name":"","@id":"aba49fdb-93bd-4457-a903-74a7012012e5","email":"peini@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
