  ('ff0bce886b414068a2024335b44b4a4e', 'a9fbea70faee46d49a1ac5826f3a442c', '微生物介导氟碳铈矿生物风化实验数据集', NULL, '数据集来源：论文《微生物介导的氟碳铈矿溶解作为风化壳型稀土矿床中黏土吸附态稀土元素的有效来源》
数据集类型：天然氟碳铈矿与苏云金芽孢杆菌的生物风化实验对比数据
数据集研究摘要：理解含稀土元素矿物的风化过程对于揭示风化壳型稀土矿床的成因至关重要。然而，氟碳铈矿（母岩中稀土的主要载体）的风化机制仍不明确。关于其在矿物-地下水相互作用过程中可风化性的野外观察与热力学计算结果之间的差异，引发了关于控制氟碳铈矿自然风化因素的问题。在此，我们提出微生物活动对氟碳铈矿的溶解有显著贡献。为了验证这一假设，我们使用天然氟碳铈矿和一株从风化壳型稀土矿床中分离的野生菌株——苏云金芽孢杆菌进行了生物风化实验。
结果表明，与热力学预测一致，在模拟地下水pH条件（约6）下，氟碳铈矿表现出抗溶解性。然而，苏云金芽孢杆菌的存在显著促进了氟碳铈矿的溶解。该菌株分泌多种有机酸，在生物风化过程中酸化溶液。生物与非生物对比实验表明，苏云金芽孢杆菌可通过酸解和配体络合作用诱导氟碳铈矿溶解。直接的细胞附着于矿物表面进一步增强了这些效应。
现有野外研究表明，在非常早期的岩石风化过程中氟碳铈矿快速溶解，这为氟碳铈矿对黏土吸附态稀土富集的贡献增加了不确定性。我们的结果表明，氟碳铈矿的溶解在很大程度上依赖于pH值，其生物溶解速率（RCe = 10⁻¹³ – 10⁻¹² mol·m⁻²·s⁻¹）接近或略低于在弱酸性至中性pH条件下实验室测定的长石和云母的溶解速率。由于这些铝硅酸盐矿物的风化提供了黏土矿物的主要来源，我们推断从氟碳铈矿中释放的部分稀土可以被风化剖面中的黏土矿物所保留。这些发现可能为氟碳铈矿的自然风化提供新的见解，并增进我们对风化壳型稀土矿床形成过程中稀土生物地球化学循环的理解。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）'], ARRAY['氟碳铈矿','生物风化','苏云金芽孢杆菌','稀土活化','风化壳型稀土矿'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"马灵涯","en_name":"","@id":"0790a8e2-e681-48b6-9f63-5b63c7e60507","email":"lingya.ma@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 354612, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":354612,"name":"pdf"}]'::jsonb, '马灵涯', 'lingya.ma@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('1cd468e97e8e45438eb6846346c455a9', '5fa45ae0cc5548db87274a8f230bc801', '西藏中部早-中始新世先遣盆地定年与沉积特征数据集', NULL, '数据集来源：《西藏中部早-中始新世（50–43 Ma）先遣盆地：干旱古环境与高原向南隆升趋势的档案》
数据集类型：羌塘西南部先遣盆地尕尔错组的综合地层学、沉积学、古生物学和物源数据
数据集研究摘要：沉积盆地为恢复局部地表隆升和古环境提供了宝贵记录。尽管先前的研究推断青藏高原内部的羌塘地体至少自始新世以来就已处于高海拔，但来自羌塘地体内高质量定年盆地的直接证据仍然稀缺。本文展示了羌塘西南部先遣盆地尕尔错组的综合地层学、沉积学、古生物学和物源数据。凝灰岩锆石和湖相碳酸盐的U-Pb定年表明，尕尔错组沉积于约50 Ma至43 Ma之间，为西藏中部的古环境、构造和地形演化建立了始新世记录。
尕尔错组由超过1900米出露良好的地层组成，从底部到顶部包含五个不同的单元：Em1（下部砾岩）；Em2（河流相红层）；Em3（下部细粒湖相红层）；Em4（上部湖相单元）；和Em5（上部砾岩）。生长地层与先遣盆地北缘的北倾逆冲断层同期发育，而盆地南部则平缓倾斜，不整合覆盖在中生代地层之上。多指标物源数据表明，沉积物来自周围的沉积岩和火山岩，而在盆地北部Em4和Em5单元沉积期间，来自北部更局部的变质岩和侏罗纪花岗岩类的物源变得占主导地位。
Em3中丰富的石膏、Em3和Em4中的湖相碳酸盐，以及Em4中细小、狭窄、拉长的叶片化石，均指示了干旱环境。这些发现表明先遣盆地是一个短暂的、干旱的内流系统，其消亡时间远早于南部班公湖-怒江缝合带沿线新生代盆地的最大扩张期。综合古地理重建表明，青藏高原的地表隆升自始新世以来从其内部向南推进。这种高原隆升模式可能是由岩石圈拆沉以及随之发生的地壳缩短和增厚所驱动的，这一过程始于羌塘地体中部。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['先遣盆地','始新世','古环境','干旱','高原隆升','羌塘地体'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"马安林","en_name":"","@id":"662bd163-4321-48ad-898b-122a2e790273","email":"alma@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"胡修棉","en_name":"","@id":"fbe0f7b6-cab7-4a4e-9a3c-06da1e90e59e","email":"huxm@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 894082, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":894082,"name":"docx"}]'::jsonb, '马安林', 'alma@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('fe6024e4b01a4de0953344a9b1b577b5', '812f56bfba5f4684a0a5c0eb08d3e3fe', '中国鄂尔多斯盆地东部奥陶系马家沟组白云石地球化学数据集', NULL, '数据集来源：论文《中国鄂尔多斯盆地东部奥陶系马家沟组（第五段）厚层白云岩的白云石化机制》
数据集类型：鄂尔多斯盆地东部奥陶系马家沟组（第五段）厚层白云岩的矿物学、沉积学和地球化学特征数据
数据集研究摘要：厚层白云岩的成因被认为与“白云石问题”密切相关。本研究对鄂尔多斯盆地东部奥陶系马家沟组（第五段）厚层白云岩的矿物学、沉积学和地球化学特征进行了系统分析。这些白云岩由米级至亚米级薄层旋回叠加而成，特征性地发育三种关键岩相：含球形石膏铸模的隐晶白云岩、具非平直晶界和板状石膏假晶的微晶白云岩，以及无石膏但具平直晶界的细晶白云岩。这些岩相的垂向分布与海平面旋回及白云石化学计量学的地球化学变化相关，表明白云石化作用受高频海平面波动控制。水平石膏假晶的保存，结合特征的Th/U比值和钟形稀土元素配分模式，支持低能、受限克拉通盆地的沉积背景。我们提出一个同生沉积模型：在温暖的浅海温室环境中，蒸发浓缩导致方解石和石膏沉淀，提高了Mg/Ca比值并触发了白云石化作用。所形成的稠密盐水向下渗透，交代未固结的钙质前驱物，形成了所观察到的白云岩类型。这一实例表明，高频海平面波动及其产生的薄层旋回叠置可以构成克拉通盆地中厚层白云岩的有效形成机制。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿物学（包括放射性矿物学）'], ARRAY['白云岩','鄂尔多斯盆地','马家沟组','海平面波动','同生白云石化'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"陆现彩","en_name":"","@id":"1d0b9749-bb84-4f59-b83c-02c1f37808ca","email":"xcljun@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 7040754, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":7040754,"name":"docx"}]'::jsonb, '陆现彩', 'xcljun@nju.edu.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-18'),
  ('6614608ae8264bc6a2e5700774021f2d', '710a1c26159c4301b1e510f2e7c161dc', '新元古代和古生代之交关键化石库micro-CT图像数据集', NULL, '元古宙和显生宙之交是地球-生命系统演化史上关键转折期，生物圈发生以单细胞微生物为主导向多细胞复杂生命为主导的革命性转变，因而元古宙-显生宙之交地球-生命系统演变研究成为全球近20 年来地球科学和演化生物学共同聚焦的前沿交叉领域，相关研究可为人类正确认识地球宜居性演化规律提供宝贵启示。该数据集依托实验室自主部署的前瞻课题“动物起源与寒武纪大爆发：过程与机制”产生，为完善复杂多细胞生命起源和早期演化过程提供了关键化石证据。本数据集为多个关键化石的micro-CT图像数据，数据扫描自中国科学院南京地质古生物研究所。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','古生物学'], ARRAY['寒武纪','新元古代','瓮安生物群','宽川铺生物群','澄江生物群','早期生物演化'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地质古生物研究所","en_name":"Nanjing Institute of Geology and Palaeontology,Chinese Academy of Sciences","@id":"c352231b0b0647ea9f94db9c8a7caa68"},"@type":"Person","name":"殷宗军","en_name":"","@id":"838b0ffc-4d31-437f-bcbb-a0315b7e7efd","email":"zjyin@nigpas.ac.cn"}]'::jsonb, '中国科学院南京地质古生物研究所', NULL, NULL, NULL, 'CC BY-ND 4.0', 'open', NULL, 42356870000, 10, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"rar","count":10}]'::jsonb, '[{"storageNum":42356870000,"name":"rar"}]'::jsonb, '殷宗军', 'zjyin@nigpas.ac.cn', NULL, NULL, NULL, '2026-05-19', '2026-05-19'),
  ('504e80df687a48d89de4669b417392f9', '2436b4310ec54cc097c33a7a31c4bf88', '华南奥陶纪地层电镜、micro-CT影像及同位素分析数据集', NULL, '该数据集为前瞻性课题“华南奥陶纪重大生物事件精细研究”产生的成果和数据，包含显微CT图像、地球化学分析等数据。为进一步探索华南奥陶纪生物事件及其背景机制，课题成员运用扫描电镜、micro-CT、双束电镜等多种成像设备，对多门类生物的化石照片进行影像提取，进而开展生物宏演化研究。同时运用地球化学手段，对多种元素开展同位素地层分析，探索当时的环境演变。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学','地质学','古生物学'], ARRAY['系统古生物学','地球化学','形态功能学'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地质古生物研究所","en_name":"Nanjing Institute of Geology and Palaeontology,Chinese Academy of Sciences","@id":"c352231b0b0647ea9f94db9c8a7caa68"},"@type":"Person","name":"梁艳","en_name":"","@id":"ab9715a6-02b3-4eec-bd4c-feafc6dc11e3","email":"liangyan@nigpas.ac.cn"}]'::jsonb, '中国科学院南京地质古生物研究所', NULL, NULL, NULL, 'CC BY-ND 4.0', 'open', NULL, 2956960156, 27, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"tif","count":22},{"name":"zip","count":1},{"name":"rar","count":3},{"name":"7z","count":1}]'::jsonb, '[{"storageNum":18663524,"name":"tif"},{"storageNum":336894600,"name":"zip"},{"storageNum":2476702776,"name":"rar"},{"storageNum":124699256,"name":"7z"}]'::jsonb, '梁艳', 'liangyan@nigpas.ac.cn', NULL, NULL, NULL, '2026-05-18', '2026-05-18'),
  ('5169876fa03443d0a7a35c64c2e0520d', '72a5a30cb22246b089869ccaaf5e3be5', '华南晚古生界沉积地球化学数据集', NULL, '该数据集是基于古生物学与油气地层应用全国重点实验室前瞻性课题“晚古生代关键气候转折期的海陆生态系统共演化”利用元素和同位素质谱仪测试产生的相关元素和同位素地球化学数据及地层古生物数据，以揭示晚古生代关键气候转折期的植被演化、火山事件、大陆风化、海洋初级生产力和氧化还原环境及其与生物演化协同演化机制。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','元素地球化学','同位素地球化学'], ARRAY['晚古生代','大陆风化','海洋初级生产力','氧化还原条件','沉积地球化学'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地质古生物研究所","en_name":"Nanjing Institute of Geology and Palaeontology,Chinese Academy of Sciences","@id":"c352231b0b0647ea9f94db9c8a7caa68"},"@type":"Person","name":"陈吉涛","en_name":"","@id":"cc4343ac-479c-4e08-a2a5-332cff70f0e9","email":"jtchen@nigpas.ac.cn"}]'::jsonb, '中国科学院南京地质古生物研究所', NULL, NULL, NULL, 'CC BY-ND 4.0', 'open', NULL, 27404171, 11, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":7},{"name":"pdf","count":4}]'::jsonb, '[{"storageNum":590258,"name":"xlsx"},{"storageNum":26813913,"name":"pdf"}]'::jsonb, '陈吉涛', 'jtchen@nigpas.ac.cn', NULL, NULL, NULL, '2026-05-18', '2026-05-18'),
  ('fbd62002d90e4d329cf53843936eca2c', 'ca3fbf795254401e9cf09013d12121b5', '南京信息工程大学地球系统模式碳中和情景预估试验数据', NULL, '本数据集由南京信息工程大学 气候系统预测与变化应对全国重点实验室，采用南京信息工程大学自主研发地球系统模式（NESM3），在SSP2-com碳中和排放情景下的模拟结果。背景与意义：SSP2-com情景以SSP2社会经济路径为框架，在全球至区域的多分辨率网格尺度上构建一个与现实相符的温室气体与空气污染物综合情景。SSP2-com 预测，通过亚太地区（尤其是中国）的能源和工业减排，全球 CO₂浓度将在 2062 年达到峰值，并在 2072 年实现净零排放。全球气温最初将遵循 SSP2-4.5，但随后将偏离该轨迹，并在 2100 年后的第一个十年内降至巴黎协定规定的 2°C 以下。在该情景下开展多成员气候预估，对理解碳中和的气候效应及区域响应不确定性具有重要价值。产生方法：基于NESM3全耦合框架（大气分辨率T63，约250 km），在设定的排放强迫下驱动5个集合成员（ens1–ens5）进行瞬变积分，逐日输出变量，经后处理按变量拆分为月分辨率的独立文件，变量名称对应的CMIP6格式long name记录在README.md。目前涵盖5个成员40余个月平均变量，包括近地面气象、水循环、云与辐射收支、地表通量、碳循环及三维大气场等，覆盖2015-2150年共136年（1632个月），总数据量约130 GB，以NetCDF格式存储。主要面向碳中和情景下全球与区域气候变化预估、极端事件演变、碳循环反馈及多模式比对。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['气候学'], ARRAY['南京信息工程大学地球系统模式','碳中和','多样本','气候变化'], '[{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"曹剑","en_name":"","@id":"a3e0a996-68bd-487a-8bc4-43e529089928","email":"jianc@nuist.edu.cn"},{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"孔智勇","en_name":"","@id":"9f898e67-278e-461e-912c-c3e645221d61","email":"202511010015@nuist.edu.cn"},{"@type":"Organization","name":"南京信息工程大学","@id":"19802bcf0d0046dfa69e5c2d405a68a4"}]'::jsonb, '南京信息工程大学', NULL, NULL, NULL, 'CC BY-SA 4.0', 'open', NULL, 137329967405, 236, NULL, 1, 0, 0, 'adopt', 'release', 'V2', NULL, '[{"name":"nc","count":235},{"name":"md","count":1}]'::jsonb, '[{"storageNum":137329960812,"name":"nc"},{"storageNum":6593,"name":"md"}]'::jsonb, '曹剑', 'jianc@nuist.edu.cn', NULL, NULL, NULL, '2026-05-18', '2026-05-18'),
  ('4b909750e1bc4564814b1b1da1977022', '0045a41b437545f18031c9ab3fe719cb', '中国城市区域通用热气候指数数据集（2003-2020）', 'Universal Thermal Climate Index (UTCI) dataset of urban areas in China (2003-2020)', '中国区域354座城市通用热气候指数（Universal Thermal Climate Index, UTCI）白天和夜晚月均值数据。该数据时间范围为2003年1月至2020年12月，时间分辨率为逐月，空间分辨率为1 km。数据以MODIS遥感产品为重要数据源，并结合气象站点观测资料、再分析资料及地形、土地覆盖、不透水面等关键地理环境和地表属性因子，构建适用于城市及亚城市尺度的UTCI遥感估算方法，生成覆盖中国城市区域的1 km分辨率日间和夜间月均UTCI数据产品。城市范围基于Global Urban Boundary（GUB）2018年城市边界数据进行划定，并将相关栅格数据统一处理至1 km空间分辨率。该数据可用于分析全球变暖和快速城市化背景下中国城市热舒适度及热暴露风险的时空变化特征。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['城市地理学'], ARRAY['通用热气候指数','热舒适度','热红外遥感'], '[{"Organization":{"@type":"Organization","name":"南京大学国际地球系统科学研究所","@id":"fa9feb03-8a83-49b1-bc4b-9b5eb27332a9"},"@type":"Person","name":"王晨光","en_name":"","@id":"ae5f30c7-cc75-4170-bd64-901b4d08b210","email":"wangchenguangnju@foxmail.com"},{"Organization":{"@type":"Organization","name":"南京大学国际地球系统科学研究所","@id":"fa9feb03-8a83-49b1-bc4b-9b5eb27332a9"},"@type":"Person","name":"占文凤","en_name":"","@id":"e8dfa8e3-7e85-40e3-ab38-773e312e14ce","email":"zhanwenfeng@nju.edu.cn"}]'::jsonb, '南京大学国际地球系统科学研究所', NULL, NULL, NULL, 'CC BY-ND 4.0', 'open', NULL, 35341787376, 432, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/4b909750e1bc4564814b1b1da1977022.png', '[{"name":"tif","count":432}]'::jsonb, '[{"storageNum":35341787376,"name":"tif"}]'::jsonb, '王晨光', 'wangchenguangnju@foxmail.com', NULL, NULL, NULL, '2026-05-18', '2026-05-18'),
  ('d6c341f317734d6a87dc355221032d76', 'c894fcd8b70043a18d7ae469259ccb60', '全球平均水汽与温度变化耦合模式的数据', NULL, '水蒸气对气候系统内的能量流动起着至关重要的作用。在塑造全球大气环流进而影响气候的动态过程中，水蒸气和温度变化之间存在复杂的耦合关系。然而，由于缺乏对该耦合关系的精确描述，限制了现有气候模式对于全球温度的预测精度。在全球变暖的趋势下，建立有效捕捉水汽并精确预测未来气候变化的气候模式对促进人类发展具有重要的参考价值。在本研究中，团队成员基于2021年诺贝尔物理学奖表彰的复杂气候模式，结合水汽扰动方程和机器学习的云量预测，开发了一个水汽动力学辐射对流模型。根据1900年至2000年的气象观测数据，本工作预测了在变暖趋势下水汽动力对全球平均气温的影响。通过来自七个气象机构的历史数据进行验证表明，该耦合模型能够有效地预测2000年至2020年的全球平均地表温度和比湿。该模型对2020年至2050年的地球表面温度预测将逐年上升，并在一定温度区间内随机波动。将该模型的预测结果与干大气模型的预测结果进行比较，可以得出水汽的动态耦合能够减缓地球表面的变暖趋势。与固定比湿的解耦模型的预测相比，水汽的正反馈效应至少能使大气变暖趋势增加 6%。因此，水汽与全球平均气温变化的耦合是气候变化的一个重要组成部分。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['大气科学'], ARRAY['气候模型','全球温度','温湿耦合','机器学习'], '[{"Organization":{"@type":"Organization","name":"南京航空航天大学","@id":"e0d5d9e2-65b0-4668-8e87-ced1229aed25"},"@type":"Person","name":"马锦暄","en_name":"","@id":"3d1a30c2-2a66-40c8-9959-69b55623b7fa","email":"jinxuanma@nuaa.edu.cn"}]'::jsonb, '南京航空航天大学', NULL, NULL, NULL, 'CC BY-NC 4.0', 'open', NULL, 52457, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":52457,"name":"xlsx"}]'::jsonb, '郭万林', 'wlguo@nuaa.edu.cn', NULL, NULL, NULL, '2026-05-18', '2026-05-16'),
  ('d3743e930b1943deb852454ff997313d', '574cdde9065e4673a9669d5fb26c6e18', '拉伸纪-寒武纪早期复杂生命演化及其环境背景电镜、micro-CT及硫同位素等数据集', NULL, '本数据集依托实验室自主部署的前瞻性课题“复杂生命早期演化及其环境背景”产生，主要根据课题组成员在胶辽徐淮地区拉伸纪、华南地区成冰纪间冰期、柴达木盆地和皖南地区埃迪卡拉纪以及陕南地区寒武纪早期的研究工作采集。化石方面，主要研究了拉伸纪的多细胞藻类、成冰纪间冰期的浮游生物、埃迪卡拉纪的埃迪卡拉型生物和寒武纪最早期宽川铺生物群的环节动物。地球化学方面，主要研究了皖南蓝田生物群岩心里面黄铁矿的硫同位素差异。化石照片主要由扫描电镜、光学显微镜、micro-CT等设备产生，另外辅助了超薄切片。地球化学方面主要是应用了nano-SIMS技术分析了原位硫同位素组成。数据集展示了从拉伸纪到寒武纪早期的复杂生命演化及其环境背景。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学','地质学','古生物学'], ARRAY['拉伸纪','成冰纪','埃迪卡拉纪','寒武纪幸运期','多细胞藻类','后生动物','nanoSIMS'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地质古生物研究所","en_name":"Nanjing Institute of Geology and Palaeontology,Chinese Academy of Sciences","@id":"c352231b0b0647ea9f94db9c8a7caa68"},"@type":"Person","name":"张华侨","en_name":"","@id":"759755ff-6ad0-47f0-ac54-bb611dc4ae6d","email":"hqzhang@nigpas.ac.cn"}]'::jsonb, '中国科学院南京地质古生物研究所', NULL, NULL, NULL, 'CC BY-ND 4.0', 'open', NULL, 765823414, 67, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"jpg","count":45},{"name":"psd","count":8},{"name":"mp4","count":5},{"name":"xlsx","count":1},{"name":"pdf","count":7},{"name":"ai","count":1}]'::jsonb, '[{"storageNum":290022015,"name":"jpg"},{"storageNum":377050792,"name":"psd"},{"storageNum":17229505,"name":"mp4"},{"storageNum":403188,"name":"xlsx"},{"storageNum":80741803,"name":"pdf"},{"storageNum":376111,"name":"ai"}]'::jsonb, '张华侨', 'hqzhang@nigpas.ac.cn', NULL, NULL, NULL, '2026-05-18', '2026-05-18'),
  ('cae885078fb948b88522a22cf518a2ed', '181f0d118b554d96a2b6e7f5be89f7d2', '中生代化石图像及地球化学分析数据集', NULL, '该数据集依托实验室自主部署的前瞻性课题“中生代生态系统重大革新及环境背景”产生。该课题在高分辨率地质年代学研究基础上，对我国内蒙、新疆和缅甸中生代关键地质时期的古生物、古生态和古环境进行系统深入的研究，以揭示中生代重要动植物门类的起源、演化历史和形态演化模式，和中生代重要生物事件中动植物的演替历史及其地质背景和环境驱动机制。数据内容主要包括论文代表作的PDF、由体视显微镜，生物显微镜，激光共聚焦显微镜和扫描电子显微镜等拍摄化石的原始照片、由电感耦合等离子体质谱仪（ICP-MS），无机碳氧稳定同位素质谱检测系统等测试产生的地层样品的地球化学原始分析数据等。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','地质学','古生物学'], ARRAY['中生代','宏演化','环境','地质时间','陆地生态系统','地球化学'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地质古生物研究所","en_name":"Nanjing Institute of Geology and Palaeontology,Chinese Academy of Sciences","@id":"c352231b0b0647ea9f94db9c8a7caa68"},"@type":"Person","name":"史恭乐","en_name":"","@id":"c5c04cbf-4038-409d-8681-2f267a3a6f09","email":"glshi@nigpas.ac.cn"}]'::jsonb, '中国科学院南京地质古生物研究所', NULL, NULL, NULL, 'CC BY-ND 4.0', 'open', NULL, 548573221, 68, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"tif","count":6},{"name":"nex","count":2},{"name":"jpg","count":39},{"name":"mp4","count":1},{"name":"xlsx","count":13},{"name":"pdf","count":1},{"name":"png","count":1},{"name":"eps","count":4},{"name":"tnt","count":1}]'::jsonb, '[{"storageNum":14748158,"name":"tif"},{"storageNum":55344,"name":"nex"},{"storageNum":65169059,"name":"jpg"},{"storageNum":1337906,"name":"mp4"},{"storageNum":3454937,"name":"xlsx"},{"storageNum":2594837,"name":"pdf"},{"storageNum":9523839,"name":"png"},{"storageNum":451669920,"name":"eps"},{"storageNum":19221,"name":"tnt"}]'::jsonb, '史恭乐', 'glshi@nigpas.ac.cn', NULL, NULL, NULL, '2026-05-18', '2026-05-18'),
  ('bc1731a665ca40ed8ebb13ab509d8461', '2550444655b54e97b116926c72274371', '中国光伏电站空间分布ChinaPV数据集（2015,2020年）', 'ChinaPV: the spatial distribution of solar photovoltaic installation dataset across China in 2015 and 2020', '太阳能光伏发电是一种清洁无污染、可再生、地域限制小的能源利用方式。目前中国已成为世界上最大的光伏发电市场，并拥有全球将近三分之一的光伏。我们在此发布中国光伏电站空间分布ChinaPV数据，数据时间为2015和2020年。该数据集以Landsat-8卫星影像为数据源，处理方法是基于GEE遥感云计算平台，运用随机森林分类模型对2020年中国光伏电站（包含水上光伏、屋顶光伏等）进行遥感提取，后经过形态学运算，灯光数据滤除，轮廓细化及目视解译等后处理操作生成。该数据详细描述了中国区域内每个光伏电站的面积和地理位置信息，反映了中国地区光伏电站发展现状及其地域分布规律，以ESRI Shapefile格式存储。数据集反映了中国地区光伏电站发展现状及其地域分布规律，对于我国光伏产业的规划、建设、运营和管理具有重要的价值。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地理学','地理学其他学科','摄影测量与遥感技术'], ARRAY['新能源','光伏发电','遥感提取'], '[{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"刘婧","en_name":"","@id":"978118d0-a5a2-4e88-a2c0-6a0a54078661","email":"jingliugeo@njnu.edu.cn"},{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"王瑾玥","en_name":"","@id":"7183783c-4063-474b-9845-50d00edcc864","email":"972211659@qq.com"},{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"李龙辉","en_name":"","@id":"19c7fdea-55a8-479a-b8ab-40bf37b0f1bc","email":"longhui.li@njnu.edu.cn"}]'::jsonb, '南京师范大学', NULL, NULL, NULL, 'CC BY-NC 4.0', 'open', NULL, 31176964, 21, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/bc1731a665ca40ed8ebb13ab509d8461.png', '[{"name":"shx","count":3},{"name":"xml","count":3},{"name":"sbx","count":3},{"name":"prj","count":3},{"name":"dbf","count":3},{"name":"shp","count":3},{"name":"sbn","count":3}]'::jsonb, '[{"storageNum":176676,"name":"shx"},{"storageNum":15173,"name":"xml"},{"storageNum":6700,"name":"sbx"},{"storageNum":435,"name":"prj"},{"storageNum":1843388,"name":"dbf"},{"storageNum":28920020,"name":"shp"},{"storageNum":214572,"name":"sbn"}]'::jsonb, '刘婧', 'jingliugeo@njnu.edu.cn', NULL, NULL, NULL, '2026-05-17', '2026-05-17'),
  ('d705c302060e45019ae9585b1f3c2b51', 'a4fdd20a9841408b973e5204c796cf69', '中国高标准农田建设数据集', 'China''s Well-Facilitated Farmland distribution dataset', '研究通过收集和整理政府部门发布的377份报告和文件，制作了2020年中国市级和省级高标准农田（WFF）建设数据集。数据产品涵盖了省级和市级尺度，其中，省级数据包括2020年WFF累计建设面积、2030年计划累计建设目标以及当前完成度等内容；市级数据集则包括了2020年各地WFF累计建设面积。省市级数据都包括WFF建设数据集(*.xlsx)和数据来源文件（*.pdf）。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地理学其他学科'], ARRAY['高标准农田，农田面积，耕地'], '[{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"阿布都沙拉木·吐鲁甫","en_name":"","@id":"ad790a30-3210-457f-a7a9-0a4935df2b59","email":"a_turup@nnu.edu.cn"},{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"张君","en_name":"","@id":"29975eae-8657-44d3-85d1-7e8bb6c2f583","email":"jun.zhang@njnu.edu.cn"},{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"马文超","en_name":"","@id":"cf1389ad-2eb9-4580-9125-88812c9f1e2e","email":"wma@nnu.edu.cn"},{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"马炳鑫","en_name":"","@id":"cf70afd6-b9b7-4b7c-9e33-81259fc03a76","email":"231301026@njnu.edu.cn"},{"Organization":{"@type":"Organization","name":"新疆师范大学","@id":"1c7f9ed607744d52b80b09bbc57e65f3"},"@type":"Person","name":"张月","en_name":"","@id":"3f98e3b4-6d2f-47d8-8244-854e288be11e","email":"zhangyuexinjiang@163.com"},{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"Zaeem Hassan Akhter","en_name":"","@id":"8a61fe86-111a-4e9d-a727-4705df52a79b","email":"haccan@live.com"},{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"李龙辉","en_name":"","@id":"19c7fdea-55a8-479a-b8ab-40bf37b0f1bc","email":"longhui.li@njnu.edu.cn"}]'::jsonb, '南京师范大学', NULL, NULL, NULL, 'CC BY 4.0', 'open', NULL, 293511459, 5, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":2},{"name":"pdf","count":2},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":78578,"name":"xlsx"},{"storageNum":293302334,"name":"pdf"},{"storageNum":130547,"name":"docx"}]'::jsonb, '李龙辉', 'longhui.li@njnu.edu.cn', NULL, NULL, NULL, '2026-05-16', '2026-05-16'),
  ('8c0f57b74b8d4b89ba72f30e2a5d616e', 'd4bbb24c596146839dd60ec8348d8461', '基于最优模型的0.1°全球植被带逐月潜在蒸散发数据集', 'A 0.1° monthly potential evapotranspiration dataset based on the optimal models over global vegetation zones', '在气候学、生态学、水文学和农学等多个领域，选择有效模型来准确估算潜在蒸散发（PET）至关重要。然而，当前许多主流的PET产品依赖于使用默认参数的模型，这会给PET相关研究带来不确定性。为解决该问题，我们基于全球124个通量塔的观测数据，推导了五种常用PET模型的参数。通过比较这些模型在不同生物群系中的性能，我们确定校准后的Priestley-Taylor模型和Milly-Dunne模型为最优选择，它们具有很好的空间可移植性，能够有效应用于其原始观测站点之外。利用这些最优模型，结合四个广泛使用的气象数据集以及随时间变化的土地利用/覆盖数据，我们生成了1992-2022年的0.1°全球植被带逐月潜在蒸散发数据集。这个新的PET数据集为开展PET相关研究提供了一个新的选择。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['大气科学'], ARRAY['蒸发','潜在蒸散发','水文','蒸散发'], '[{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"毕早莹","en_name":"","@id":"bd4b4c84-d3d8-467d-85a3-305d7ca180c9","email":"202311010030@nuist.edu.cn"},{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"孙善磊","en_name":"","@id":"bb95eb9a-e63d-4125-8b86-4a1c978197a8","email":"sun.s@nuist.edu.cn"},{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"陈海山","en_name":"","@id":"8149a666-5e2e-460a-85ef-2bbf1573dfb5","email":"haishan@nuist.edu.cn"}]'::jsonb, '南京信息工程大学', NULL, NULL, NULL, 'CC BY-NC 4.0', 'open', NULL, 1102388595, 32, NULL, 0, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/8c0f57b74b8d4b89ba72f30e2a5d616e.png', '[{"name":"txt","count":1},{"name":"nc","count":31}]'::jsonb, '[{"storageNum":316,"name":"txt"},{"storageNum":1102388279,"name":"nc"}]'::jsonb, '孙善磊', 'sun.s@nuist.edu.cn', NULL, NULL, NULL, '2026-05-16', '2026-05-16'),
  ('32a1e31bae19472a957181fc5a77d7a1', '91ce60493f6946bebf5acc9b540ca768', '基于Shuttleworth-Wallace模型的全球5km逐月潜在蒸散发数据集（1982–2015）', 'A global 5 km monthly potential evapotranspiration dataset (1982–2015) estimated by the Shuttleworth-Wallace model', '作为蒸散发（ET）的理论上限，潜在蒸散发（PET）一直以来都是各个学科重点关注的一个关键变量。然而，由于非真实的下垫面设置和不合理的模型参数化，目前PET数据集及主要PET模型依然存在诸多不确定性。因此，研究充分考虑植被参数（如植被气孔导度、CO2效应对植被气孔导度的影响）的种间差异，并应用经过严格筛选的全球96个通量塔观测的PET（即不受水分胁迫的ET）数据，对Shuttleworth-Wallace（SW）双源模型进行了率定和参数化。评估结果显示，无论是在模型率定期和验证期，率定后的模型均可以较好地模拟出PET。基于1982–2015年四套气象数据（MSWX-Past、CRU TS4.06、ERA-5和MERRA-2）、重制的全球植被冠层高度、土地利用/覆盖数据集（GLASS-GLC）、叶面积指数数据（GLASS AVHRR LAI）以及格点化的全球CO2浓度数据，生产了全球（60oS–85oN，180oW–180oE）逐月5km的PET、潜在蒸腾（PT）和潜在土壤蒸发（PE）产品；需要注意的是，考虑气象数据的不确定性，最终提供PET、PT和PE的集合产品。该数据集的主要特点如下：（1）估算的PET更加贴近现实情况；（2）给出了PET的二组分PT和PE；（3）考虑了植被CO2生理效应对PET过程的影响。该数据集将为全球气候变化研究、水文模拟、干旱指数计算以及农业用水估算等相关领域的研究提供新的数据选择。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['大气科学'], ARRAY['蒸发','水文','潜在蒸散发','蒸散发'], '[{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"孙善磊","en_name":"","@id":"bb95eb9a-e63d-4125-8b86-4a1c978197a8","email":"sun.s@nuist.edu.cn"},{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"毕早莹","en_name":"","@id":"bd4b4c84-d3d8-467d-85a3-305d7ca180c9","email":"202311010030@nuist.edu.cn"},{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"陈海山","en_name":"","@id":"8149a666-5e2e-460a-85ef-2bbf1573dfb5","email":"haishan@nuist.edu.cn"}]'::jsonb, '南京信息工程大学', NULL, NULL, NULL, 'CC BY-NC 4.0', 'open', NULL, 25780713013, 35, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/32a1e31bae19472a957181fc5a77d7a1.png', '[{"name":"txt","count":1},{"name":"nc","count":34}]'::jsonb, '[{"storageNum":341,"name":"txt"},{"storageNum":25780712672,"name":"nc"}]'::jsonb, '孙善磊', 'sun.s@nuist.edu.cn', NULL, NULL, NULL, '2026-05-16', '2026-05-16'),
  ('3a409f770a5a4cf18aada3fc23b9f079', '0193baa677c54ce8bf450170c44b27ae', '单斜辉石堆晶型玄武无球粒陨石 Northwest Africa 8326 中强冲击变质作用的矿物学与年代学记录', '', 'L 群球粒陨石、火星陨石和月球陨石中普遍记录到强冲击变质作用（约 ≥20 GPa）的矿物学证据，但在霍华德岩–辉长无球粒陨石–纯辉长无球粒陨石（HED）陨石中却鲜有报道。本文对鸽辉石累积型无球粒陨石西北非（NWA）8326 中冲击成因矿物学特征及磷灰石族矿物 merrillite 的离子探针 U–Pb 定年结果进行了详细研究。
NWA 8326 中的冲击矿物学特征包括：（i）辉石中的平面裂隙以及斜长石的部分假玄武玻璃化（maskelynitization）；（ii）熔脉内出现高压矿物，如 tissintite、斯石英（stishovite）、富空位普通辉石（vacancy-rich augite）、超硅石榴子石，以及宿主岩（熔脉外）中发现的 xieite、tuite 和 reidite。此外，我们在冲击熔体边部观察到细粒单斜顽火辉石（clinoenstatite）和鸽辉石，认为其形成于亚稳态结晶过程。
上述表明，NWA 8326 经历了至少 20 GPa 的冲击变质作用，其强度可与 L 群球粒陨石、火星陨石及月球陨石中记录的冲击作用相当。我们提出，先前研究中部分辉长无球粒陨石所推断的较低冲击压力，可能源于缺乏合适的高压矿物学指示标志。
离子探针测得 NWA 8326 中 merrillite 的 ^207Pb/^206Pb 年龄为 4238 ± 32 Ma（95% 置信度），代表该次冲击变质事件的发生时间。NWA 8326、部分无球粒陨石、月球样品/陨石及球粒陨石之间相似的撞击年龄表明，在约 4.2 Ga 时太阳系中可能发生过一次广泛的撞击事件。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学'], ARRAY['High-pressure minerals'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"张爱诚","en_name":"","@id":"79c486b1-880d-44ca-8270-0938b825fa9d","email":"aczhang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 51439, 1, NULL, 4, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":51439,"name":"xlsx"}]'::jsonb, '张爱诚', 'aczhang@nju.edu.cn', NULL, NULL, NULL, '2026-05-16', '2026-05-15'),
  ('74632a0599ae41c99a74f6695b3f5a16', 'f8846c6d9e364f58b12556f965fe33ed', '基于元素-络合机制的黏土矿物中锂的赋存状态数据集', NULL, '锂是绿色技术中减少碳排放的基石。然而，传统的锂开采面临到2030年可能出现的供应链中断风险，这凸显了探索黏土型锂矿床的紧迫性，而这类矿床的锂赋存状态和提取机制目前尚不清楚。本研究对云南中部的一个钻探岩心进行了调查，以阐明锂的赋存模式及其成因机制。该黏土岩主要由锂绿泥石、硬水铝石和锐钛矿组成，全岩锂品位高达1.94 wt%，达到世界级水平。
研究采用X射线光电子能谱（XPS）、核磁共振（NMR）和飞行时间二次离子质谱（TOF-SIMS）分析来约束锂的赋存状态。对样品AN 1.62和AN 1.58的XPS Li 1s峰进行拟合，分别在57.0、56.3、55.9、55.4 eV和57.2、56.6、56.0、55.3 eV处获得特征峰，表明锂存在于表面、伪六方空腔内以及晶格中，形成LiCl、Li₂O、LiF和LiOH等物种。在-0.7 ppm处的⁷Li NMR化学位移表明锂主要赋存于晶格中，而峰的不对称性和正偏态则表明表面锂和结构锂共存。这些锂的成因机制可能涉及四面体Al-Si位点和八面体Fe/Mg-Al位点的同晶替代。Al/Mg/Fe-F络合物和F-Li物种的存在进一步支持了结构锂的掺入。在锂绿泥石中，锂与Al、Mg和Fe呈现耦合富集，但在硬水铝石中则与Al解耦。TOF-SIMS三维重建显示，锂主要集中在锂绿泥石TO1T-O2-TO1T结构中的O₂层。
逐级浸出实验进一步约束了锂的赋存状态，表明大多数锂赋存于晶格中。在400°C下煅烧可促进锂掺入晶格，而随后在600°C–200°C（H₂SO₄）或200°C（浓H₂SO₄）条件下处理可有效活化锂，特别是对于样品AN 1.58，实现了近乎完全的提取', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）','矿物学（包括放射性矿物学）'], ARRAY['锂赋存状态','黏土型锂矿','锂绿泥石','XPS','NMR','TOF-S'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"蔡元峰","en_name":"","@id":"bea6d84a-4dae-4ef7-91bf-1ea580bac031","email":"caiyf@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 125548, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":125548,"name":"pdf"}]'::jsonb, '蔡元峰', 'caiyf@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('53d779af25aa48b1804ed67e84375fe0', 'e659d0ba1b994a1ca94e937e66af5c32', '中国华南埃迪卡拉纪末期铜山化石库数据集', NULL, '由于具有丰富生物信息的布尔吉斯页岩型（Burgess Shale-type）保存方式在埃迪卡拉纪并不常见，因此铸模形式的埃迪卡拉型（Ediacara-type）保存为理解后生动物（包括典型的叶状体）、原生生物和藻类等生物的早期演化提供了重要信息。本文报道了中国湖北通山地区埃迪卡拉系顶部灯影组碳质泥岩/页岩中发现的新“铜山化石库”（Tongshan Lagerstätte，年龄约为551–543.74 ± 0.87 Ma），该化石库属于布尔吉斯页岩型保存。该生物群具有很高的生物多样性，表明生物在海洋透光带内、风暴浪基面之下发生了快速的、很可能是原地的埋藏，揭示了与埃迪卡拉生物群Nama组合同期的深水生物多样性。据我们所知，这是首次记录到典型的埃迪卡拉Rangeomorph叶状体具有布尔吉斯页岩型保存。叶状体的布尔吉斯页岩型保存的出现，反映了埃迪卡拉纪细粒沉积物的稀缺性，并填补了传统埃迪卡拉型保存、含有机质残留的埃迪卡拉型保存以及布尔吉斯页岩型保存之间的一个重要空白。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','地层学与地史学','古生物学'], ARRAY['布尔吉斯页岩型保存','铜山化石库','埃迪卡拉纪','叶状体','华南'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"沈树忠","en_name":"","@id":"d2845e4a-e43f-48c5-8cb1-8c09d25a7fd1","email":"szshen@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 18389019, 6, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1},{"name":"pdf","count":4},{"name":"csv","count":1}]'::jsonb, '[{"storageNum":123276,"name":"xlsx"},{"storageNum":18260634,"name":"pdf"},{"storageNum":5109,"name":"csv"}]'::jsonb, '沈树忠', 'szshen@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('e7f20389b7854557baf0c990cce43621', '7b7f17060ffc447190a73583c8a07aa4', '一种用于基于Orbitrap的淡水磷酸盐氧同位素测定的亚升预处理方法数据集', NULL, '磷酸盐氧同位素组成（δ¹⁸O(PO₄³⁻)）为理解水生环境中磷的来源和转化过程提供了关键信息。然而，天然淡水中磷酸盐浓度很低（<1 μM），在使用传统的热转化/元素分析-气体源同位素比值质谱法（TC/EA–IRMS）分析δ¹⁸O(PO₄³⁻)时，需要大体积水样（25–100 L）且操作流程繁琐。本文报道了一种使用亚升体积（约1升）淡水分析δ¹⁸O(PO₄³⁻)的方法。该方法采用成熟的氧化锆凝胶法吸附溶解态磷酸盐，然后通过阴离子交换树脂纯化磷酸盐，并用电喷雾电离-轨道阱质谱（ESI–Orbitrap–MS）进行同位素测量。整个前处理过程的δ¹⁸O(PO₄³⁻)分析精度为±0.8‰，在ESI–Orbitrap–MS测量的分析不确定度范围内。与TC/EA–IRMS的校准结果显示近乎1:1的回归关系（斜率0.96，残差<0.9‰）。对天然湖泊淡水样品的测试达到了±0.3‰的精度。与TC/EA–IRMS方法相比，本方法将样品体积降低了三个数量级，为以前所未有的时空分辨率示踪PO₄³⁻循环和源解析开辟了新途径。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['氧化锆凝胶','AG1–X8树脂','亚升级体积','ESI–Orbit'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"Hattori, Shohei","en_name":"","@id":"a3970736-2980-4936-8726-2be694bbed1c","email":"hattori@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"Bao, Huiming","en_name":"","@id":"c755117b-4c46-4b82-96f0-087b01b8efb1","email":"bao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 577007, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":577007,"name":"docx"}]'::jsonb, 'Hattori, Shohei', 'hattori@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('a6dda1172e374bfc8b73a4c58284b111', 'dfb6ba6a1f524edab2a1856d7cc35595', '使用ESI-Orbitrap-MS中SO₃⁻碎片离子进行甲磺酸的三氧同位素分析数据集', NULL, '二甲基硫（DMS，CH₃SCH₃）在大气中氧化为硫酸盐（SO₄²⁻）和甲磺酸（MSA，CH₃SO₃⁻）是大气硫循环的一个关键过程，尤其是在偏远的海洋地区。为了更好理解DMS的氧化化学，氧同位素特征（δ¹⁸O和Δ¹⁷O）可作为示踪剂用于研究DMS氧化生成MSA的过程。然而，传统的气体源稳定同位素比值质谱法（IRMS）由于需要微摩尔级的样品量以及分析步骤复杂，很少被用于测量天然丰度MSA的同位素组成。本文开发了一种使用电喷雾电离-轨道阱质谱（ESI-Orbitrap-MS）结合双进样系统（在约13 nmol样品上，4个参考样和3个样品块，分析时间98分钟）测量MSA的δ¹⁸O和Δ¹⁷O值的新方法。
直接在CH₃SO₃⁻离子上进行Δ¹⁷O测量需要高达120,000的质量分辨率（在m/z 200处的半高全宽）来分离¹⁷O和¹³C同位素体，与使用60,000的较低质量分辨率相比，这往往会增加分析不确定性。因此，我们测量了从MSA衍生并去除了–CH₃基团的SO₃⁻碎片离子，从而能够在60,000的较低质量分辨率和更高的扫描速度（4次扫描/秒）下进行Δ¹⁷O分析。我们的ESI-Orbitrap-MS测量结果与传统IRMS测量结果之间的三点校准显示，δ¹⁸O和Δ¹⁷O值的回归线残差标准差分别为1.0‰和0.4‰。总体而言，这种新的分析方法比以前的方法更直接、更灵敏，为分析更多的自然大气和/或冰芯样品提供了可能。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['甲磺酸','三氧同位素','ESI-Orbitrap-MS','SO₃⁻'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"Hattori, Shohei","en_name":"","@id":"a3970736-2980-4936-8726-2be694bbed1c","email":"hattori@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1676855, 1, NULL, 2, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":1676855,"name":"pdf"}]'::jsonb, 'Hattori, Shohei', 'hattori@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('38a4f6dce1ec499abadd13b9a329fc1a', '370829c770ef4c16b21b7f37ac9319ea', '来自格陵兰东南部冰芯的具有最小后沉积改造的60年大气硝酸盐同位素记录数据集', NULL, '大气硝酸盐（NO₃⁻）的稳定同位素是示踪氮来源和转化过程的宝贵工具；然而，它们在冰芯记录中的信号常常被后沉积过程所干扰。来自格陵兰东南穹顶（SE-Dome）的冰芯由于年积累率高（约1米水当量/年），后沉积效应较低，是记录大气化学变化的潜在载体。本文报道了来自SE-Dome冰芯的60年（1959–2014年）δ¹⁵N(NO₃⁻)和Δ¹⁷O(NO₃⁻)记录。δ¹⁵N(NO₃⁻)从1960年到1974年呈下降趋势，并表现出明显的季节变化（夏季高，冬季低）。Δ¹⁷O(NO₃⁻)没有表现出显著的长期趋势，但具有季节变化模式。在1959年至2006年期间，SE-Dome冰芯中δ¹⁵N(NO₃⁻)的质量加权年平均值比格陵兰Summit冰芯低4.2±2.8‰。在SE-Dome条件下，运用大气硝酸盐稳定同位素向雪中迁移（TRANSITS）模型进行估算，结果显示从初始沉积到最终记录，δ¹⁵N(NO₃⁻)仅改变了0.9‰，Δ¹⁷O(NO₃⁻)改变了-0.2‰。尽管不能排除NO₃⁻来源差异的影响，但SE-Dome观测到的δ¹⁵N(NO₃⁻)值低于Summit很可能是由于后沉积改造较弱所致。因此，SE-Dome冰芯的硝酸盐记录能够精确重建北美和西欧的氮氧化物（NOx）排放，以及大气氧化化学和传输过程，从而为理解大气氮循环提供可靠的见解。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['大气硝酸盐','稳定同位素','SE-Dome冰芯','后沉积改造','氮循'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"Hattori, Shohei","en_name":"","@id":"a3970736-2980-4936-8726-2be694bbed1c","email":"hattori@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 2286658, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":2286658,"name":"zip"}]'::jsonb, 'Hattori, Shohei', 'hattori@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('c92147aa3b7c459bafeda7d86df160d3', '697a01e89b1b491785ba3ef55d46ebf2', '重晶石记录的海水氧同位素组成历史数据集', NULL, '海水的氧同位素组成（δ¹⁸O_seawater）受高温和低温条件下水-岩相互作用的塑造，反映了地球系统的动力学和演化。δ¹⁸O_seawater的历史仍存在争议，部分原因在于所有现有的矿物代用指标都受到了后沉积改造的影响。硫酸盐矿物中的氧原子是最难与外界发生交换的，但它们通常与周围水体的同位素不平衡。然而，在微生物硫酸盐还原过程中，随着相应的δ³⁴S_sulfate增加，δ¹⁸O_sulfate可能达到一个平台或趋近于与δ¹⁸O_seawater的平衡。本文展示了跨越显生宙六个时期的289组沉积重晶石的δ¹⁸O-δ³⁴S配对数据。δ¹⁸O-δ³⁴S演化轨迹表明，不同时期的平衡δ¹⁸O_barite值存在差异。如果假设相同的形成温度，石炭纪之前的δ¹⁸O_seawater值比现今明显低约4‰。利用重晶石的δ¹⁸O-δ³⁴S轨迹方法，我们如今拥有了一个强有力的代用指标来推进长期争论的海水δ¹⁸O历史问题', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['海水氧同位素','重晶石','硫酸盐还原','δ¹⁸O-δ³⁴S协同变化'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"Bao, Huiming","en_name":"","@id":"c755117b-4c46-4b82-96f0-087b01b8efb1","email":"bao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者', 1877611, 2, NULL, 2, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1},{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":125908,"name":"xlsx"},{"storageNum":1751703,"name":"pdf"}]'::jsonb, 'Bao, Huiming', 'bao@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('f8d19b60e9414d5c9cae1956aec06344', '2a7bafed419843c9bdb37341a999aa20', '西藏中部广泛分布的早白垩世弧型岩浆岩揭示了新特提斯洋的俯冲板片回撤数据集', NULL, '大陆岩浆弧中岩浆作用的时空分布通常伴随着火成岩成分的变化。然而，在古岩浆弧中，岩浆作用的变化轨迹和地球化学亲和性是否以及如何有效地用于重建俯冲极性，目前尚不清楚。本研究提供了新的年代学、矿物学、地球化学以及Sr-Nd-Hf同位素数据，以刻画西藏中部拉萨地块中部则弄群早白垩世（约130–110 Ma）双峰式火山岩的特征。数据显示，则弄群火山岩以流纹岩和英安岩为主，次为玄武岩，局部有安山岩。玄武岩具有富集的Sr-Nd-Hf同位素组成和弧型微量元素特征，表明其源区为尖晶石稳定域内的岩石圈地幔，并有少量软流圈地幔的贡献。安山岩具有相似的Mg#值和同位素组成，指示其为玄武质岩浆分异的产物。同期的英安岩和流纹岩显示出相对较低的Mg#值和变化的同位素组成，指向古老下地壳源区并有少量地幔物质的贡献。火山岩的双峰式成分特征以及对比鲜明的岩浆源区表明其形成于伸展构造背景。我们认为，拉萨地块中部早白垩世（约130–110 Ma）岩浆活动向北迁移，是俯冲的新特提斯洋板块发生板片回撤（slab rollback）所导致的弧后裂谷作用的结果。该弧后裂谷模型有助于解释更广泛区域内在约130–110 Ma期间的沉积-岩浆演化记录，包括日喀则弧前盆地的扩张、冈底斯岩浆弧的岩浆活动间歇期，以及拉萨地块中部的火山-沉积岩记录', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['板片回撤','双峰式火山岩','则弄群','拉萨地块','新特提斯洋','弧后裂'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"胡修棉","en_name":"","@id":"fbe0f7b6-cab7-4a4e-9a3c-06da1e90e59e","email":"huxm@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 4065551, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":4065551,"name":"zip"}]'::jsonb, '胡修棉', 'huxm@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('bc0e65489cc644459562f33420dfca21', '54aa3e94af51493f88fb02f506582dc4', '西藏中部晚侏罗世至早白垩世同碰撞海沟序列记录了微陆块在拉萨–羌塘碰撞中的作用数据集', NULL, '作为早新生代印度-亚洲碰撞之前最近的一次碰撞事件，拉萨地体与羌塘地体的缝合导致了地壳增生和岩石圈结构的形成，极大地影响了西藏中部随后的新生代岩石隆升。在拉萨地体和羌塘地体之间的班公湖-怒江缝合带内发现的数个微陆块，可能暗示存在多期缝合阶段，然而，这些地体是如何以及何时发生缝合的，仍然存在很大争议。本文报道了新发现的一套晚侏罗世至早白垩世的深水重力流扇沉积序列，该序列位于新生代伦坡拉盆地以南的杰努山地区，厚度超过660米。通过运用多指标、单颗粒物源分析和沉积物混合物正演模拟，我们发现这些碎屑物沉积于一个同碰撞海沟环境中，其物源来自东卡错微陆块、仰冲蛇绿岩—俯冲杂岩、增生的海山以及火山弧岩石。我们解释这一海沟沉积的发生是由于晚侏罗世至早白垩世期间，拉萨地体向東卡错微陆块及其他增生地体之下发生碰撞俯冲所致。已经缝合的东卡错微陆块构成了伦坡拉盆地的基底，并且推断在向西沿走向的较窄的尼玛、改则和阿翁错盆地之下并不存在该基底，这些盆地要么宽度更窄，要么随时间表现出急剧的相变。本研究强调了中生代构造继承性对青藏高原新生代隆升的重要控制作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学','沉积学'], ARRAY['拉萨–羌塘碰撞','微陆块','班公湖-怒江缝合带','同碰撞海沟','物源'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"胡修棉","en_name":"","@id":"fbe0f7b6-cab7-4a4e-9a3c-06da1e90e59e","email":"huxm@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 7807938, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":7807938,"name":"zip"}]'::jsonb, '胡修棉', 'huxm@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('78f486f879334129bff0240d28ca80a4', 'bfe53e2df597482fbb1d3ce8d2e74ebc', '人类活动导致的伊洛瓦底江侵蚀加速与泥沙通量增加数据集', NULL, '人类活动对全球气候和自然生态系统具有强烈影响，但其对长期自然侵蚀过程的影响程度仍然缺乏定量评估。以亚洲输沙量排名第二的伊洛瓦底江为研究对象，本文揭示了流域内广泛的人类活动已显著加速侵蚀速率，使其远超自然基准水平，从而成为该河高输沙量的重要原因。为此，我们对比了基于现代泥沙通量计算的现代侵蚀速率与基于碎屑磷灰石裂变径迹（AFT）和宇宙成因核素¹⁰Be数据获得的长期自然侵蚀速率。结果显示出鲜明对比：长期自然侵蚀速率在伊洛瓦底江上游（0.06–0.34 mm/a）明显高于钦敦江上游（0.02 ± 0.005 mm/a）；而现代侵蚀速率在钦敦江上游（0.63 ± 0.05 mm/a）却是伊洛瓦底江上游（0.19 ± 0.02 mm/a）的三倍。特别值得注意的是，钦敦江上游和穆河流域的侵蚀速率相比长期自然背景值增加了一个数量级以上。这种侵蚀速率的显著增加与冲积型采矿的空间分布呈正相关，尤其是在钦敦江上游流域。从长期到现代时间尺度上观测到的泥沙通量增加，还可能归因于土地利用扩张导致的森林砍伐以及降水增强。这些结果强调了人类活动如何能够极大地加速侵蚀过程，从而对自然系统产生剧烈影响。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','沉积学'], ARRAY['人类活动','侵蚀速率','泥沙通量','伊洛瓦底江','钦敦江','磷灰石裂变'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"胡修棉","en_name":"","@id":"fbe0f7b6-cab7-4a4e-9a3c-06da1e90e59e","email":"huxm@nju.edu.cn"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李广伟","en_name":"","@id":"6ec5af19-641f-4f9d-b6e9-ae65ae2aa06b","email":"guangweili@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 3099406, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":3099406,"name":"zip"}]'::jsonb, '胡修棉', 'huxm@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('946a2c1ad29f47a5ad83c795088f6662', '15a08e7eb9ed4ced9276ca40d968ef28', '褶皱冲断带中盐下裂谷盆地的叠加变形：来自物理模拟的启示数据集', NULL, '裂谷反转在褶皱冲断带的缩短 accommodating 过程中扮演着重要角色，但常常被同裂谷期之后的盐岩层所掩盖，这使得变形序列复杂化，并遮蔽了下伏的盐下反转构造。本研究利用四个等比例物理模拟实验，结合粒子图像测速技术，探讨了同裂谷期之后的盐岩层对盐下裂谷反转的应变演化和最终构造几何形态的影响。实验结果表明，盐岩层使变形发生解耦，促使上覆盐层在早期发生薄皮缩短作用，这一过程先于下伏盐下裂谷盆地的反转，并使其反转发生延迟。裂谷反转开始于微弱的盆地隆升，反映了早期的应变局部化，这可能同时引导了盐上薄皮逆冲断层的成核以及后续盐下逆冲断层的局部化。随后的变形主要通过新生成的、低角度（12°–22°）的逆冲断层（例如下盘捷径断层）来容纳，这些断层切割了裂谷盆地，其形成受陡倾（58°–81°）的先存正断层发生摩擦锁定的控制。这一过程在单盆地和多盆地反转背景下均产生了特征的“鱼叉”几何形态，其特征为陡倾的正断层被低角度下盘捷径逆冲断层所截切，并伴生上盘背斜，这与在西喀尔巴阡外带和柯坪褶皱冲断带观测到的构造相似。这些发现突显了同裂谷期之后的盐岩层在控制盐下裂谷反转运动学中的关键作用，并为解释地震成像常常模糊不清的深层反转样式提供了一个框架', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','构造地质学（包括显微构造学等）'], ARRAY['裂谷反转','盐构造','物理模拟','褶皱冲断带','叠加变形','下盘捷径'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"贾东","en_name":"","@id":"dcad8a7e-433b-41ac-bb72-a130b598a7d3","email":"djia@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 18113800, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":18113800,"name":"zip"}]'::jsonb, '贾东', 'djia@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('35e14960454f449d88426b4152366ee3', '109534ce30bf4444a0f49eb5cff0e91b', '印度-亚洲板块的汇聚：来自印度-亚洲碰撞带内白垩纪至早新生代盆地碎屑热年代学的启示数据集', NULL, '印度-亚洲碰撞带内的同碰撞盆地保存了有关印度-亚洲汇聚的重要记录。本研究报道了来自印度河-雅鲁藏布缝合带南侧的目巴拉剖面和北侧的措江顶剖面的一套新的锆石双定年（裂变径迹和U-Pb）和磷灰石裂变径迹（AFT）数据。在缝合带南侧的目巴拉剖面，锆石U-Pb和裂变径迹（ZFT）年龄数据显示了从印度物源向亚洲物源的显著转变，证实了印度-亚洲初始碰撞发生在约60 Ma。来自印度物源地层的ZFT主导年龄范围揭示了泛非造山运动以及冈瓦纳亲缘地体中的几个构造-热事件。来自冈底斯物源地层的ZFT显著年龄范围指示了印度-亚洲汇聚期间冈底斯岩浆弧的四期构造-热事件：早白垩世年龄范围与新特提斯洋的俯冲相关；约90 ± 3 Ma的显著年龄范围与新特提斯洋中脊俯冲有关；约73 ± 4 Ma的平均年龄范围可能归因于新特提斯板片的平俯冲；随后约60 ± 2 Ma的主导年龄范围记录了印度-亚洲碰撞。此外，热历史模拟表明，同碰撞盆地可能连续沉积到始新世最晚期，被特提斯喜马拉雅褶皱冲断带的活动所终止。在缝合带北侧的措江顶剖面，完全重置的AFT年龄（约17–20 Ma）和部分重置的ZFT年龄（约21–119 Ma）暗示了大反向逆冲断层的活动。总体而言，碰撞带的构造-热事件可以与印度-亚洲汇聚的构造过程很好地关联起来。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','构造地质学（包括显微构造学等）'], ARRAY['印度-亚洲碰撞','碎屑热年代学','锆石裂变径迹','磷灰石裂变径迹'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李广伟","en_name":"","@id":"6ec5af19-641f-4f9d-b6e9-ae65ae2aa06b","email":"guangweili@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 380463, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":380463,"name":"zip"}]'::jsonb, '李广伟', 'guangweili@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('7b0e1ad44a254f7e884005d835d9c912', '95b63f58911e44019bcfdd3bccb33a3c', '隐藏在扬子地块内部的一条长约700公里的成冰纪岩浆弧带数据集', NULL, '古岩浆弧保存了关于新生岩浆作用、地壳生长和分异的重要档案，从而有助于我们理解大陆的演化历史。然而，一些古老的岩浆弧位于大陆内部，被厚厚的盖层所掩埋，这使得它们的识别具有挑战性。本文通过深钻孔、地质年代学、地球化学和地球物理学等多学科数据，研究了华南扬子地块四川盆地的基底性质与演化历史。这些结果为扬子地块内部隐藏着一条大型成冰纪岩浆弧带提供了证据。
七个深钻孔（深度约3,600–6,500米）穿透了盆地基底，结合地质年代学和三维地震反射剖面，揭示了大面积的成冰纪（约820–770 Ma）流纹岩/花岗岩被埃迪卡拉纪沉积岩所覆盖。航磁数据描绘出一条横跨盆地中部的北东-南西走向、长约700公里的正磁异常带，指示了下地壳中存在超基性/基性岩石。岩石成因分析表明，在正磁异常带范围内钻遇的成冰纪长英质岩石很可能来源于新生弧玄武质源区。因此，我们认为该正磁异常带记录了幔源熔体的输入及其随后向花岗质岩浆的演化，这与扬子地块内部曾经存在的成冰纪弧岩浆前锋带有关。
我们的发现拓宽了该区域成冰纪大陆弧系统的范围，表明其从地块西北边缘向内陆延伸至少达400–900公里。如此宽阔的造山系统在扬子地块的大陆演化、元素循环和盆地形成中发挥了至关重要的作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['成冰纪','岩浆弧','扬子地块','四川盆地','航磁异常','深钻孔'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李军勇","en_name":"","@id":"99c59f2e-84f7-4921-92b1-b425b68fa7f3","email":"ljy@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 3515408, 2, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":198616,"name":"zip"},{"storageNum":3316792,"name":"docx"}]'::jsonb, '李军勇', 'ljy@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('4418df1845bd438db66f5957feba4688', '1611b690b3c441e49e34bfab17a90e5f', '赤铁矿表面络合过程中稳定钼同位素分馏：来自从头算分子动力学和X射线吸收光谱的分子尺度认识数据集', NULL, '铁（氢）氧化物是多种环境条件下钼（Mo）的关键吸附剂。其中，赤铁矿（α-Fe₂O₃）是地表条件下最稳定的铁氧化物；然而，在不同pH条件下，Mo在赤铁矿上同位素分馏的程度及其分子尺度机制仍缺乏深入认识。本研究在pH 5.0–9.0范围内开展了一系列Mo吸附实验，以探究其同位素分馏特征，并识别出酸性和碱性条件下的两种不同分馏机制。Mo同位素分馏在pH 4.0–7.0之间保持相对恒定，Δ⁹⁸Mo[Mo(aq)-Mo(hematite)] ≈ 2.10‰，表明对pH敏感性很低。但在pH高于7时，分馏显著减小，在pH 8时降至1.80‰，在pH 9时降至1.37‰。
从头算分子动力学模拟表明，Mo在水-赤铁矿界面主要以五配位络合物形式存在。这一结构特征得到了Mo K边X射线吸收近边结构光谱的支持，该光谱显示吸附态Mo的局域配位环境不同于MoO₃（八面体构型），且不能简单用四面体和八面体物种的混合来解释。扩展X射线吸收精细结构分析得出平均Mo–O配位数在pH 5.0时为4.3 ± 0.9，在pH 7.0时为4.7 ± 0.9，与先前观测结果（5.3 ± 0.6）一致，从而证实了五配位Mo物种的主导地位。
计算得到的这种五配位络合物在20°C下的理论同位素分馏值为Δ⁹⁸Mo[Mo(aq)-Mo(five-fold complex)] = 2.01‰，与我们的实验结果（Δ⁹⁸Mo[Mo(aq)-Mo(hematite)] = 1.899 ± 0.322‰）以及先前数据（2.19 ± 0.54‰）高度吻合。一个同时包含五配位和四面体Mo络合物的双组分模型成功再现了观测到的pH依赖性分馏趋势。综合这些发现表明，Mo在赤铁矿上的同位素分馏具有强pH依赖性，并受表面络合几何构型变化的控制，这对于从大陆风化剖面到水体迁移路径等自然和人为影响系统中Mo同位素作为示踪剂的应用具有重要意义。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','实验地球化学'], ARRAY['钼形态','赤铁矿','五配位络合物','从头算分子动力学','同位素分馏'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李伟","en_name":"","@id":"6ff3124f-f464-4eb1-8c0a-5f19cc871dde","email":"liwei_isg@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 498359, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":498359,"name":"docx"}]'::jsonb, '李伟', 'liwei_isg@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('ea174b0d782e4642a281ebad9e982fe7', 'd376201c2e3e466cb4ea58756e9d7bd7', '磷酸盐与方解石的共沉淀：掺入和包裹机制的分子尺度证据数据集', NULL, '磷酸盐在碳酸钙矿物中的共沉淀是海洋沉积和洞穴石笋形成中普遍存在的地球化学现象，然而，磷酸盐是否掺入到方解石结构中尚不清楚。在本研究中，我们应用固态核磁共振（NMR）光谱分析了磷酸盐与方解石共沉淀过程中磷的形态。³¹P NMR结果显示三个化学位移分别为3.9、3.0和-1.0 ppm的峰，表明共沉淀物中至少存在三种磷酸盐物种。
结合先进的³¹P{¹H}交叉极化（CP）/魔角旋转（MAS）、¹H双回波（DE）/MAS、³¹P{¹H}二维异核相关（HetCor）和³¹P{¹³C}交叉极化旋转回波双共振（CP-REDOT）NMR实验，3.9 ppm峰可初步归属为方解石结构缺陷中的非晶磷酸钙（ACP）类似环境，而3.0 ppm峰来自碳化羟基磷灰石（CHap）。-1.0 ppm处的³¹P NMR峰可归属为以HPO₄²⁻形式结构性地掺入方解石晶体中的磷酸盐。纳米二次离子质谱（NanoSIMS）和高分辨扫描透射电子显微镜（HR-STEM）分析进一步表明，掺入的HPO₄²⁻替代了方解石中的结构碳酸根（CO₃²⁻）。然而，随着HPO₄²⁻掺入方解石结构而产生的局部膨胀应力场阻止了PO₄/CO₃类质同象替代，并有利于磷酸钙的沉淀。本研究的发现不仅为碳酸盐晶体化学提供了深刻见解，而且为碳酸盐材料作为古环境重建中的有效地球化学代用指标的应用提供了启示。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','元素地球化学'], ARRAY['方解石','磷酸盐','掺入','固态核磁共振','纳米二次离子质谱','高分辨'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李伟","en_name":"","@id":"6ff3124f-f464-4eb1-8c0a-5f19cc871dde","email":"liwei_isg@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 499375, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":499375,"name":"pdf"}]'::jsonb, '李伟', 'liwei_isg@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('7b333cd7a1f34f4aacb6f572c16f22f2', '8a46cc7a88054c5faba8e37591e00626', '印度支那和华南地区玻璃陨石成分和结构的变异性：对澳亚玻璃陨石散落区撞击成因的启示数据集', NULL, '澳亚玻璃陨石散落区年龄约为0.8 Ma，覆盖了地球表面近10%的面积，是全球最大、最年轻的玻璃陨石散落区。本研究对从该散落区内不同地点（特别是越南、泰国和华南）回收的玻璃陨石进行了元素组成和结构的综合分析。这些玻璃陨石表现出与正常玻璃陨石相似的上陆壳特征一致的主量和微量元素组成。在印度支那半岛的玻璃陨石中观测到CaO、FeO、MgO、Pb和Sr浓度的显著元素偏差，表明存在多个靶岩组分的混合。与来自中国、印度尼西亚和澳大利亚的玻璃陨石相比，来自泰国和越南的印度支那玻璃陨石显示出较低的Pb和Sr含量，这可能反映了它们靠近假设中的撞击点——老挝的波罗芬高原。在推测的源区陨石坑位置，玄武岩覆盖在红土和砂岩之上的局部地层可能解释了观测到的Pb和Sr浓度降低，这主要归因于砂岩的混入，而变化的MgO、CaO和FeO则暗示了玄武岩的贡献。与华南玻璃陨石相比，印度支那玻璃陨石中焦石英包裹体的高丰度和升高的SiO₂含量突显了靶岩成分在玻璃陨石形成中的作用。条纹状流动构造进一步证实了撞击早期阶段的岩石混合。总体而言，这些发现阐明了玻璃陨石形成、靶岩相互作用和撞击过程之间的关系，支持印度支那半岛是撞击区域的看法，并强调了对元素分馏和靶岩非均质性进行进一步研究的必要性', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','元素地球化学'], ARRAY['澳亚玻璃陨石散落区','印度支那','元素组成','焦石英','靶岩混合','撞'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李伟","en_name":"","@id":"6ff3124f-f464-4eb1-8c0a-5f19cc871dde","email":"liwei_isg@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 148227, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":148227,"name":"zip"}]'::jsonb, '李伟', 'liwei_isg@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('35284a542690465c8e6d92b4812dccff', '0afb7fb5d8bb47bc9781d3a01c69bef4', '微米和纳米针铁矿吸附过程中锌同位素分馏效应的对比数据集', NULL, '针铁矿在控制地表环境中锌的迁移性和行为方面起着至关重要的作用，并能通过吸附过程强烈影响锌同位素分馏。然而，针铁矿的粒径对稳定同位素分馏的影响仍知之甚少。本研究探讨了锌稳定同位素在纳米针铁矿和微米针铁矿上吸附过程中的分馏特征，重点关注反应时间、锌浓度和pH等因素。研究结果表明，在pH 6条件下，纳米和微米针铁矿体系中的锌同位素分馏均在大约48小时后达到平衡。对于纳米针铁矿，无论pH和初始锌浓度如何，吸附态与溶液态锌之间的同位素分馏（Δ⁶⁶Zn_adsorbed–aqueous）保持在约-0.1 ± 0.04‰。在微米针铁矿上吸附时，观测到显著更负的分馏，Δ⁶⁶Zn_adsorbed–aqueous = -0.40 ± 0.04‰。扩展X射线吸收精细结构光谱表明，锌以内层八面体和四面体表面络合物的组合形式结合在纳米针铁矿表面，平均Zn-O键长范围为2.00至2.02 Å。相比之下，在微米针铁矿上，锌主要以扭曲的八面体结构存在，平均Zn-O原子间距为2.09 Å。我们的发现表明，针铁矿中与粒径相关的锌同位素分馏是由纳米和微米针铁矿上形成的锌表面络合物的结构差异所驱动的。这些结果为天然富铁土壤中的锌同位素特征提供了有价值的见解，支持使用锌同位素作为示踪剂来理解土壤环境中受铁矿物影响的锌的归宿。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['针铁矿','纳米尺寸效应','吸附','锌同位素','分馏','扩展X射线吸收精'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李伟","en_name":"","@id":"6ff3124f-f464-4eb1-8c0a-5f19cc871dde","email":"liwei_isg@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 537689, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":537689,"name":"pdf"}]'::jsonb, '李伟', 'liwei_isg@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('8979ee395eba4a5980cca8f8f01e49b7', '413601023cc3496186c51d51c9a5ea8c', '上新世-更新世界限中国黄土沉积物源材料的突然变化：来自钾同位素和模拟的启示数据集', NULL, '中国黄土高原的风成沉积物是晚新生代气候变化和大气环流的关键档案。然而，关于过去约6百万年来粉尘源区稳定性的长期争议限制了我们对黄土高原成因及其古环境意义的理解。本文报道了在约2.58 Ma时期，黄土高原风成沉积物的钾同位素组成（δ⁴¹K）发生了突然降低。黄土/古土壤的δ⁴¹K值（-0.41‰至-0.63‰）低于类似于上地壳平均成分的红黏土的值（-0.35‰至-0.45‰）。此外，风成沉积物的δ⁴¹K值与Na₂O/K₂O和Na₂O/Al₂O₃比值呈负相关，而不同粒级组分的影响可以忽略。这些观测结果表明，δ⁴¹K值并非受黄土高原沉积后风化作用的控制，而是受来自青藏高原东北部风化碎屑或再循环沉积物输出增加的驱动——这一点通过潜在源区物质的钾同位素调查和地球系统模型模拟得到了揭示。我们的结果进一步表明，第四纪期间全球变冷的加剧促进了更多沉积物的侵蚀，并改变了西风带和西伯利亚高压的动力学特征，这对于理解上新世-更新世界线附近的古环境变化以及重建东亚大气环流具有重要意义。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['钾同位素','风成沉积物','中国黄土高原','东亚大气环流','第四纪变冷'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李伟强","en_name":"","@id":"2c658685-4951-4010-ad1b-a5d277bdd9ee","email":"liweiqiang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 2011659, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":2011659,"name":"zip"}]'::jsonb, '李伟强', 'liweiqiang@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('585efe204fb141ec91ba9e9600c50a4a', 'de61f557b6ce49fa921359d911f5089a', '锡同位素非质量分馏对紫外辐射和磁场的敏感性数据集', NULL, '非质量同位素分馏（MIF）为各种地质和行星问题提供了强大的地球化学示踪剂，然而驱动锡（Sn）同位素MIF的机制仍然不明确。本研究证明，在实验室紫外辐照和自然太阳光照射下，有机锡物种（即甲基锡）的光解过程中产生了独特的锡同位素分馏信号。紫外辐照甲基锡在所有奇数锡同位素中引发了显著的Sn-MIF（Δ¹¹⁵Sn高达21.82‰，Δ¹¹⁷Sn高达23.16‰，Δ¹¹⁹Sn高达24.01‰），其比值（Δ¹¹⁷Sn/Δ¹¹⁵Sn = 1.069；Δ¹¹⁹Sn/Δ¹¹⁵Sn = 1.099；Δ¹¹⁹Sn/Δ¹¹⁷Sn = 1.028）与核磁矩高度相关。这明确地将磁同位素效应（MIE）确定为驱动机制，排除了核体积效应等其他原因。在甲基锡光解实验中检测到了甲基自由基（•CH₃），并且锡的MIF幅度因存在电子自旋捕获剂（DMPO）而受到抑制，这支持了显著的Sn-MIF源于自由基介导的锡物种单重态-三重态跃迁的观点。此外，Sn-MIF的幅度随外部磁场呈非单调变化（在100至180 G时出现峰值抑制），表明超精细耦合与塞曼相互作用之间存在竞争。值得注意的是，在自然太阳光照射下甲基锡的光解过程中，尽管存在显著的质量相关锡同位素分馏（例如δ¹²²/¹¹⁶Sn > 3‰），但未观察到Sn-MIF，这归因于大气臭氧对产生自由基所需的短波紫外（<290 nm）的屏蔽作用。我们的研究结果将Sn-MIF作为低氧环境中紫外驱动光化学的灵敏示踪剂，强调了锡同位素在早期地球大气和行星环境研究中的潜力。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['锡同位素','非质量分馏','磁同位素效应','紫外辐射','甲基锡','自由基'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李伟强","en_name":"","@id":"2c658685-4951-4010-ad1b-a5d277bdd9ee","email":"liweiqiang@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 2243062, 5, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":4},{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":112965,"name":"xlsx"},{"storageNum":2130097,"name":"pdf"}]'::jsonb, '李伟强', 'liweiqiang@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('31b72b076d1f4d62b4de5e4ada1d47d6', '23d77592b9594d4da41477c5e1d7059d', '雅鲁藏布江缝合带中的古海山揭示了早白垩世新特提斯岩石圈的动力学过程数据集', NULL, '对于被捕获在大陆缝合带中的洋壳海山的动力学过程，目前了解甚少。雅鲁藏布江缝合带中海山序列的发现与分析，使我们能够探测新特提斯洋东部的垂向岩石圈运动。本研究采用岩石学、地球化学、岩相学、古生物学和地层学方法，对西藏仲巴地区基性岩和沉积岩构成的复合块体进行了研究。放射虫化石指示其时代为早白垩世早期。岩石相和地球化学分析表明，大部分玄武岩呈枕状熔岩产出，富集轻稀土元素和高场强元素，指示洋岛玄武岩的构造背景。沉积岩相可划分为角砾岩、页岩、燧石和灰岩（包括鲕粒灰岩和同心粒灰岩微相）。玄武岩基底与盖层之间存在三种接触类型：规则型、塌积型和侵蚀型。研究结果表明，在雅鲁藏布江缝合带西段，存在两个此前未知的叠加海山，它们至少由八个从玄武岩到沉积岩的海山序列组成。盖层岩相和海山结构特征表明，仲巴古海山整体记录了多次由快速沉降和抬升（岩石圈的“隆与降”）引起的突然加深-变浅旋回，水深变化范围从约3000米到约5米。为了解释这种动态的沉降与抬升过程，我们提出了“洋流旁通复发与地幔柱更生”模型。当地幔柱活动产生基性基底并带来显著的浮力抬升时，洋壳因旁通漂移而逐渐远离地幔柱，导致冷却、浮力丧失和快速沉降。该模型为解释已消失洋壳的演化提供了一种新的思路。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['古海山','雅鲁藏布江缝合带','早白垩世','新特提斯洋','岩石圈动力学'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李祥辉","en_name":"","@id":"e3ba3f97-f4e4-46b0-9a08-37a247a73c83","email":"seanlee@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 575851, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":575851,"name":"zip"}]'::jsonb, '李祥辉', 'seanlee@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('6687b7b92c154a61914b5eec7fdba346', '095c244bb333415ebbc8110f7465eeea', '新特提斯洋东部阿尔布期-塞诺曼期界线（OAE 1d）升高的δ¹³C值：对潜在超级营养水团的启示数据集', '', '发生在阿尔布期-塞诺曼期界线的大洋缺氧事件（OAE）1d被认为是一个全球性古海洋学现象。然而，由于对古地理和古海洋背景的数据有限，包括碳同位素、生物群和生产力等关键代用指标的一致性仍不明确。为弥补这一空白并探究新特提斯洋东部的OAE 1d记录及其全球对比关系，本研究对西藏中部措勤盆地郎山组进行了生物地层学、化学地层学和岩相学的综合分析。综合地层学将郎山组上第二段至下第三段的时代确定为晚阿尔布期至早塞诺曼期，并圈定了OAE 1d的层位。研究识别出八种微相（MF1–MF8），将其沉积环境解释为从碳酸盐台地斜坡到深水陆棚，并伴有少量开阔台地和局限台地内部环境。新特提斯洋内碳同位素偏移阶段A–D的对比以及不同海区之间的差异表明，OAE 1d可能在超大区域尺度上表现显著，这对将其视为严格全球性事件的观点提出了挑战。值得注意的是，在晚阿尔布期，新特提斯洋东部展现出异常高的平均δ¹³C值（3.83–3.91‰），是新特提斯洋南部的四倍，几乎是其他海区的两倍，表明存在地理上差异化的水团条件。有利的古环境因素，包括低纬度位置、受限的陆间陆表海、多重营养来源以及火山活动，被认为是形成超级富营养水团和高生产力的驱动因素。这些条件很可能导致了δ¹³C值的升高，并为与OAE 1d相关的古地理和古海洋动力学提供了新的见解', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','沉积学'], ARRAY['水团','碳同位素','阿尔布期-塞诺曼期过渡','郎山组','西藏中部','古'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李祥辉","en_name":"","@id":"e3ba3f97-f4e4-46b0-9a08-37a247a73c83","email":"seanlee@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 81482, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":81482,"name":"zip"}]'::jsonb, '李祥辉', 'seanlee@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('e6dd5cde483448f8b35f7313f72421b0', 'c45336cb9a6a4ff390b9a96564be36ed', '寒武纪华北板块的位置：来自生物地层学、化学地层学和磁性地层学综合约束数据集', NULL, '由于华北板块早古生代古地磁极的极性 ambiguity，其古生代的古地理和构造演化一直缺乏有效约束。本文报道了华北板块两个上寒武统以石灰岩为主的海相剖面的磁性地层学研究结果，这些剖面记录了斯蒂普阶正碳同位素漂移事件——一次伴随三叶虫灭绝的全球碳循环扰动。逐步热退磁揭示了三组分剩磁，其中高温组分通过古地磁学和岩石磁学分析被确认为原生剩磁。研究建立了华北板块跨SPICE的复合极性序列，并与西伯利亚同时期的极性序列进行对比，从而确定华北板块在SPICE期间处于反向极性期。这种洲际对比，结合古生物地理学的亲缘性，支持华北板块在晚寒武世位于南半球低纬度地区、东冈瓦纳大陆西侧邻近的位置，从而为古生代东冈瓦纳大陆周围的古地理-构造重建提供了进一步的约束。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','地层学与地史学','古生物学'], ARRAY['华北板块','寒武纪','磁性地层学','SPICE','古地理','冈瓦纳'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李永祥","en_name":"","@id":"abce85b8-06b3-49ca-ab30-40062304cd80","email":"yxli@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 4321501, 3, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1},{"name":"txt","count":1},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":45200,"name":"xlsx"},{"storageNum":309663,"name":"txt"},{"storageNum":3966638,"name":"docx"}]'::jsonb, '李永祥', 'yxli@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('e1aa0a58673b4136824968f2d8d8beab', 'aa102ee156f44da1b218b89a99756d07', '铁同位素证据揭示热液来源营养盐在大洋缺氧事件2期间触发初级生产力提高数据集', NULL, '大洋缺氧事件2（OAE2，约94 Ma）代表了白垩纪中期温室时期的一次重大全球碳循环扰动，通常归因于营养盐增加所刺激的生物初级生产力提高。然而，增加的营养盐是来源于海底火山作用还是增强的大陆风化作用仍不清楚。本文报道了西藏南部贡扎剖面高分辨率的OAE2层段全岩铁同位素记录，以追踪跨OAE2期间通过生物、地质和地球化学过程的铁循环。δ⁵⁶Fe_T数据显示了三次显著的负偏移，对应于锇同位素记录所记载的火山活动增强期；其中最大的一次负偏移之后，伴随着与OAE2的δ¹³C正漂移同时期的长时间正δ⁵⁶Fe_T偏移，这与热液来源的铁与生物吸收之间存在因果关系的观点一致。在其他不同沉积环境的OAE2剖面中也观察到了类似的δ⁵⁶Fe_T变化模式，表明海底火山作用是启动OAE2的驱动力。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['大洋缺氧事件2','铁同位素','热液','初级生产力','火山作用'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"李永祥","en_name":"","@id":"abce85b8-06b3-49ca-ab30-40062304cd80","email":"yxli@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 29245, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":29245,"name":"zip"}]'::jsonb, '李永祥', 'yxli@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('2112ae76b9894d37b9f52e20d2d17b32', 'ccc842590425465fa1543b136505008a', '北祁连造山带中的格林威尔期S型花岗岩：对罗迪尼亚超大陆地球动力学演化的启示数据集', NULL, '识别显生宙造山带内前寒武纪微陆块的构造位置和亲缘关系，是揭示全球古地理和早期地球超大陆演化的关键。柴达木陆块被认为是一个被数条古生代造山带包围的前寒武纪大陆碎片，在中元古代到新元古代期间参与了罗迪尼亚超大陆的拼合与裂解。然而，柴达木陆块在罗迪尼亚超大陆中的详细构造位置仍然缺乏约束。本文对北祁连造山带鱼卡地区的格林威尔期花岗质片麻岩进行了年代学、地球化学、锆石Lu-Hf同位素以及热力学模拟的综合研究。鱼卡花岗质片麻岩的原岩形成于905–908 Ma。这些岩石以富铝为特征，含有富铝矿物（如石榴子石、白云母和黑云母），并且铝饱和指数高（1.03–1.20），属于S型花岗岩。锆石Lu-Hf同位素显示出不均一的εHf(t)值（-9.7至+1.6）和古元古代-中元古代的模式年龄（2319–1651 Ma），同时存在跨越太古宙-新元古代的捕虏锆石（2558–937 Ma）。这些特征共同表明，它们是由包含太古宙-新元古代碎屑物的新元古代富Zr变沉积岩部分熔融形成的。相平衡图和微量元素模拟进一步表明，鱼卡905–908 Ma花岗质片麻岩可能是在690–820°C条件下，变沉积岩发生不同程度含水部分熔融（F = 0.12–0.60）的产物。结合柴达木陆块周围中元古代晚期至新元古代的岩浆和变质记录，我们认为柴达木陆块经历了格林威尔期（1.10–0.85 Ga）的俯冲-碰撞事件，随后发生了0.85–0.60 Ga的非造山和大陆裂谷事件。通过与罗迪尼亚超大陆中其他主要克拉通和大陆的全面对比，表明柴达木陆块可能位于澳大利亚西南部、印度和东南极洲的核心部位，与华北、塔里木和扬子克拉通没有直接的亲缘关系。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['格林威尔造山运动','S型花岗岩','热力学模拟','柴达木陆块','罗迪尼'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"连东洋","en_name":"","@id":"5b8dbb77-7340-4299-8111-22b3c958e55d","email":"ldy199008@163.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
