  ('581470ac36424476a302306b7243f677', '3bafd6c2deac43ce80d7803cbd15b462', '来自循环古老地壳的渗透熔体对大洋岩石圈地幔的改造：来自难熔方辉橄榄岩中Ca-Os同位素的证据数据集', NULL, '大洋岩石圈地幔最初形成于大洋板块的扩张中心下方，经常通过与向上迁移至地壳区域的幔源基性熔体相互作用而发生改变。高度难熔的方辉橄榄岩通常保留了微量的间隙单斜辉石和贱金属硫化物，这些矿物是在与渗透熔体相互作用过程中沉淀形成的。本研究展示了古巴Moa-Baracoa蛇绿岩中方辉橄榄岩的全岩和矿物Ca以及Re-Os同位素组成，以揭示熔体-橄榄岩相互作用过程并评估其对岩石圈地幔组成的影响。
热力学模拟表明，与亏损的大洋中脊玄武岩地幔相比，所研究的方辉橄榄岩经历了高程度（20–30%）的部分熔融，随后在岩石圈地幔内与极少量的弧前玄武质熔体（<2%）发生相互作用。全岩δ⁴⁴/⁴⁰Ca值范围为1.06‰至1.31‰，低于经历了20–30%部分熔融的高度难熔方辉橄榄岩的计算值，这表明存在由具有轻δ⁴⁴/⁴⁰Ca值的间隙单斜辉石引起的偏移。此外，升高的¹⁸⁷Os/¹⁸⁸Os比值（0.1271–0.1401），结合低的Re浓度（0.03–0.64）和低的¹⁸⁷Re/¹⁸⁸Os比值（0.08–1.40），暗示了放射性Os的加入，这些Os要么来自俯冲板片，要么来自地幔中循环的古老地壳组分。¹⁸⁷Os/¹⁸⁸Os比值随δ⁴⁴/⁴⁰Ca值降低而增加的趋势，进一步证实了Moa-Baracoa方辉橄榄岩中硫化物和单斜辉石的共同沉淀。值得注意的是，在某些深海橄榄岩和蛇绿岩橄榄岩中也观察到类似的矿物组合和全岩放射性Os组成。二元混合计算表明，只有当从源自循环古老地壳的小比例渗透基性熔体中沉淀出罕见的贱金属硫化物时，才可能出现这种Re-Os特征。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['Re-Os同位素','熔体-橄榄岩相互作用','循环古老洋壳','地幔方'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"连东洋","en_name":"","@id":"5b8dbb77-7340-4299-8111-22b3c958e55d","email":"ldy199008@163.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 3911021, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":3911021,"name":"zip"}]'::jsonb, '连东洋', 'ldy199008@163.com', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('89081f5b45eb4303ae9a00496f49a764', '1597942546be4a5988bb721c0531cc95', '阿曼塞迈尔蛇绿岩Geotimes熔岩记录的大洋上地壳海底热液蚀变过程中的铁同位素分馏数据集', NULL, '阿曼的塞迈尔蛇绿岩具有类似于快速扩张的现代大洋岩石圈的地壳层序。其Geotimes枕状熔岩是地层上最底部的最古老喷出序列，与当代大洋中脊玄武岩具有相似的地球化学特征，为研究不同氧化还原条件下热液蚀变过程中的铁（Fe）同位素分馏提供了独特的机会。显著的蚀变改变了原生矿物，表现为单斜辉石、斜长石和钛铁矿的溶解，以及绿泥石、钠长石和磁铁矿-赤铁矿的沉淀。来自蚀变枕状熔岩的18个玄武岩子样品的⁸⁷Sr/⁸⁸Sr比值范围为0.705110至0.705680，表明与海水发生了广泛的相互作用。δ⁵⁶Fe值在厘米尺度上显示出系统性变化（0.037–0.291‰），这主要是由热液过程而非源区继承造成的。值得注意的是，枕状熔岩的核心显示出较高的δ⁵⁶Fe值，表明在还原条件下含铁矿物发生了初始溶解。相比之下，边缘显示出类似于平均大洋中脊玄武岩的较低δ⁵⁶Fe值，表明强氧化条件对这些同位素值的影响极小。总之，本研究揭示了在不同氧化还原条件下遭受热液蚀变的蚀变玄武岩的铁浓度和铁同位素组成的复杂变化。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['海底蚀变','洋壳','Geotimes熔岩','铁同位素分馏','Sr-N'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"连东洋","en_name":"","@id":"5b8dbb77-7340-4299-8111-22b3c958e55d","email":"ldy199008@163.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 4126678, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":4126678,"name":"zip"}]'::jsonb, '连东洋', 'ldy199008@163.com', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('35c349a48fa144f3954ef7352c6b952b', 'c531a373871e46d5be05766b8157a4c8', '中国主要豆荚状铬铁矿床的岩石学、矿物学和地球化学特征：对其成因的启示数据集', NULL, '在中国，豆荚状铬铁矿床是国内铬铁矿供应的主要来源。这些主要铬铁矿床分布在西藏雅鲁藏布江缝合带内的侏罗纪-早白垩世蛇绿岩中，以及内蒙古和新疆的古生代蛇绿岩中。为了阐明中国铬铁矿成矿过程中的成矿作用及相关构造背景，本研究深入探讨了采集自西藏（罗布莎、普兰、东波、巴尔、错不扎和达吉翁）、新疆（萨尔托海）和内蒙古（贺根山）等蛇绿岩中代表性铬铁矿石样品的岩石学、矿物学和地球化学特征。
根据铬铁矿的成分，这些铬铁矿石可分为高铬型和高铝型。铬铁矿中的矿物包裹体主要由硅酸盐矿物、贱金属硫化物和多种铂族矿物组成。与高铝型铬铁矿石相比，高铬型铬铁矿石中更常检测到铂族矿物包裹体。雅鲁藏布江缝合带蛇绿岩中的铬铁矿石主要为高铬型（Cr# 66–82），表明其形成于俯冲带上覆环境中的玻安质熔体。贺根山和萨尔托海铬铁矿石典型为高铝型（Cr# 50.5–52.8），是由类似大洋中脊玄武岩的岩浆形成的。综合围岩信息，我们得出结论：中国的主要铬铁矿床与俯冲带上覆环境中的不同岩浆作用阶段密切相关，特别是在俯冲起始阶段。对于未来的铬铁矿找矿勘探，我们提出沿藏南雅鲁藏布江缝合带的蛇绿岩体具有巨大潜力。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学','矿床学与矿相学（包括放射性矿床学，不包括石油、天然气和煤）'], ARRAY['铬铁矿床','雅鲁藏布江缝合带','萨尔托海蛇绿岩','贺根山蛇绿岩','铬'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"连东洋","en_name":"","@id":"5b8dbb77-7340-4299-8111-22b3c958e55d","email":"ldy199008@163.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 60128, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":60128,"name":"xlsx"}]'::jsonb, '连东洋', 'ldy199008@163.com', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('db18925c73c34c74a365a47479414115', '4a9486fc974449f59fc5860a8aab38df', '大洋和大陆板片来源的埃达克质熔体大规模注入地幔楔数据集', NULL, '地幔楔交代作用是俯冲带中普遍存在的现象。然而，关于早期熔体生成以及交代作用范围的细节尚不清楚。本文在北祁连超高压变质带的地幔楔内发现了两种不同类型的埃达克质长英质岩石。这些野外观察为大规模地幔楔交代作用提供了直接证据。锆石和磷灰石U-Pb定年表明俯冲板块经历了快速折返和冷却。Sr-Nd-Hf同位素分析，结合部分熔融的相平衡正演模拟，表明这些埃达克质岩脉要么通过单一陆壳源区的部分熔融形成，要么通过洋壳和陆壳来源熔体的混合形成。这些发现强调了在碰撞造山事件期间，大洋和大陆地壳来源的熔体在大陆地壳生长和演化中的关键作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['埃达克质熔体','地幔楔交代','北祁连','超高压变质带','部分熔融'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"连东洋","en_name":"","@id":"5b8dbb77-7340-4299-8111-22b3c958e55d","email":"ldy199008@163.com"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨经绥","en_name":"","@id":"b430b2d8-3ad2-413e-a19a-6c31e6b1cd4b","email":"yangjsui@163.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
