  ('7fbfd554096b43629c9732ccdac10fc3', 'cbfe66254c8f4281a976e91f81353f18', '雅鲁藏布江悬移质与推移质物源预算的对比：拉萨地块还是喜马拉雅？数据集', NULL, '同一河流的沉积物通常被认为反映共同的物源，尽管它们可能记录着显著不同甚至相反的沉积供给和侵蚀信号。这种差异可能会对我们解释地貌过程产生重大偏差。本研究聚焦于雅鲁藏布江——布拉马普特拉河在西藏境内的上游河段，对比分析了输移过程中的悬移质与河道砂坝的矿物学和地球化学信息，揭示了利用砂岩和泥岩组分的岩相学与同位素数据计算出的沉积物预算之间存在重大差异。
我们的结果表明，无论是在悬移质还是河道砂坝中，砂质组分都记录了来自拉萨地块的压倒性贡献，而泥质组分则主要反映喜马拉雅带的供给。在砂坝中，来自拉萨地块的碎屑物是喜马拉雅碎屑物的两倍；但在悬移质中，喜马拉雅的贡献是拉萨地块的1.4倍。总体而言，估算显示喜马拉雅沉积岩产生的沉积物量与拉萨花岗岩类和火山岩相当。如果在沉积物预算计算中只考虑砂（仅占总输沙量的一小部分），喜马拉雅的侵蚀速率和产沙量将被大大低估。在沉积物生成过程的研究中，必须同时充分考虑以砂为主的推移质和以泥为主的悬移质。我们的结果强调了在物源分析中仅依赖砂级沉积物的潜在陷阱，并迫使人们重新评估产沙量和侵蚀模式的评估方法。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','沉积学'], ARRAY['雅鲁藏布江','物源预算','悬移质','推移质'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"胡修棉","en_name":"","@id":"fbe0f7b6-cab7-4a4e-9a3c-06da1e90e59e","email":"huxm@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 1229554, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":1229554,"name":"pdf"}]'::jsonb, '胡修棉', 'huxm@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('9146be2bb1db47e8a9a24c20e14e493a', '3202530efc6245269fb5b504a9a58ed8', '中晚宾夕法尼亚世事件：时间与机制数据集', NULL, '晚古生代冰期（LPIA）伴随着气候波动、显著的生物变化等事件。这些变化发生在宾夕法尼亚世中晚期（约307–303.7 Ma）的海洋和陆地领域。由于连续的宾夕法尼亚系剖面稀缺，以及LPIA期间频繁的冰川-海平面升降导致的国际对比困难，这些事件（尤其是海洋事件）的时间、机制和规模尚不清楚。中国黔南地区的斜坡碳酸盐岩沉积序列中含有丰富的牙形石，为研究这些事件提供了机会。本文基于那庆、上龙和那绕剖面的材料，展示了中–上宾夕法尼亚统界线附近的牙形石生物地层学、牙形石磷灰石的锶和氧同位素以及全岩碳同位素数据。识别出的牙形石带包括：晚莫斯科期的Idiognathodus podolskensis带、Neognathodus roundyi带和Swadelina sp. A带；卡西莫夫期的Sw. subexcelsa带、Sw. makhlinae带、I. heckeli带、I. turbatus带、I. magnificus带、“I.” guizhouensis带、Heckelina eudoraensis带和“I.” naraoensis带；以及格热尔期的H. simulator带。聚焦于晚莫斯科期至早卡西莫夫期，在Sw. sp. A带和I. magnificus带期间识别出三期环境和生物变化。Sw. sp. A带至Sw. subexcelsa带期间的第一至第二期变化，对应于雨林生物群落的优势类群从科达类-石松类转变为合囊蕨类树木。Sw. subexcelsa带至I. magnificus带期间的第二至第三期变化，对应于德梅因期晚期灭绝事件和Idiognathodus物种的辐射。根据δ¹⁸O计算得出的约4–6°C的总体变暖趋势可以部分解释雨林的干旱化和崩溃。牙形石磷灰石的⁸⁷Sr/⁸⁶Sr和δ¹⁸O支持：大陆风化的变化部分驱动了卡西莫夫期中晚期牙形石的灭绝和随后的辐射。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','古生物学'], ARRAY['晚古生代冰期','中晚宾夕法尼亚世事件','牙形石','同位素','生物地层学','华南'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"胡科毅","en_name":"","@id":"9655eded-ea57-4c6c-b44f-32e05dc69f0b","email":"kyhu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 44405, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":44405,"name":"xlsx"}]'::jsonb, '胡科毅', 'kyhu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('d1c1dd8acb164819901b6c6382f18a38', 'a3fb43ce80944f7aa14d7ef8caee19b2', '密西西比亚纪牙形石的时空演化：案例研究数据集', NULL, '牙形石在石炭纪（地球历史上倒数第二个冰期——晚古生代冰期（LPIA）的关键时期）沉积地层中具有重要的生物地层学意义。石炭纪的牙形石属 Gnathodus 尤为重要，因为其广泛的地理和地层分布及其种/亚种已被广泛用于定义密西西比亚纪的牙形石带。由于化石记录的不完整以及 P1 单元形态的复杂性，Gnathodus 各物种/亚种之间的演化关系仍然不清楚，导致国际对比不精确。此外，Gnathodus 物种的古地理分布也需要进一步讨论，因为它可能为了解 LPIA 期间牙形石演化动态与环境因素之间的相互作用提供关键见解。本文通过对 34 个 Gnathodus 种/亚种和 2 个 Protognathodus 种进行系统发育分析，捕捉并分析了 P1 单元的 48 个形态特征。提出了一个新的 Gnathodus 系统发育模型，揭示了两条不同的演化路径：1) G. praebilineatus 相关分支，其特征为吻部平台上有复杂的节点；2) G. semiglaber 相关分支，其特征为具有吻部护墙。此外，使用统计扩散-替代分析（S-DIVA），Gnathodus 的祖先生物地理分布表明，该属的大多数物种形成事件可能发生在莱茵洋东部，暗示洋流刺激了新演化物种的快速扩散。基于该属的时空演化，还提出了一个基于 Gnathodus 的密西西比亚纪精细分带方案。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','古生物学'], ARRAY['石炭纪','Gnathodus','系统发育','古生物地理学','生物地层学'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"胡科毅","en_name":"","@id":"9655eded-ea57-4c6c-b44f-32e05dc69f0b","email":"kyhu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 1584697, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":1584697,"name":"pdf"}]'::jsonb, '胡科毅', 'kyhu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('87dd860a7c2d4deb9459803b8476f4d8', '4fa8f0b02cec4ed2a14ea7d151d55858', '古巴蛇绿岩混杂岩中的超高压到高压榴辉岩揭示原加勒比扩张脊俯冲数据集', NULL, '在南北美洲板块张裂过程中形成的原加勒比洋壳，随后俯冲到了加勒比板块之下。然而，原加勒比扩张脊俯冲的时间与空间配置仍存在争议。代表俯冲原加勒比洋壳残片的高压基性变质岩常见于古巴蛇绿岩混杂岩中。本研究对古巴中部拉斯维利亚斯混杂岩中的榴辉岩进行了岩石学、地球化学和年代学综合研究。榴辉岩具有典型的大洋中脊玄武岩（MORB）地球化学特征，表明其原岩形成于原加勒比扩张脊。基于相平衡模拟以及金红石中Zr含量和锆石中Ti含量温度计获得的压力-温度（P-T）估算，代表性样品的P-T演化路径如下：进变质路径从24–25 kbar、510–520°C上升到峰期条件29–31 kbar、525–575°C；复杂的退变质路径先经历近等温折返至25–27 kbar，随后近等压加热至610–640°C，最后完全折返。这是北加勒比地区首次记录的洋壳进变质超高压（UHP）变质作用。具有陡峭重稀土（HREE）模式和负Eu异常的岩浆锆石U-Pb定年给出原岩年龄为126.3 ± 0.7 Ma。而具有平坦HREE模式和无Eu异常的变质锆石给出的加权平均年龄为118.6 ± 1.6 Ma。MORB岩浆作用与超高压变质作用之间的时间间隔小于8 m.y.，表明洋壳在扩张脊附近形成后不久即俯冲到约100 km深度，这为原加勒比扩张脊的俯冲提供了有力证据。此外，本研究展示了通过对洋壳榴辉岩进行岩石学、地球化学和年代学联合研究来示踪古代扩张脊俯冲的巨大潜力', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['超高压变质作用','榴辉岩','原加勒比扩张脊'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨经绥","en_name":"","@id":"b430b2d8-3ad2-413e-a19a-6c31e6b1cd4b","email":"yangjsui@163.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 216711, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":216711,"name":"zip"}]'::jsonb, '杨经绥', 'yangjsui@163.com', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('46dc4f9190f247439b1788886aa3103e', 'c944ed9ae9c34c35b2da8d310c9a9685', '利用岩墙群的古地磁方向重新评估元古宙的地心轴向偶极子（GAD）模型数据集', NULL, '元古宙地磁场结构存在争议，这阻碍了我们对古代板块古地理和地核演化的理解。本研究采用改进的统计方法和扩大的基性岩墙群古地磁方向数据集（覆盖了比以前更大的区域），重新评估了元古宙的地心轴向偶极子（GAD）模型。除了常用的Fisher统计外，我们还使用Bingham和Kent统计来评估虚地磁极（VGP）分布的紧密度和伸长率。我们的结果表明，元古宙地磁场主要是GAD，但在某些时间间隔内存在约10–15%的潜在轴向八极子（G₃）分量。我们的发现不支持先前关于元古宙存在显著更大（25–29%）非偶极子贡献的主张。识别出的元古宙非偶极子分量可能导致古纬度出现约10°的变浅，这不足以解释低纬度冰川作用，但可能解释元古宙古气候记录中一些偏移的古地磁纬度。我们的研究还表明，利用古地磁学上独立的古地理重建来扩展VGP的空间分布，可以提高检验的灵敏度，并对地磁场结构提供更严格的约束。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','前寒武纪地质学'], ARRAY['地磁场结构','GAD假说','非偶极子场','元古宙','球面统计'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"龚政","en_name":"","@id":"810233f3-95e4-489d-b9c0-84cbe558d759","email":"njugongzheng@gmail.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 36680524, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":36680524,"name":"docx"}]'::jsonb, '龚政', 'njugongzheng@gmail.com', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('e800b9fe63374370b4bc4aaf861778b7', 'ef1daf2b07034780a130f74462853d66', '利用磁显微技术对实验室地震中局部滑动诱发摩擦加热的成像数据集', NULL, '滑动引起的加热对于理解地震过程中的断层力学和能量分配至关重要。最强的加热发生在毫米到亚毫米尺度的薄层内，这对现有的地质温度计构成了挑战，因为它们缺乏空间分辨率或仅限于特定的岩石成分。在这里，我们利用最近开发的量子金刚石显微镜（QDM），以微米级分辨率测量实验产生的滑动带周围的热退磁，从而量化近场滑动引起的温度升高。这项新技术还使我们能够观察到沿断层加热强度存在约300微米尺度的非均质性，突显了局部应力和变形在指导摩擦演化中的作用。一个简单的一维热扩散模型可以同时满足QDM的温度估算、远场热电偶测量以及局部熔融的显微结构观测。该模型约束了实验室地震中滑动期间的热能量密度为52–65 kJ/m²，占总能量预算的52%–75%。我们还估算出快速滑动期间的平均摩擦系数为0.2–0.3，表明滑动过程中存在显著的弱化。我们的结果为理解类地震破裂过程中局部加热的作用提供了新的见解，并阐明了在对应于孕震层底部的压力条件下热弱化机制的作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','构造地质学（包括显微构造学等）'], ARRAY['滑动加热','摩擦','量子金刚石显微镜','断层弱化','实验室地震'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"龚政","en_name":"","@id":"810233f3-95e4-489d-b9c0-84cbe558d759","email":"njugongzheng@gmail.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 7783984, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":7783984,"name":"docx"}]'::jsonb, '龚政', 'njugongzheng@gmail.com', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('620725e5e9e54b4989753a149549b607', '129a9e782e554e25bd8da5d59e7f5542', '提高中始新世–晚渐新世有孔虫生物-磁性地层年代学的时间分辨率：来自CONOP的见解及生物事件的年代学意义数据集', NULL, '为了理解地球历史，一个整合了可用地层信息的综合时间标尺至关重要。中始新世到晚渐新世提供了丰富的地层信息，包括有孔虫和磁性地层数据。然而，传统生物地层学仅使用一小部分（1–10%）有孔虫作为标记，降低了时间标尺的时间分辨率，并且缺乏定量评估标记和非标记生物事件年代学意义的方法。本研究采用定量地层学方法——约束优化（CONOP），利用11个参考剖面为中始新世–晚渐新世创建了一个高分辨率的磁性地层-有孔虫时间标尺。新的复合序列比传统方法的时间分辨率提高了近十倍，纳入了409个额外的生物事件，同时与已建立的标志层紧密吻合。研究开发了两个评估因子——穿时性和中心性，用以评估事件在不同地点和地理范围之间的时间一致性。结果显示：小底栖有孔虫、浮游有孔虫和有孔虫带化石事件的年代学意义依次增强。相反，大底栖有孔虫事件受地方特有性影响，使其评估复杂化。将磁性地层数据纳入CONOP增强了地层对比的稳健性和准确性。我们的方法提供了一种应用CONOP构建高分辨率时间标尺的途径，使得能够超越带化石的局限，对生物事件进行全面评估。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','地层学与地史学','古生物学'], ARRAY['磁性地层学','生物地层学','CONOP','时间标尺','年龄模型'], '[{"Organization":{"@type":"Organization","name":"南京大学","en_name":"Nanjing University","@id":"4dcddfe8b797476f9e75e381379d3849"},"@type":"Person","name":"樊隽轩","en_name":"","@id":"f454a4d5-5c8a-4b5e-ab37-772fea4e81ec","email":"jxfan@nju.edu.cn"}]'::jsonb, '南京大学', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 21119508, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":21119508,"name":"zip"}]'::jsonb, '樊隽轩', 'jxfan@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('a75ff5c302f648af86f4cf889a0d904c', '9767b5eca4354e52b70119813480c0bb', '通过陆架沉积物移除闭合海洋锂收支数据集', NULL, '海水锂同位素（δ7LiSW）越来越多地被用作地球历史中大陆硅酸盐风化和海洋反向风化的代用指标。然而，驱动δ7LiSW演化的机制仍然不确定，部分原因在于对现代锂源和汇的约束不足。其中，沉积物成岩作用长期以来被认为是一个重要的锂汇，但对全球自生锂汇的直接和定量评估仍然有限。本文通过孔隙水数据探讨了孔隙水中锂分布的控制因素，并直接定量了陆架沉积物中锂的移除和同位素分馏。我们发现，与陆架沉积物中海洋自生黏土（MAAC）形成相关的锂移除不受硅酸（Si(OH)4）的限制，因为陆源活性铝硅酸盐和生物硅的溶解提供了充足的硅酸供应。研究表明，灌溉作用增强的溶质传输，加上锂向陆架沉积物中自生黏土的活跃移除，产生了21±8 G mol/年的通量，表明与陆架沉积物中MAAC形成相关的锂移除是海水锂的主要汇。我们进一步限定了与这种灌溉增强的陆架沉积物汇相关的同位素分馏（ΔSW−MAAC = δ7LiSW - δ7LiMAAC）为14.7–16.5‰。我们的结果强调了进入陆架沉积物的自生锂移除，加上来自海底玄武岩蚀变的较小贡献，可以紧密地平衡海洋锂源，这对于理解古海洋中的自生黏土形成和锂循环具有深远意义', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','海洋科学','海洋地质学'], ARRAY['锂通量','海洋自生黏土形成','陆架沉积物','锂同位素','孔隙水','东海'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"陈天宇","en_name":"","@id":"e125edfa-6c4e-45ca-817c-714fc2672a10","email":"tianyuchen@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 2215418, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":2215418,"name":"zip"}]'::jsonb, '陈天宇', 'tianyuchen@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('b69c178c9a5449dbab0d04e2d6fbdb7b', 'b7edd960cf4a4406a03eccbc5d44c3a9', '板内火山活动记录的滞留板片回返数据集', NULL, '俯冲板块常常滞留在地幔转换带（MTZ）中，而滞留板片的最终归宿仍然存在争议。它们可能沉入下地幔，或者部分被困在MTZ中，但能否回返到上地幔仍不确定。我们报道了来自双鸭山（位于东亚滞留太平洋板块撕裂上方的区域）晚中新世（~6 Ma）玄武岩的地球化学证据以及该区域上地幔的地震学证据，展示了板片如何从MTZ回返到上地幔。双鸭山玄武岩具有异常高的δ57Fe、Gd/Yb值和异常低的δ26Mg、Ti/Eu、CaO/Al2O3值，表明俯冲的太平洋洋壳物质被裹挟进入了它们上地幔的源区。因此，洋壳从MTZ向上地幔的回返似乎是由该区域正下方滞留板片撕裂所触发的上涌流驱动的。与此同时，局部的剪切波分裂测量揭示了上地幔各向异性的环形模式，其延迟时间向板片撕裂处减小，表明携带板片碎片的上升流随后在上地幔中转变为侧向流，并促成了滞留板片上方更广泛的板内岩浆作用。这一发现，连同东亚地区其他广泛分布的、延伸约6000公里的板内火山活动，表明俯冲作用诱发的撕裂可导致滞留板片物质的破坏和部分回返，进而导致俯冲地壳物质的再循环以及俯冲诱发的板内岩浆作用的产生。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','同位素地球化学'], ARRAY['滞留板片','板片回返','板片撕裂','板内火山作用','地球化学'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"黄周传","en_name":"","@id":"9c009154-12c5-4dc9-93fe-709d6df4947d","email":"huangz@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 1702302, 9, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":8},{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":433392,"name":"xlsx"},{"storageNum":1268910,"name":"pdf"}]'::jsonb, '黄周传', 'huangz@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('fd9cb466eae24238b43eacbad63c6fa1', '4bf7ed95c3da4f9094c650b06d6c5ab3', '火山驱动的Hg–C–S循环与早二叠世Artinskian变暖期的气候变化数据集', NULL, '晚古生代冰期的气候变化及其驱动机制——作为当今全球变化的理想类比——仍然存在争议。本文通过研究泛大陆北部准噶尔盆地早二叠世芦草沟组（跨越Artinskian变暖事件），提出了火山碳-硫辐射强迫机制。碳同位素地层学和古气候代用指标记录了早二叠世的碳循环波动以及在Artinskian一级变暖背景下的二级冷却事件。汞浓度、汞/总有机碳比值的峰值，以及δ¹³Corg和δ³⁴Sbulk的负偏移，与塔里木大火成岩省的喷发时间高度一致，表明塔里木火山活动驱动了汞-碳-硫循环和气候变化。具体而言，硫循环通过提高大气硫酸盐气溶胶水平引发短期冷却，而碳循环通过升高大气二氧化碳浓度则促进了长期变暖。在全球范围内，火山作用可能调节了跨地质时代的碳-硫循环以及冰期-间冰期的交替，其中硫酸盐辐射强迫是一个长期被忽视但对气候演化至关重要的机制。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','有机地球化学'], ARRAY['晚古生代冰期','Artinskian变暖','汞循环','碳-硫循环'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"曹剑","en_name":"","@id":"4a65761d-c3b6-44f1-801b-cb244b463768","email":"jcao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 39405, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":39405,"name":"xlsx"}]'::jsonb, '曹剑', 'jcao@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('c3a4e3d7eebd485c89d0d9273f7186ed', '309b3cfc709c4f62b1c0ad39bb0e19d2', '解析托阿尔期大洋缺氧事件期间的汞循环与火山作用数据集', NULL, '费拉尔大火成岩省的侵位被认为是早侏罗世托阿尔期大洋缺氧事件（T-OAE）的根本驱动因素。汞（Hg）同位素体系以及其他证据被用来支持这一假设，但关于火山输入与陆地汞输入的相对作用仍存在争议。本文研究了两个岩心中的汞记录，这两个岩心记录了跨越中国四川湖相盆地的一个水深梯度剖面。两个岩心的特征均显示在托阿尔期大洋缺氧事件期间存在汞的富集。然而，观测到的汞浓度与水柱硫化物可利用性的地球化学指标之间的负相关关系表明，通过氧化还原作用导致的沉积物汞损失对原始的汞富集进行了改造。此外，汞同位素体系在浅水和深水岩心之间显示出不同的信号，分别指示了来自陆源和大气源的输入增加。这些结果表明，区域因素对沉积物中的汞富集起着主要的控制作用，在利用汞体系评估火山活动时必须考虑这一点。尽管如此，我们的方法强调了湖相系统确实记录了托阿尔期大洋缺氧事件期间大气汞沉降的重要作用，证实了费拉尔大火成岩省的大规模活动是这次重大环境扰动的一个关键驱动因素。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','沉积学'], ARRAY['托阿尔期大洋缺氧事件','汞','大火成岩省','氧化还原条件','四川盆地'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"曹剑","en_name":"","@id":"4a65761d-c3b6-44f1-801b-cb244b463768","email":"jcao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 3387254, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":3387254,"name":"zip"}]'::jsonb, '曹剑', 'jcao@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('1f76770ef2a84df687f7a3bc9e5f0307', '5969631690634e6189d177b3286cfd1c', '托阿尔期温室变暖导致气候带向极地移动及其对全球变化的启示数据集', NULL, '据预测，大气对流将因人为全球变暖而发生改变，导致哈得利环流及相关干旱气候带向极地扩张。然而，对于气候带位置可能发生的纬度变化幅度，目前了解甚少。本文基于早托阿尔期（早侏罗世晚期）大洋缺氧事件（T-OAE，~183 Ma）的案例研究来解决这一问题。该事件是显生宙最重要的全球变化事件之一，其特征是湿度升高和陆地生态系统受到重大干扰。我们展示了来自高古纬度准噶尔盆地（中国西北部）跨越T-OAE事件的新的叶蜡正构烷烃δ¹³C数据，并建立了一个在该时间间隔内从低古纬度到高古纬度的植物分馏变化的时空框架。我们表明，在T-OAE期间，湿度发生了显著的纬度变化（约10°），这很可能是因为低纬度干旱带显著向北扩张到了中古纬度地区，并由此推断哈得利环流发生了纬度扩张。这一发现对理解人为全球变暖及其对气候带的影响具有重要意义。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','有机地球化学'], ARRAY['托阿尔期大洋缺氧事件','温室变暖','哈得利环流','气候带','叶蜡正构'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"曹剑","en_name":"","@id":"4a65761d-c3b6-44f1-801b-cb244b463768","email":"jcao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 93478, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":93478,"name":"zip"}]'::jsonb, '曹剑', 'jcao@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('7b84601a2dda48188271e8f06223de37', '9a5156ddfad04a78b5bbc79a22dfd23d', '早二叠世Artinskian变暖期间古湖泊与气候变化的关联数据集', NULL, '古湖泊与过去气候变化之间的联系是一个重要但认识不足的地质问题，具有广泛的科学意义。本文以晚古生代冰期（LPIA）期间的早二叠世Artinskian变暖事件（约290 Ma）为研究对象，利用泛大陆北部中纬度地区一个大型古湖泊系统——古准噶尔湖（显生宙已知最大湖泊之一）中富含有机质的细粒岩石的综合记录，开展了一项探索性研究。该湖泊的早二叠世芦草沟组记录了这一时期的气候环境信息。
研究结果显示，芦草沟组中大陆化学风化作用的增强（表现为升高的化学蚀变指数CIA值）和碳同位素负偏移（CIEs）揭示了Artinskian变暖事件期间气候确实发生了变暖。与气候变暖相关的古环境参数，如Cu/Ti比值、Sr/Ba比值、磷（P）含量和总有机碳（TOC）含量，表现出同步的变化，这表明Artinskian变暖期间气候变暖加剧了水文循环，导致河流营养输入增加和水体初级生产力提高。这些过程与湖泊中稳定的盐度分层相结合，促进了有机碳的富集（TOC约5.0%）。来自自生白云石中富集¹³C（δ¹³C = 3.2–12.3‰，平均6.1‰）的信号进一步揭示了湖泊中发生了强烈的微生物甲烷循环。
此外，异常高的沉积物汞浓度与碳同位素负偏移、高CIA值和高TOC含量之间的协同变化表明，火山活动很可能是驱动气候变暖和水文循环的关键初始因素，同时也促进了湖泊中有机碳的埋藏和甲烷的释放。据估算，在约3百万年的时间里，古准噶尔湖从大气-海洋系统中吸收并封存了约290 Gt的有机碳。有机碳埋藏速率估计约为1 × 10¹¹ gC/年，约占同期全球有机碳埋藏速率的0.1–0.2%，并在Artinskian变暖期间生成了约540 Gt的甲烷。
我们的新见解强调了在关键地质转折期陆地碳循环的重要性。这些湖泊中的碳封存可能对外源碳循环产生负反馈，从而产生全球性影响，而甲烷的释放则作为碳源加剧了全球变暖。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','有机地球化学'], ARRAY['碳循环','Artinskian变暖事件','有机质富集','芦草沟组'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"曹剑","en_name":"","@id":"4a65761d-c3b6-44f1-801b-cb244b463768","email":"jcao@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 4040316, 2, NULL, 2, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"xlsx","count":1},{"name":"docx","count":1}]'::jsonb, '[{"storageNum":56151,"name":"xlsx"},{"storageNum":3984165,"name":"docx"}]'::jsonb, '曹剑', 'jcao@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('6f73b4ae6bef46d7b1688d50dad7b70b', 'dd8568e702e748df918670835643dbee', '淮河流域大气陆面水文再分析资料', 'Huaihe River Basin Atmospheric-Land Surface Hydrological Reanalysis Data', '淮河流域大气陆面水文再分析资料是基于大气-陆面-水文全耦合模式研制的高分辨率再分析数据集，考虑了人类取用水和水库调蓄等人类活动过程，包含的物理机制相比ERA5等现有再分析资料更为完善，提供的要素覆盖大气、陆面、水文多圈层完整水循环要素（降水、蒸散发、径流、地下水等）。
与ERA5等现有再分析产品相比，本数据集空间分辨率显著提高（大气3公里/陆面水文500米），在气温、降水等关键气象与水文变量的表征精度上均有提升，与实测值更为接近。春、夏、秋、冬降水的均方根误差分别减少0.1、0.42、0.09、0.08 mm/day；年平均气温偏差和均方根误差分别减少0.149℃和0.323℃；土壤湿度和蒸散发模拟偏差分别减少11%和47%。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['气候学'], ARRAY['再分析资料','资料同化'], '[{"Organization":{"@type":"Organization","name":"南京信息工程大学","en_name":"Nanjing University of Information Science and Technology","@id":"19802bcf0d0046dfa69e5c2d405a68a4"},"@type":"Person","name":"姚遥","en_name":"","@id":"24a4fc9c-0003-4990-bea4-59cc3526fcc0","email":"yyao@nuist.edu.cn"}]'::jsonb, '南京信息工程大学', NULL, NULL, NULL, 'CC BY 4.0', 'open', NULL, 1110252288, 6, NULL, 6, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"nc","count":6}]'::jsonb, '[{"storageNum":1110252288,"name":"nc"}]'::jsonb, '姚遥', 'yyao@nuist.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('1628fd2770cb4f0e9ce239eb27762ab9', '6a165c5bdec94588bdd49a6bebdde208', '塞迈尔蛇绿岩Maqsad地区壳-幔过渡带中形成于新生弧前环境之上的过渡型铬铁岩数据集', NULL, '塞迈尔蛇绿岩是保存完好的蛇绿岩经典实例，拥有超过450个已记录的豆荚状铬铁矿床。本研究调查了塞迈尔蛇绿岩苏马尔山体Maqsad地区壳-幔过渡带中的一种过渡型铬铁岩产出。这些被纯橄岩包裹的铬铁岩呈现出块状和浸染状构造。作为上地幔残留体的寄主方辉橄榄岩经历了约20–35%的部分熔融，随后受到俯冲板片派生熔体/流体的交代作用。这些橄榄岩的地球化学特征与伊豆-小笠原-马里亚纳弧前橄榄岩相似，指示了一个弧前构造背景。Maqsad铬铁岩的铬铁矿Cr#值为54.3–66.2，被归类为过渡型铬铁岩。其地球化学特征类似于从洋中脊玄武质熔体中结晶的铬铁矿。相对于深海橄榄岩升高的氧逸度值进一步支持它们形成于俯冲带上覆环境。基于寄主岩的岩石地质和地球化学特征，我们提出Maqsad过渡型铬铁岩的母岩浆来源于俯冲带上覆环境中的新生弧前地幔，具有类似洋中脊玄武岩的亲和性。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','岩石学'], ARRAY['塞迈尔蛇绿岩','Maqsad底辟','壳-幔过渡带','过渡型铬铁岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"连东洋","en_name":"","@id":"5b8dbb77-7340-4299-8111-22b3c958e55d","email":"ldy199008@163.com"},{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"杨经绥","en_name":"","@id":"b430b2d8-3ad2-413e-a19a-6c31e6b1cd4b","email":"yangjsui@163.com"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 4219565, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":4219565,"name":"zip"}]'::jsonb, '连东洋', 'ldy199008@163.com', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('7d2a8d94b5014ea3b31904dc56b92f24', '7a209bcbd251450f877ae6d53070641a', '正长石（001）表面的界面结构与酸性：表面金属阳离子效应的理解数据集', NULL, '表面酸化学是正长石界面性质的核心问题。本研究采用第一性原理分子动力学方法，研究了表面存在Na⁺/K⁺阳离子时正长石（001）面的界面结构和酸常数（pKa）。详细的结构分析表明，Na⁺和K⁺在表面上具有相似的配位结构，而Na⁺与K⁺的交换几乎不改变表面基团的水合结构。表面基团（即≡SiOH、≡AlOH和≡AlOH₂）在K⁺存在下的pKa值分别为11.5、18.5和7.8；在Na⁺存在下的pKa值分别为5.5、17.7和4.3。基于第一性原理分子动力学推导的pKa值表明，当表面存在K⁺时，≡AlOH₂是常见pH范围内唯一的活性基团；而Na⁺会降低表面基团的pKa值，使得≡AlOH₂和≡SiOH均具有活性。根据这些pKa值，我们计算出表面含K⁺和Na⁺的正长石（001）面的零电荷点分别为9.7和4.9。这意味着Na⁺显著增强了表面的酸反应活性。本文还讨论了这一发现对理解正长石地球化学性质的意义，重点聚焦于金属阳离子的表面络合作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿物学（包括放射性矿物学）'], ARRAY['第一性原理分子动力学','正长石-水界面','微观结构','酸常数','吸附'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"刘显东","en_name":"","@id":"3b97e59a-36ff-409e-ac4a-0161502b95f8","email":"xiandongliu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 1144611, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":1144611,"name":"pdf"}]'::jsonb, '刘显东', 'xiandongliu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('4b8fa908991a47d4b644b736a1cec833', 'aaf3eaff74934a6fa68f4914292a7ebf', '2:1型顺式空位Cs饱和蒙脱石溶胀、结构和动力学性质的分子动力学研究数据集', NULL, '蒙脱石是一族层状硅酸盐矿物，基于层间水和离子的活动性表现出分立的含水/溶胀状态以及较高的阳离子交换容量，使其成为工程和环境领域的关键材料。天然蒙脱石中同时存在顺式空位和反式空位结构。先前的分子尺度研究大多假设为反式空位构型，这可能导致对蒙脱石热力学和微观性质的预测出现偏差。本研究以三种代表性的顺式空位蒙脱石（即怀俄明型、Ari型和贝得石）为模型框架，以Cs为层间阳离子，采用经典分子动力学模拟探索蒙脱石的热力学和微观性质。研究考察了不同层间水含量下蒙脱石的溶胀行为、Cs的结合结构、层间水和Cs物种的分布与迁移率，以及Cs/Na饱和蒙脱石之间的阳离子交换。结果表明，单层水合物是Cs饱和蒙脱石最稳定的水合状态。与相应的体相水相比，层间水的扩散相对较慢，而在低含水量条件下Cs阳离子可以被有效地固定。此外，Cs阳离子在平行于蒙脱石基面方向上的迁移率高于垂直方向。Cs阳离子在层间形成稳定的内层络合结构，主要结合于六元环位点和三角形位点。计算得到的Cs/Na离子间的阳离子选择性系数相当高（Log Kc = 1.69），表明Cs阳离子被有效滞留，这与已有实验报道相符。此外，将顺式空位蒙脱石获得的所有结果进一步与反式空位蒙脱石的结果进行了比较。比较结果表明，两种蒙脱石具有高度相似的热力学和微观性质。本研究为促进蒙脱石在地球化学和环境材料科学中的基础研究提供了更深入的理解', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿物学（包括放射性矿物学）'], ARRAY['Cs饱和蒙脱石','顺式空位','层间阳离子','溶胀','水合作用','分子动'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"刘显东","en_name":"","@id":"3b97e59a-36ff-409e-ac4a-0161502b95f8","email":"xiandongliu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 3367538, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":3367538,"name":"docx"}]'::jsonb, '刘显东', 'xiandongliu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('84be3a9d7e4c4c24a524aa0ee6f5c998', '5294d105fa334b6e8aababa218589a3c', '页岩气在干酪根基质中的吸附与扩散：分子模拟的启示数据集', '', '页岩气采收率低，这凸显了理解其与干酪根基质相互作用以及在其中的扩散行为的必要性。本研究利用分子模拟技术，系统研究了页岩气在干酪根基质中的吸附与扩散。构建了五种干酪根模型（即 I-A、II-A、II-B、II-C 和 II-D）。发现 I-A 型和 II-D 型干酪根分别表现出最低和最高的密度，且干酪根的孔隙度随热成熟度增加而单调增加。此外，发现甲烷吸附能力与孔隙度之间存在线性相关性。甲烷在 I-A 型干酪根中的扩散率显著高于 II 型干酪根，这归因于 I-A 干酪根的柔性。此外，还表征了甲烷扩散过程中的同位素分馏，发现负的同位素分馏可由 ¹³CH₄ 略高的扩散活化能来解释。本研究的发现为干酪根中甲烷的吸附与扩散提供了分子层面的认识，并有助于理解生产现场中甲烷-干酪根的相互作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地球化学','有机地球化学'], ARRAY['干酪根','吸附','扩散','甲烷','同位素分馏','分子模拟'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"刘显东","en_name":"","@id":"3b97e59a-36ff-409e-ac4a-0161502b95f8","email":"xiandongliu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 3748923, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":3748923,"name":"docx"}]'::jsonb, '刘显东', 'xiandongliu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('de5c2d16f0c84dc9825baa78800a769e', '5833f8bd63fd4c4aaa2a3059fb615ff8', '超临界NaAlSi₃O₈-H₂O流体的结构与输运性质：来自ReaxFF分子动力学模拟的启示数据集', NULL, '超临界流体作为含水流体和硅酸盐熔体的中间组分，具有类似流体的粘度和类似熔体的元素携带能力，是从俯冲板片向地幔楔进行物质迁移的理想介质。然而，超临界流体的结构和输运性质尚未得到充分理解。本研究利用ReaxFF反应力场分子动力学模拟技术，在1000–3000 K和约2 GPa条件下，研究了超临界NaAlSi₃O₈-H₂O体系的结构和输运性质。探讨了水含量和温度对超临界流体中物种形成、结构、扩散率和粘度的影响。
硅主要以四配位形式存在，而铝的配位数在3到6之间变化。随着水含量的增加，Q⁴和Q⁵物种减少，Q⁰物种持续增加，同时优势物种逐渐从Q⁴转变为Q³，随后转变为Q²、Q¹、Q⁰。元素扩散率和粘度均被建模为水含量和温度的函数。这些模型可用于预测含水硅酸盐熔体/流体的输运性质。总体而言，本研究的发现为典型超临界流体提供了分子层面的理解。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','动力地质学'], ARRAY['超临界流体','ReaxFF','分子动力学','结构','物种形成','扩散'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"刘显东","en_name":"","@id":"3b97e59a-36ff-409e-ac4a-0161502b95f8","email":"xiandongliu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 5729163, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":5729163,"name":"docx"}]'::jsonb, '刘显东', 'xiandongliu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('7dd2f8dad0c64138b42e110350c97d50', '7be5929c63624e5ab9fef47c306d5d99', '热液溶液中铀酰的形态：分子动力学模拟的启示数据集', NULL, '本研究采用经典分子动力学和第一性原理分子动力学方法，研究了热液溶液中铀酰的形态。我们利用经典分子动力学模拟计算了铀酰氯/氟配合物的逐级缔合常数，并利用第一性原理分子动力学模拟计算了铀酰的第三级水解常数。基于本研究及前人获得的热力学数据，我们确定了在含有 Cl⁻、F⁻、CO₃²⁻、SO₄²⁻ 和 OH⁻ 的热液溶液中铀酰的形态分布。结果表明，在常温条件下，酸性至中性溶液中铀酰形态受 F⁻ 浓度控制，而碳酸根和氢氧根配合物则是碱性溶液中的主要形态。随着温度升高，在高 pH 条件下铀酰氢氧根配合物成为优势种，而在低 pH 条件下，铀酰硫酸根配合物和铀酰氟配合物可能变得重要。本研究扩展了热液溶液中铀酰的热力学数据库，为理解自然界中铀的迁移和富集提供了定量基础。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','动力地质学'], ARRAY['铀','热液溶液','形态','缔合常数','水解','分子动力学'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"刘显东","en_name":"","@id":"3b97e59a-36ff-409e-ac4a-0161502b95f8","email":"xiandongliu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 983162, 2, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"zip","count":1},{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":153405,"name":"zip"},{"storageNum":829757,"name":"pdf"}]'::jsonb, '刘显东', 'xiandongliu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('b56e9ee8a4a246c0aa910ded9dad91e2', '8260d00d83d34d0abd4f7b7fc4614952', '蒙脱石脱羟基反应机理的认识：基于反应力场分子动力学模拟的启示数据集', NULL, '蒙脱石是地球关键带中污染物的主要屏障材料，是一种具有顺式空位和反式空位构型的层状铝硅酸盐矿物。蒙脱石的高温转变与其热反应直接相关。然而，顺式空位和反式空位蒙脱石的确切热反应机理和热致结构转变仍存在争议。本研究利用反应力场分子动力学系统研究了顺式空位和反式空位蒙脱石模型的热反应机理。我们探讨了在700 K和900 K下顺式空位和反式空位蒙脱石的脱质子化和层内脱水步骤。结果表明，在700 K时，顺式空位蒙脱石的脱羟基反应比反式空位蒙脱石更困难，而在900 K时则相对更容易。此外，研究发现脱羟基后的顺式空位和反式空位蒙脱石自发演化成一致的结构。我们的结果进一步证实了顺式空位蒙脱石具有比反式空位蒙脱石更高的脱羟基温度，从而为使用热重分析区分顺式空位和反式空位蒙脱石提供了理论依据。此外，我们收集了来自不同地区蒙脱石的热重分析数据，证实了蒙脱石具有顺式空位结构，并且中国（超过11个省）几乎所有的蒙脱石都是顺式空位的。本研究为蒙脱石的热反应机理提供了分子层面的理解，并为蒙脱石的进一步研究和应用提供了物理基础。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿物学（包括放射性矿物学）'], ARRAY['反应力场分子动力学','元动力学','蒙脱石','顺式空位','反式空位','热'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"刘显东","en_name":"","@id":"3b97e59a-36ff-409e-ac4a-0161502b95f8","email":"xiandongliu@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 4655671, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":4655671,"name":"pdf"}]'::jsonb, '刘显东', 'xiandongliu@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('bde7afad8d1e45e8acb774ab72502732', '0c35791eb84e47278dd58ad038a554e1', '钨在针铁矿上的吸附：来自第一性原理分子动力学模拟的启示数据集', NULL, '由于钨的日益广泛使用及其潜在的健康危害，其环境归趋受到了特别关注。矿物吸附被认为是控制钨迁移性和生物有效性的主要因素。针铁矿作为土壤和沉积物中一种高度稳定的铁氧化物，在决定钨的环境行为方面起着关键作用。本研究通过系统的第一性原理分子动力学模拟，研究了钨在针铁矿主要（110）面上的吸附机制。首先，我们计算了钨在所有质子化状态（即 WO₄²⁻、HWO₄⁻ 和 H₂WO₄⁰）下在针铁矿表面形成的双齿角共享络合结构。在 WO₄²⁻ 和 HWO₄⁻ 体系中，钨呈现五配位，而在 H₂WO₄⁰ 体系中则转变为六配位。通过使用垂直能隙法计算 pKa 值，发现吸附态物种 WO₄(H₂O)²⁻ 在 pH > 2.0 时占主导地位，这与水溶液中 WO₄²⁻（pH > 4.9）不同。对 WO₄(H₂O)²⁻ 物种的解吸自由能计算表明，其双齿角共享形式非常稳定，结合能为 19.8 kcal/mol。本研究填补了关于自然环境中钨的行为与稳定性在原子尺度认识上的关键空白，为管理自然和工业环境中钨的迁移提供了理论基础。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿物学（包括放射性矿物学）'], ARRAY['钨','针铁矿','吸附','第一性原理分子动力学','表面络合','pKa'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"陆现彩","en_name":"","@id":"1d0b9749-bb84-4f59-b83c-02c1f37808ca","email":"xcljun@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 2372596, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":2372596,"name":"pdf"}]'::jsonb, '陆现彩', 'xcljun@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('ff130345a36d47869cb7a5e572e5b294', 'ea04b7f546444663b5b0576d694b0d5f', '华北串岭沟组古元古代晚期鲕状铁岩中的黏土-赤铁矿共生组合数据集', NULL, '元古宙铁建造的原始相被认为是古海水地球化学的重要档案。人们普遍认为水合铁氧化物/氢氧化物是主要的原始前驱相之一。然而，前寒武纪海水中高硅浓度的意义在理解原始铁矿物学方面正受到越来越多的关注。近期研究提供了令人信服的证据，表明Fe(II)-硅酸盐（特别是绿泥石）是铁建造的主要前驱相。但是，铁建造中铁硅酸盐转化为当前广泛存在的铁氧化物的可行性仍然不确定。本研究中，我们在河北张家口古元古代串岭沟铁建造中识别出了由含铁伊利石包壳和赤铁矿包壳构成的鲕粒交互层。含铁伊利石的Fe(II)/Fe总比例约为20%，显示出切向排列的晶体，这可能是还原环境中波浪作用的结果。在含铁伊利石包壳中存在相当数量的赤铁矿，可分为条纹状和球状两种类型。条纹状赤铁矿与含铁伊利石一起呈切向排列，其稀土元素模式显示重稀土富集，与赤铁矿包壳相似。相比之下，与球状赤铁矿伴生的含铁伊利石则显示轻稀土富集。我们提出：含铁伊利石包壳反映了在碱性条件下古海水中原始Fe-蒙脱石的沉淀，而条纹状赤铁矿代表了Fe-蒙脱石包壳形成过程中的原始矿物相。但在成岩过程中，由于伊利石化作用，从原始Fe-蒙脱石中释放出的铁促进了含铁伊利石包壳内部球状赤铁矿的形成。此外，在赤铁矿包壳的松散赤铁矿纹层中观察到微米级伊利石状硅酸盐颗粒的富集。我们认为，底层水的Eh、pH以及热液硅通量的变化调控了赤铁矿包壳鲕粒与Fe-蒙脱石包壳鲕粒的交替沉淀，以及这些包壳内不同纹层的互层。这些发现为铁建造沉积过程中Fe-蒙脱石的原始沉淀及其在成岩过程中的转化提供了矿物学和地球化学证据。这增进了我们对高铁高硅特征的前寒武纪海水条件下矿物沉积的认识。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿物学（包括放射性矿物学）'], ARRAY['古元古代','鲕状铁岩','鲕粒','含铁伊利石包壳','Fe-蒙脱石','成岩'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"陆现彩","en_name":"","@id":"1d0b9749-bb84-4f59-b83c-02c1f37808ca","email":"xcljun@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
', 20054679, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":20054679,"name":"docx"}]'::jsonb, '陆现彩', 'xcljun@nju.edu.cn', NULL, NULL, NULL, '2026-05-15', '2026-05-15'),
  ('44e54f02904b4f21ba16133af962c775', 'dadf52a2dabe43d7af2ff26c055526bd', 'As(III)和Mn(II)氧化诱导的锰氧化物结构转变数据集', NULL, '锰氧化物在自然系统中普遍存在，作为高反应性纳米颗粒在控制微量元素和污染物归趋中起关键作用。本研究探讨了As(III)与δ-MnO₂在不同pH条件下的反应，以及Mn(II)存在时的协同与竞争效应。结果表明，As(III)被完全氧化为As(V)，吸附量随pH降低而增加，As(V)以双齿双核表面络合物形式存在。As(III)和Mn(II)单独反应均降低锰的平均氧化态，共存时效应叠加。固相中生成Mn(II)和Mn(III)，高pH下Mn(III)比例更高。在pH 4时，Mn(II)诱导δ-MnO₂部分转化为恩苏塔矿，但As(III)抑制此转化；pH 7时，Mn(II)增加层堆积，As(III)效应较弱，共存时变化微弱；pH 8.5时，As(III)诱导层堆积增强，共存时引起片层对称性从六方晶系向正交晶系部分转换。在酸性和中性条件下，Mn(II)与As(III)共存表现为抑制效应；碱性条件下表现为协同效应。As(III)可作为重要还原剂触发锰氧化物的还原转化，影响其与微量金属的地球化学相互作用。', NULL, '11', '数据集', '重点实验室科学数据集模板', ARRAY['地球科学','地质学','矿物学（包括放射性矿物学）'], ARRAY['锰氧化物','砷','结构转变','氧化还原反应','X射线吸收精细结构谱'], '[{"Organization":{"@type":"Organization","name":"南京大学关键地球物质循环与成矿全国重点实验室","@id":"afae270c-5d31-4fa9-9325-25cd5bc8e219"},"@type":"Person","name":"陆现彩","en_name":"","@id":"1d0b9749-bb84-4f59-b83c-02c1f37808ca","email":"xcljun@nju.edu.cn"}]'::jsonb, '南京大学关键地球物质循环与成矿全国重点实验室', NULL, NULL, NULL, 'CC BY-NC-ND 4.0', 'condition', '联系通讯作者
