  ('f8dfde0a8e2748b2a3c067cd58d3da1d', 'f8ceaf000c824ea4bc79e20750f6aa14', '江苏省Landsat-ETM卫星遥感影像数据集（2009-2014年）', NULL, '本数据集为 2009-2014 年江苏省全域 Landsat_ETM_C2_L2 遥感影像，经标准大气校正与辐射精处理，含地表反射率及地表温度产品，30 米空间分辨率，时序连续完整。可支撑江苏省土地利用变化、河湖湿地演变、植被生态及城市热环境等长时序遥感监测研究。', '数据覆盖江苏省全域，采用 Landsat-7 ETM + 传感器 C2 二级产品，包含多光谱与热红外波段，附带质量 QA 波段，可识别云与阴影。2003 年后影像存在 SLC 条带缺失，可经插值修复使用，适用于湖泊流域、城乡建设及生态环境定量分析与时序动态研究。', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['江苏','landsat','遥感影像'], '[{"@type":"Organization","name":"江苏省水域生态科学数据中心","@id":"f1fc1653-1256-4f93-9a2e-1258542a80d2"}]'::jsonb, '江苏省水域生态科学数据中心', '江苏省', '2009-2014年', NULL, 'CC BY-NC-SA 4.0', 'open', NULL, 254599052800, 504, NULL, 4, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/f8dfde0a8e2748b2a3c067cd58d3da1d.png', '[{"name":"tar","count":504}]'::jsonb, '[{"storageNum":254599052800,"name":"tar"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-12', '2026-05-12'),
  ('6bad147540114ce0abf29c0d9c604eda', '3aadfbfc48ad47d0832f9f4f99cb4c4a', '太湖各湖区高锰酸盐指数数据集（2005-2010年）', NULL, '该数据集为江苏省典型湖泊2005-2010年水质数据集。 该数据来源于《中国湖泊生态环境研究报告》第三章湖泊生态环境评估。包含了江苏省典型湖泊全湖及各个分湖区的高锰酸盐，数据集包含1个Excel表格数据：江苏省典型湖泊各湖区高锰酸盐.xlsx。', '数据来源：数据来源于《中国湖泊生态环境研究报告》第三章太湖生态环境评估
质量控制：对数据进行二次核查，保证数据质量', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['太湖','高锰酸盐'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地理与湖泊研究所","en_name":"Nanjing Institute of Geography and Limnology","@id":"7599508ada754b5d83a2760af4e3f9ce"},"@type":"Person","name":"朱广伟","en_name":"","@id":"e915cdabe1ed48a0bb1695e1beb16754","email":"gwzhu@niglas.ac.cn"}]'::jsonb, '中国科学院南京地理与湖泊研究所', '太湖', '2005-2010年', NULL, 'CC BY-NC-SA 4.0', 'open', NULL, 17347, 2, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/6bad147540114ce0abf29c0d9c604eda.png', '[{"name":"xlsx","count":1},{"name":"png","count":1}]'::jsonb, '[{"storageNum":13439,"name":"xlsx"},{"storageNum":3908,"name":"png"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-08', '2026-05-08'),
  ('31b91abbcdc94da0a3dc95a41a4914ec', '1f8dae1ff5cd4f6c94956204c7da182e', '太湖各湖区透明度数据集（2005-2010年）', NULL, '该数据集为江苏省典型湖泊2005-2010年水质数据集。 该数据来源于《中国湖泊生态环境研究报告》第三章湖泊生态环境评估。包含了江苏省典型湖泊全湖及各个分湖区的透明度，数据集包含1个Excel表格数据：江苏省典型湖泊各湖区透明度.xlsx。', '数据来源：数据来源于《中国湖泊生态环境研究报告》第三章太湖生态环境评估
