  ('791443a91fc14672a802adf1393e2532', 'c68a8548e14b4f63ab1bfa76e40ad036', '宁镇扬一体化1:67万开发区数据集(2016年)', '', '该数据集为宁镇扬一体化空间分布数据，数据范围为宁镇扬一体化区域（南京、镇江、扬州），时间为2016年。通过对宁镇扬一体化空间分布图进行配准数字化得到宁镇扬一体化空间分布，数据主要包括森林公园、自然保护区、国家级经济技术开发区、省级高新技术产业开发区、省级经济开发区、限制开发区域、优化开发区域、重点开发区域、禁止开发区域等。数据以ESRI SHAPEFILE格式存储。', NULL, '11', '数据集', '地理数据集', ARRAY['城市地理学'], ARRAY['开发区','保护区','森林公园'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2016年', '10.12041/geodata.254413350006638.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 107195, 8, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/791443a91fc14672a802adf1393e2532.png', '[{"name":"zip","count":8}]'::jsonb, '[{"storageNum":107195,"name":"zip"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('095053f6a28a47f09277da94b65d8419', '4ec4c7c233384078bf12999e8eef2f9c', '江苏省357处省级地名文化遗产空间分布数据集(2022,2023年)', '', '《江苏省357处省级地名文化遗产空间分布数据集》共包括两个部分：（1）地名文化遗产空间位置矢量数据（.shp）；（2）地名文化遗产的属性数据，包括名称、批次、类型和行政区划等（.xls）。收集2022和2023年江苏省民政厅公布的两批次省级地名文化遗产名单，参照《中国古今地名大辞典》建立地名文化遗产中古今地名映射关系，基于国家民政部发布的中国·国家地名信息库获取各地名文化遗产的行政区划与地理坐标，生产了江苏省级地名文化遗产空间位置分布数据。', NULL, '11', '数据集', '地理数据集', ARRAY['人文地理学'], ARRAY['地名','文化遗产','空间分布'], '[{"Organization":{"@type":"Organization","name":"扬州大学","@id":"09635cab-f2e2-410e-b324-b713b543525f"},"@type":"Person","name":"叶鹏","en_name":"","@id":"f03bb2f4-c585-442d-9941-538c44ea0bd2","email":"007839@yzu.edu.cn"}]'::jsonb, '扬州大学', NULL, '2022,2023', '10.12009/YRDR.2024.2023.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用
', 1742606, 8, NULL, 0, 0, 0, 'adopt', 'release', 'V2', 'https://kxsj.jssic.cn/api/datasetLogo/2026/095053f6a28a47f09277da94b65d8419.png', '[{"name":"shx","count":1},{"name":"xml","count":1},{"name":"sbx","count":1},{"name":"dbf","count":1},{"name":"prj","count":1},{"name":"shp","count":1},{"name":"sbn","count":1},{"name":"xls","count":1}]'::jsonb, '[{"storageNum":2900,"name":"shx"},{"storageNum":483,"name":"xml"},{"storageNum":284,"name":"sbx"},{"storageNum":1546656,"name":"dbf"},{"storageNum":147,"name":"prj"},{"storageNum":9900,"name":"shp"},{"storageNum":3548,"name":"sbn"},{"storageNum":178688,"name":"xls"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('c8365c520ad541bfbdd4d5ff83bc9ad8', 'eeca737743e244b89069510bc6513875', '洪泽湖环湖水文站月流量数据集（2006-2021年）', NULL, '该数据集在2006-2021年代洪泽湖区水文年鉴的基础上进行人工整理，得到包含了洪泽湖环湖15个水文水位站点日流量数据。包含了所属河流、站点名称、时间、流量等指标。对日数据进行均值化处理得到月流量数据。数据集为1个excel表格文件，月流量.xlsx。', '数据来源：淮河流域水文资料 第3册 淮河中游区（涡河、洪泽湖水系）（2006-2021年）
数据加工方法：提取《淮河流域水文资料 第3册 淮河中游区（涡河、洪泽湖水系）》中水文站及日均水位指标，对相关要素整理、扫描数字化，再按照标准格式，将流量及相关站点信息摘录成表格格式。
质量控制：在人工摘录、加工过程中进行了两轮与原始数据的人工比对校核，纠正错误信息，数据质量可靠。', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['洪泽湖','水文站','月流量'], '[{"@type":"Organization","name":"江苏省水域生态科学数据中心","@id":"f1fc1653-1256-4f93-9a2e-1258542a80d2"}]'::jsonb, '江苏省水域生态科学数据中心', '洪泽湖', '2006-2021年', '10.11971/lim.2025.075.db.lwdc', 'CC BY-NC-SA 4.0', 'condition', '需要用户提交申请表进行离线申请', 39467, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/c8365c520ad541bfbdd4d5ff83bc9ad8.png', '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":39467,"name":"zip"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-08', '2026-05-08'),
  ('84179f40fa3540af8dadd5423636bbc6', 'ac679fd21ade41cc9baad8b6c4f85941', '太湖总磷常规监测数据集（2000-2005年）', NULL, '"该数据集数据源为中国科学院太湖湖泊生态系统研究站监测数据，包含了太湖14个水质监测站点数据，及太湖水总磷的逐月观测记录数据。
数据内容包含了1个excel表格，“太湖总磷2000-2005.xlsx”。', '数据来源：数据来自中国科学院太湖湖泊生态系统研究站观测数据
数据加工方法：中国科学院太湖湖泊生态系统研究站是一个以湖泊科学的基础研究和应用基础研究为主、能长期积累大型湖泊资料、临湖性的综合性湖泊生态系统研究站，自1991年建站以来，连续收集太湖的气象、水体物理和化学指标、水生生物指标等有关湖泊生态系统方面的数据。
质量控制：观测阶段，由长期工作在太湖站的专业人员进行观测和观测仪器维护工作。数据整理和入库过程的质量控制方面，主要分为两个步骤：（1）进行了各种源数据的集成、整理、转换、格式统一；（2）通过一系列质量控制方法，去除随机及系统误差。使用的质量控制方法，包括极值检查、内部一致性检查，以保障数据的质量。', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['太湖','总磷'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地理与湖泊研究所","en_name":"Nanjing Institute of Geography and Limnology","@id":"7599508ada754b5d83a2760af4e3f9ce"},"@type":"Person","name":"朱广伟","en_name":"","@id":"e915cdabe1ed48a0bb1695e1beb16754","email":"gwzhu@niglas.ac.cn"}]'::jsonb, '中国科学院南京地理与湖泊研究所', '太湖', '2000-2005年', NULL, 'CC BY-NC-SA 4.0', 'open', NULL, 18196, 1, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/84179f40fa3540af8dadd5423636bbc6.png', '[{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":18196,"name":"xlsx"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-08', '2026-05-08'),
  ('b35752def5f44b4fb8ee6e5a22d9b633', '0cc580a182ef4e8884213d35cda40980', '宁杭生态经济带30m分辨率土地覆被数据(2015年)', '', '该数据借助开源全球土地覆被数据，集合宁杭生态经济带规划范围进行拼接、裁剪，形成宁杭生态经济带土地覆被数据，利用本地土地覆被样本库进行质量检验，形成区域研究可用的2015年宁杭生态经济带30m分辨率土地覆被数据。', NULL, '11', '数据集', '地理数据集', ARRAY['地理学'], ARRAY['宁杭生态经济带','土地覆被'], '[]'::jsonb, '南京师范大学地理科学学院', NULL, '2015年', '', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 11369955, 16, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/b35752def5f44b4fb8ee6e5a22d9b633.png', '[{"name":"adf","count":7},{"name":"xml","count":2},{"name":"dat","count":3},{"name":"nit","count":3},{"name":"dir","count":1}]'::jsonb, '[{"storageNum":11358228,"name":"adf"},{"storageNum":8907,"name":"xml"},{"storageNum":240,"name":"dat"},{"storageNum":1440,"name":"nit"},{"storageNum":1140,"name":"dir"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('6e2dcae1d23d494b9a6996df47050ebd', '0937302cba70467fb635bac598dde58d', '苏南现代化示范区30m分辨率土地覆被数据(2015年)', '', '该数据借助开源全球土地覆被数据，集合苏南现代化示范区规划范围进行拼接、裁剪，形成苏南现代化示范区土地覆被数据，利用本地土地覆被样本库进行质量检验，形成区域研究可用的2015年苏南现代化示范区30m分辨率土地覆被数据。', NULL, '11', '数据集', '地理数据集', ARRAY['地理学'], ARRAY['苏南现代化示范区','土地覆被'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2015年', '', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 21840160, 24, NULL, 0, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/6e2dcae1d23d494b9a6996df47050ebd.png', '[{"name":"adf","count":15},{"name":"xml","count":2},{"name":"dat","count":3},{"name":"nit","count":3},{"name":"dir","count":1}]'::jsonb, '[{"storageNum":21828412,"name":"adf"},{"storageNum":8928,"name":"xml"},{"storageNum":240,"name":"dat"},{"storageNum":1440,"name":"nit"},{"storageNum":1140,"name":"dir"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('72a6a476c50f4824b7e751f53c51cab7', 'a91bd4e650c04a5cb553a89e60809bea', '江苏省1:170万地下水开采条件数据(1989年)', '', '该数据集为江苏省地下水开采条件空间分布数据，数据范围为江苏省，时间为1989年。通过对江苏省地下水开采条件图进行配准数字化并结合在线地图进行数据更新得到江苏省地下水开采条件空间分布位置，数据内容主要包括江苏省地下水富水程度、开采顶板埋深、地下水水质、超过饮用水质标准离子、地下水水源地及富水带等。数据以ESRI SHAPEFILE格式存储。', NULL, '11', '数据集', '地理数据集', ARRAY['水文地质学（包括放射性水文地质学）'], ARRAY['地下水','水文地质','顶板埋深'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '1989年', '10.12041/geodata.129063650957552.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 838175, 112, NULL, 0, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/72a6a476c50f4824b7e751f53c51cab7.png', '[{"name":"shx","count":16},{"name":"xml","count":16},{"name":"sbx","count":16},{"name":"dbf","count":16},{"name":"prj","count":16},{"name":"shp","count":16},{"name":"sbn","count":16}]'::jsonb, '[{"storageNum":20144,"name":"shx"},{"storageNum":26219,"name":"xml"},{"storageNum":3720,"name":"sbx"},{"storageNum":124396,"name":"dbf"},{"storageNum":2320,"name":"prj"},{"storageNum":635008,"name":"shp"},{"storageNum":26368,"name":"sbn"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('ce43f8ff000b4206b46cf7656b695361', '71735bdf99a9481ebe6f7dc988e7e4d6', '江苏省12.5m数字高程数据产品', '', '该数据集为江苏省范围内ALOS 12.5m DEM数据产品。ALOS是日本宇宙航空研究所（JAXA）的Advanced Land Observing Satellite-1（高级陆地观测卫星-1，ALOS）项目。12.5mDEM 数据，是ALOS（Advanced Land Observing Satellite. 2006年发射）卫星相控阵型L波段合成孔径雷达（PALSAR）采集。该传感器具有高分辨率、扫描式合成孔径雷达、极化三种观测模式。该数据水平及垂直精度可达12.5米。', NULL, '11', '数据集', '地理数据集', ARRAY['地貌学'], ARRAY['数字高程','ALOS','DEM'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '', '', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 968364891, 1, NULL, 3, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/ce43f8ff000b4206b46cf7656b695361.png', '[{"name":"rar","count":1}]'::jsonb, '[{"storageNum":968364891,"name":"rar"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('721e85eacdcb41c0853a4e8724699805', 'b5cadfd62aba4fd48dd1bb335f1a14a0', '太湖各湖区总氮数据集（2011-2015年）', NULL, '该数据集为江苏省典型湖泊2011-2015年水质数据集。 该数据来源于《中国湖泊生态环境研究报告》第三章湖泊生态环境评估。包含了江苏省典型湖泊全湖及各个分湖区的总氮，数据集包含1个Excel表格数据：江苏省典型湖泊各湖区总氮.xlsx。', '数据来源：数据来源于《中国湖泊生态环境研究报告》第三章太湖生态环境评估
