  ('bddfff1e01df4c46bfde14c6568352a8', 'ec85bca902a04dfd85df913c2c1817c0', '江苏省主要文物旅游景点名录数据集(旧石器时代至今)', '', '该数据集为江苏省主要文物旅游景点名录数据集，时间为旧石器时代至今。该数据包含据包含 199 条记录，包含基本属性、不可移动文物属性、景区属性、历史文化相关属性 4 类属性。基本属性包含文物旅游景点名称、所属行政区划、判断标准 3 个字段；不可移动文物属性包含保护级别、批次、时代、类型 4 个字段；景区属性包含所属景区名称、景区级别、景区地址、景区热度、景点是否免费 5 个字段；历史文化相关属性包含相关人物、相关事件、相关作品 3 个字段。', NULL, '11', '数据集', '地理数据集', ARRAY['人文地理学'], ARRAY['历史文化','景区','名胜古迹'], '[{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"胡迪","en_name":"","@id":"6c0002d7-25b0-4687-bb66-544c4b8368dc","email":"geodata@njnu.edu.cn"}]'::jsonb, '南京师范大学', NULL, '旧石器时代至今', '10.12009/YRDR.2024.2005.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 34292, 202, 1, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/bddfff1e01df4c46bfde14c6568352a8.png', '[]'::jsonb, '[]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('8a3f6e6b92e840908c35779bb59472b3', 'f1261dfde4cf48349aa13ed50abe10ca', '江苏省1:10万建设用地数据集(1980s-2010年)', '', '该数据集主要范围包括江苏省全境地级市。该图反映了江苏省城市建设用地分布现状及其地域分布规律，以ESRI Shape格式存储。处理方法是对遥感数据进行融合增强处理，然后对其进行目视解译、精度检验，再对各幅进行拼接处理。', NULL, '11', '数据集', '地理数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['建设用地','城建区','土地利用'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '1980s-2010年', '10.12041/geodata.135639946851214.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 3471941, 5, NULL, 0, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/8a3f6e6b92e840908c35779bb59472b3.png', '[{"name":"rar","count":5}]'::jsonb, '[{"storageNum":3471941,"name":"rar"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('b83bc4efe6ab46399c8450b00441b400', 'a2cf96301ffe49f8a62bf471107d9935', '太湖流域氮磷载荷时空分布数据集（2000-2020年）', NULL, '该数据集为太湖流域氮磷等营养要素载荷时空分布数据，包含了2000-2020年的数据。在气象数据、土壤分类数据、土地利用数据、DEM数据等基础上，通过公式计算得到研究区的营养要素流失数据，包含了氮流失、磷流失栅格数据。 数据集包含了氮、磷不同要素的流失等共计42景栅格数据，氮流失数据命名为TN+year.tif，磷流失数据命名为TN+year.tif。', '数据来源：Global Precipitation Measurement v6 (GPM)、中国高分辨率国家土壤信息格网基本属性数据集、Terra Vegetation Indices MOD13A2 V6.1、SRTM Digital Elevation Data v4 (SRTM DEM)、中国科学院地理科学与资源研究所中国多时期土地利用/土地覆盖遥感监测数据集
数据加工方法：面源氮磷载荷计算方法以传统的通用水土流失方程（RUSLE）为基础，并考虑了泥沙输移比以及土壤中氮磷含量这两个关键因素，用于表征流域面源污染条件下的污染物流失量。
质量控制：将实测水文站点数据与对应流域估算的土壤水蚀模数进行统计比较，精度可达到70%，验证方法参考：
吴瀚逸，熊俊峰，侯渲，林晨，许金朵，马荣华．2001-2020年中国东北区域土壤水蚀数据集．中国科学数据，2023．
投影坐标：WGS84坐标系
分辨率：30m', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['太湖','氮磷载荷'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地理与湖泊研究所","en_name":"Nanjing Institute of Geography and Limnology","@id":"7599508ada754b5d83a2760af4e3f9ce"},"@type":"Person","name":"熊俊峰","en_name":"","@id":"bf0ceb00-b9cf-4135-ab28-d8748ff0dd87","email":"jfxiong@niglas.ac.cn"}]'::jsonb, '中国科学院南京地理与湖泊研究所', '洪泽湖', '2000-2020年', '10.11971/geo.2024.038.db.lwdc', 'CC BY-NC-SA 4.0', 'condition', '需要用户提交申请表进行离线申请', 105715379, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/b83bc4efe6ab46399c8450b00441b400.png', '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":105715379,"name":"zip"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-08', '2026-05-08'),
