  ('993e9b96de1744acb259f7a607b875a9', '6f3a2f5a34da41018e7397ef4c2f1bbc', '江苏省1:10万土地利用数据(1980s-2015年)', '', '该数据集为江苏省1：10万土地利用数据，时间为1980s-2015年。该数据反映了江苏省土地利用的特点和利用的合理程度及其地域分布规律，包括耕地、林地、草地、水域、建设用地和未利用地在内的6个一级类以及25个二级类型。以及每个地类的周长与面积。数据以ESRI Shape格式存储。', NULL, '11', '数据集', '地理数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['土地利用','遥感','图像分类'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '1980s-2015年', '10.12041/geodata.234702324325454.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 122803814, 8, NULL, 4, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/993e9b96de1744acb259f7a607b875a9.png', '[{"name":"rar","count":7},{"name":"doc","count":1}]'::jsonb, '[{"storageNum":122752614,"name":"rar"},{"storageNum":51200,"name":"doc"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('f38b29815dd742728ff7e05a4f3fe714', 'fc2b5c58b2bf463fac8d1c1d50aca53f', '江苏省市县经济统计数据集(2010年)', '', '该数据集是江苏省2010年市县社会经济统计数据。根据江苏省统计年鉴及其他统计资料辅助整理获得， 分为人口、从业人员、生产总值、交通运输、固定资产投资完成额、文化卫生、财政收入、科技教育等，其中指标包括在岗职工人数（万人）、乡村从业人员（万人）、地方生产总值（万元）、农林牧渔业总产值（万元）、工业企业个数（个）、工业总产值（万元）、公路客运量（万人）、公路货运量（万吨）、城镇固定资产投资（万元）、公共图书馆（个）、公共图书馆藏书（千册）、卫生机构数（个）、卫生机构床位数（张）、卫生技术人员（人）、地方财政一般预算收入（万元）等指标，数据年代为2010年，该数据集格式为Excel格式。该数据集是根据中国知网《江苏省统计年鉴2011年》及其他统计资料进行整理获得。', NULL, '11', '数据集', '地理数据集', ARRAY['人文地理学'], ARRAY['人口','经济','统计数据'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2010年', '10.12041/geodata.113648647340899.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 171671, 1690, 25, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/f38b29815dd742728ff7e05a4f3fe714.png', '[]'::jsonb, '[]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('1d094a5ebaf042f1b48843487403bf12', '65f0e4a983404b8f90cb07f4239553b0', '江苏省市县经济统计数据集(2009年)', '', '该数据集是江苏省2009年市县社会经济统计数据。根据江苏省统计年鉴及其他统计资料辅助整理获得， 分为人口、从业人员、生产总值、交通运输、固定资产投资完成额、文化卫生、财政收入、科技教育等，其中指标包括在岗职工人数（万人）、乡村从业人员（万人）、地方生产总值（万元）、农林牧渔业总产值（万元）、工业企业个数（个）、工业总产值（万元）、公路客运量（万人）、公路货运量（万吨）、城镇固定资产投资（万元）、公共图书馆（个）、公共图书馆藏书（千册）、卫生机构数（个）、卫生机构床位数（张）、卫生技术人员（人）、地方财政一般预算收入（万元）等指标，数据年代为2009年，该数据集格式为Excel格式。该数据集是根据中国知网《江苏省统计年鉴2010年》及其他统计资料进行整理获得。', NULL, '11', '数据集', '地理数据集', ARRAY['人文地理学'], ARRAY['人口','经济','统计数据'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2009年', '10.12041/geodata.115847670478413.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 183659, 1688, 27, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/1d094a5ebaf042f1b48843487403bf12.png', '[]'::jsonb, '[]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('7002f840b04b4ce0be023a2387e1c781', '3bd104c68b9445d5bce4cb4b1449fe19', '江苏省乡镇社会经济、人口统计数据集(2002年)', '', '该数据集根据江苏省各级政府统计年鉴整理获得，包括江苏省各市、县及乡镇级的社会经济和人口统计数据。数据内容包括：县市人口，户数及土地面积，年末从业人员，在岗职工及城镇私营个体从业人员，乡村从业人员，国内生产总值，国内生产总值构成及指数，农林牧渔业总产值，农业生产情况，农产品产量，工业企业单位数，工业总产值，工业企业主要经济指标，交通运输，邮电电力，固定资产投资完成额，国内贸易，对外经济贸易，财政主要指标，金融保险主要指标，人民生活，科技教育，文化卫生，环境保护。该数据集是根据《江苏省统计年鉴2003年》以及市县统计数据、其他统计资料进行整理获得。', NULL, '11', '数据集', '地理数据集', ARRAY['人文地理学'], ARRAY['社会','经济','人口'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2002年', '10.12041/geodata.52075997611544.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 3069936, 1, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/7002f840b04b4ce0be023a2387e1c781.png', '[{"name":"rar","count":1}]'::jsonb, '[{"storageNum":3069936,"name":"rar"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('c59f015dacfe48c49c1c5c58de8e8cef', '33c4f4d196774b6199c6e5719c1cf689', '江苏省城市建成区用地类型数据(2002年)', '', '该数据集是长江三角洲范围内江苏省13个市建成区2002年用地情况空间分布情况调查数据，该数据原始数据格式为*.shapefile，成图为*.tif格式。方便相关人员对城市建设进行空间分析，以及为城市扩张城市规划发展辅助规划决策提供理论依据。', NULL, '11', '数据集', '地理数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['城市建成区','土地利用'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2002年', '10.12041/geodata.247786365858786.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 1454387670, 98, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/c59f015dacfe48c49c1c5c58de8e8cef.png', '[{"name":"tif","count":11},{"name":"txt","count":1},{"name":"shx","count":13},{"name":"xml","count":9},{"name":"sbx","count":13},{"name":"dbf","count":13},{"name":"prj","count":12},{"name":"shp","count":13},{"name":"sbn","count":13}]'::jsonb, '[{"storageNum":1442254694,"name":"tif"},{"storageNum":110,"name":"txt"},{"storageNum":119500,"name":"shx"},{"storageNum":20618,"name":"xml"},{"storageNum":10452,"name":"sbx"},{"storageNum":991796,"name":"dbf"},{"storageNum":5024,"name":"prj"},{"storageNum":10836480,"name":"shp"},{"storageNum":148996,"name":"sbn"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('5bb9ec9d730e4314b9de3291bac50f84', 'c1383d4c93284e46a55b84099ba4793a', '江苏省1:25万风景名胜区及国家地质公园空间分布数据(2013年)', '', '该数据是根据依据江苏省及市县环保局收集到的关于江苏省环境保护区资料，对照百度地图等工具，运用ArcGIS软件对数据进行数字化得到。内容包括风景名胜区、国家地质公园等。数据格式为Shapefile格式。', NULL, '11', '数据集', '地理数据集', ARRAY['人文地理学'], ARRAY['风景名胜','地质公园'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2013年', '10.12041/geodata.102654665284780.ver1.db', NULL, 'condition', '数据申请使用', 73945, 1, NULL, 3, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/5bb9ec9d730e4314b9de3291bac50f84.png', '[{"name":"rar","count":1}]'::jsonb, '[{"storageNum":73945,"name":"rar"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
