  ('16267b035dff480c87871799f8b0dab9', '6f245b0e45204ef4b794feade41a0486', '长三角1km高分辨率高质量逐年PM10数据集(2016-2021年)', '', '该数据为长三角1km高分辨率高质量逐日PM10数据集，时间为2016-2021年。数据集的空间范围覆盖整个长三角区域，时间分辨率为日，单位为μg/m3，数据内容包括长三角地区2016年以来逐日无缝1公里地面PM10数据，以GeoTIFF(.tif)格式进行存储。', NULL, '11', '数据集', '地理数据集', ARRAY['大气科学'], ARRAY['PM10','空气污染','环境质量'], '[{"Organization":{"@type":"Organization","name":"马里兰大学","@id":"9fd4f41e-caeb-49de-a2e4-11366adc6a98"},"@type":"Person","name":"韦晶","en_name":"","@id":"b219362d-0877-4d96-b475-1dbca6aac7e7","email":"weijing_rs@163.com"}]'::jsonb, '马里兰大学', NULL, '2016-2021年', '10.12041/geodata.175423018961390.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 19274244, 6, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/16267b035dff480c87871799f8b0dab9.png', '[{"name":"tif","count":6}]'::jsonb, '[{"storageNum":19274244,"name":"tif"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('78a2e1a26de549179610f5d7d552c7f5', '457b4f09ab5f4b0384652bec942c7cb3', '长三角1km高分辨率高质量逐年PM10数据集(2011-2015年)', '', '该数据该数据为长三角1km高分辨率高质量逐日PM10数据集，时间为2011-2015年。数据集的空间范围覆盖整个长三角区域，时间分辨率为日，单位为μg/m3，数据内容包括长三角地区2011年以来逐日无缝1公里地面PM10数据，以GeoTIFF(.tif)格式进行存储。', NULL, '11', '数据集', '地理数据集', ARRAY['大气科学'], ARRAY['PM10','空气污染','环境质量'], '[{"Organization":{"@type":"Organization","name":"马里兰大学","@id":"9fd4f41e-caeb-49de-a2e4-11366adc6a98"},"@type":"Person","name":"韦晶","en_name":"","@id":"b219362d-0877-4d96-b475-1dbca6aac7e7","email":"weijing_rs@163.com"}]'::jsonb, '马里兰大学', NULL, '2011-2015年', '10.12041/geodata.175423018961390.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 16061870, 5, NULL, 1, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/78a2e1a26de549179610f5d7d552c7f5.png', '[{"name":"tif","count":5}]'::jsonb, '[{"storageNum":16061870,"name":"tif"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('e174fa1e54a14cba931985575fe4bb8c', '783968274490403c9512122db44ee73e', '长三角1km高分辨率高质量逐年PM2.5数据集(2016-2021年)', '', '该数据为长三角1km高分辨率高质量逐月PM2.5数据集，时间为2016-2021年。数据集空间范围覆盖整个长三角地区，时间分辨率为月，单位为μg/m3，内容包括长三角2016年以来逐月无缝1公里近地表PM2.5数据，以GeoTIFF(.tif)格式进行存储。', NULL, '11', '数据集', '地理数据集', ARRAY['大气科学'], ARRAY['PM2.5','空气污染','环境质量'], '[{"Organization":{"@type":"Organization","name":"马里兰大学","@id":"9fd4f41e-caeb-49de-a2e4-11366adc6a98"},"@type":"Person","name":"韦晶","en_name":"","@id":"b219362d-0877-4d96-b475-1dbca6aac7e7","email":"weijing_rs@163.com"}]'::jsonb, '马里兰大学', NULL, '2016-2021年', '10.12041/geodata.160029799926049.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 19274244, 6, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/e174fa1e54a14cba931985575fe4bb8c.png', '[{"name":"tif","count":6}]'::jsonb, '[{"storageNum":19274244,"name":"tif"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('c4e305d5a4a44ccc8b95f145617e078f', 'c62a854ba9b04957857b01f2b1d6e687', 'Simulation method for indoor airflow based on the Industry Foundation Classes model', NULL, '室内气流是影响室内热舒适与人体健康的重要因素，也是建筑设计、理想人居环境及绿色建筑领域的重要考量。目前，室内气流模拟所需建筑模型多由研究人员手动创建，建模效率低且易出错。为此，本研究分析了建筑信息模型（BIM）通用标准数据模型 IFC（Industry Foundation Class）与室内气流模拟所需空间网格的异同，提出了从 IFC 模型到空间网格的转换方法。该方法利用 IFC 模型丰富的语义、几何及关系信息，自动提取建筑室内空间、划分数值计算网格，并将语义属性信息映射至空间网格。在此基础上，结合 OpenFOAM 构建集成化模拟框架，对建筑室内空间气流运动进行模拟。结果表明，该方法可利用现有 IFC 模型自动构建空间网格而无需重新建模，为室内气流建模提供了重要支撑；集成化模拟框架通过工具链将模型构建、模拟分析等环节贯通，简化了模拟操作，便于室内气流模拟的广泛应用，有助于建筑设计与优化，并为相关数值模拟研究与数字城市建模提供参考。', NULL, '14', '论文', '论文元数据', ARRAY['城市地理学'], ARRAY['室内空气流动','气流','计算流体动力学','工业基础类模型','Open'], '[{"Organization":{"@type":"Organization","name":"南京师范大学","@id":"1e1b713f40034c338b634c43da5df724"},"@type":"Person","name":"兰馨","en_name":"","@id":"f567371e-1e00-4388-98b0-6dbc40080168","email":"zhoulch@njnu.edu.cn"}]'::jsonb, '南京师范大学', NULL, NULL, '10.57841/casdc.0007237', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 7859066, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"pdf","count":1}]'::jsonb, '[{"storageNum":7859066,"name":"pdf"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, '2026-05-08', '2026-05-08'),
  ('cce895b2daff45d59969879c6904e1d9', 'feb24b11421847e7ba6d1a74844c5b91', '长三角1km高分辨率高质量逐年PM2.5数据集(2011-2015年)', '', '该数据为长三角1km高分辨率高质量逐月PM2.5数据集，时间为2011-2015年。数据集空间范围覆盖整个长三角地区，时间分辨率为月，单位为μg/m3，内容包括长三角2000年以来逐月无缝1公里近地表PM2.5数据，以GeoTIFF(.tif)格式进行存储。', NULL, '11', '数据集', '地理数据集', ARRAY['大气科学'], ARRAY['PM2.5','空气污染','环境质量'], '[{"Organization":{"@type":"Organization","name":"马里兰大学","@id":"9fd4f41e-caeb-49de-a2e4-11366adc6a98"},"@type":"Person","name":"韦晶","en_name":"","@id":"b219362d-0877-4d96-b475-1dbca6aac7e7","email":"weijing_rs@163.com"}]'::jsonb, '马里兰大学', NULL, '2011-2015年', '10.12041/geodata.122598355314737.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 16061870, 5, NULL, 2, 0, 0, 'adopt', 'release', 'V2', 'https://kxsj.jssic.cn/api/datasetLogo/2026/cce895b2daff45d59969879c6904e1d9.png', '[{"name":"tif","count":5}]'::jsonb, '[{"storageNum":16061870,"name":"tif"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('a50b1d2ab7114adfaf9a9589206c3b91', 'ee7a94dea4314e28b3415bc95c697acf', '矿井水害信息系统', NULL, '开展了典型矿区不同类型水文地质结构特征研究和突水案例分析、统计，对整理统计的70余个典型矿井突水案例（各煤矿沉积环境、地质构造、水文地质特征与地下水流场、工程地质信息、突水水量、水压、通道、突水识别技术）进行分类。基于矿井水文地质结构的水害类型划分，构建了典型水害类型突水信息数据库。
中国矿业大学.矿井水害信息系统.(V1).中国矿业大学[创建机构],2024-11-03.国家基础学科公共科学数据中心[发布机构],https://cstr.cn/16666.11.nbsdc.o6jysha5', NULL, '19', '软件', '软件元数据', ARRAY['水文地质学（包括放射性水文地质学）'], ARRAY['时间','事故名称','水害类型'], '[{"@type":"Organization","name":"中国矿业大学","@id":"65da6f1ba3314423b565cb942b4d7b89"}]'::jsonb, '中国矿业大学', NULL, NULL, '10.57841/casdc.0007234', 'CC0', 'open', NULL, 14015, 1, NULL, 0, 0, 0, 'adopt', 'release', 'V1', NULL, '[{"name":"docx","count":1}]'::jsonb, '[{"storageNum":14015,"name":"docx"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, '2026-05-08', '2026-05-08'),
  ('213a1807d1424a45b17506bf591c9a29', '037f4200d6be4bad84fbe57afe749e11', '长三角公里格网人口密度数据集(2000、2010、2015、2020年)', '', '该数据为长三角公里格网人口密度数据集，时间分别为2000、2010、2015和2020年。数据文件以30弧秒(赤道约1公里)分辨率的全球栅格显示。整个数据采用比例分配网格算法，利用行政单位将人口计数分配到30弧秒网格单元上。', NULL, '11', '数据集', '地理数据集', ARRAY['人文地理学'], ARRAY['社会','人口','格网化'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2000年,2010年,2015年,2020年', '10.12041/geodata.170964235696203.ver1.db：注册码无效：注册码无效', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 12109681, 164, NULL, 4, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/213a1807d1424a45b17506bf591c9a29.png', '[{"name":"adf","count":24},{"name":"xml","count":8},{"name":"dat","count":64},{"name":"nit","count":64},{"name":"dir","count":4}]'::jsonb, '[{"storageNum":12011026,"name":"adf"},{"storageNum":32351,"name":"xml"},{"storageNum":5120,"name":"dat"},{"storageNum":36864,"name":"nit"},{"storageNum":24320,"name":"dir"}]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-07'),
  ('761cb73a09ff4694b0c2113156c9ea75', '60bd91e585824aae9e1d1bb2cb492066', '江苏省1:100万主要河流数据集（2002年）', NULL, '该数据集为江苏2002年1:100万主要河流数据，每条河流均为一完整的空间要素，属性信息唯一，包含了河流名称及其对应的河流代码。数据内容包含了一个shp矢量文件，“100万水系.shp”。', '数据来源：全国1:100万基础地理数据
