  ('b375ed4049754a62923331de7f757aea', '80d2dec819ec4852bf4d50064b76e889', '江苏省水资源统计数据(2021年)', '', '该数据为江苏省水资源统计数据集，时间为2021年。该数据集主要包括降水量、降水总量、降水总量年增长率、降水总量多年平均增长率、水资源总量、地表水资源量、地下水资源量、入省境水量、出省境水量、大型水库年末蓄水总量、总供水量、地表水源供水量、总用水量、生产用水量、农业灌溉耗水量等。该数据集的格式为excel格式。', NULL, '11', '数据集', '地理数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['地表水','水资源总量','蓄水工程'], '[{"@type":"Organization","name":"江苏省地理空间智能与人地系统科学数据中心","@id":"99d89b3d-60f6-4784-9dcc-6ef78708f4d5"}]'::jsonb, '江苏省地理空间智能与人地系统科学数据中心', NULL, '2021年', '10.12009/YRDR.2025.1006.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '数据申请使用', 23471, 49, 5, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/b375ed4049754a62923331de7f757aea.png', '[]'::jsonb, '[]'::jsonb, '李杨 戴玲', 'geodata@njnu.edu.cn', '南京师范大学地理科学学院', '南京市栖霞区文苑路1号', '210023', '2026-05-08', '2026-05-08'),
  ('f45e9e8ad5ad4972bd6df9bf7f28cf52', '5064280c6f774c5ba3fec10e4fb2e093', '江苏省水产养殖池塘空间分布数据集（2023年）', NULL, '以江苏的养殖池塘为研究对象，利用2023年的Sentinel-2高分辨率数据，基于GEE绘制了江苏的水产养殖池塘空间分布图，总体分类准确率达到90%以上。数据集包含1个文件夹，每个文件夹包含1个shp矢量数据。', '数据来源：基于Sentinel-2地表反射率数据
GLC_FCS30_2020 数据集
中国水库数据集（CRD）
CODCLAB 数据集
数据加工方法：本研究以中国的养殖池塘为研究对象，构建了适用于养殖池塘提取的光谱指数，开发了一套融合WVndapi指数的机器学习大尺度养殖池塘自动化提取方法的分类优化方法，利用2023年的Sentinel-2高分辨率数据，基于GEE绘制了中国的水产养殖池塘分布图，总体分类准确率达到90%以上。具体研究方法见参考论文:
Chen, J., Lin, C., Xue, K., et al. (2025). Mapping China aquaculture ponds: Integrating a new aquaculture index with machine learning. Earth''s Future, 13, e2024EF005637.
质量控制：研究利用贝叶斯优化构建了针对 AP 的方向性专用索引 WVndapi。研究提出了一种整合 WVndapi 的分类优化方法索引，能够在大规模自动提取 AP。该方法由三个主要模块组成：预处理模块、分类特征选择模块和机器学习模块，这些组件共同旨在生成中国 AP 的高分辨率数据。总体精度为90%
投影坐标：空间范围为江苏养殖池塘，投影方式为WGS84。', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['江苏省','水产养殖池塘','空间分布'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地理与湖泊研究所","en_name":"Nanjing Institute of Geography and Limnology","@id":"7599508ada754b5d83a2760af4e3f9ce"},"@type":"Person","name":"林晨","en_name":"","@id":"4376ddb4-ccca-4a07-a764-48d06249909d","email":"clin@niglas.ac.cn"}]'::jsonb, '中国科学院南京地理与湖泊研究所', '江苏省', '2023年', '10.11971/lim.2025.056.db.lwdc', 'CC BY-NC-SA 4.0', 'condition', '需要用户提交申请表进行离线申请', 158943544, 1, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/f45e9e8ad5ad4972bd6df9bf7f28cf52.png', '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":158943544,"name":"zip"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-07', '2026-05-07'),
  ('909445f385154c5a829137af048aa745', '8797075d554445d0a31694cd817ef0ed', '江苏省城市湖泊分布数据集（2020年）', '', '该数据集为江苏省城市湖泊分布数据，包含了面积0.001平方公里以上的城市湖泊分布数据，数据集包括了Type1、Type2、Type3三种类型的城市湖泊。 数据集包含2个shp矢量文件，js_Urban_Lake_Type1_&_Type2.shp，js_Urban_Lake_Type3.shp。', '数据来源：Sentinel-2 10米分辨率的遥感影像数据
数据加工方法：利用10米分辨率的Sentinel-2影像数据集提取水体，再参考全球城市边界数据集分析，最终得出3种类型的城市湖泊数据。具体数据加工方法参考论文Song C , Jiang X , Fan C ,et al.High-resolution circa-2020 map of urban lakes in China[J].Scientific Data[2024-12-05].DOI:10.1038/s41597-022-01874-6.
质量控制：通过与人工采样的城市单元进行比较进行评估，平均准确率为81.85%
投影坐标：空间范围为江苏省，WGS84坐标系。', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['江苏省','城市湖泊'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地理与湖泊研究所","en_name":"Nanjing Institute of Geography and Limnology","@id":"7599508ada754b5d83a2760af4e3f9ce"},"@type":"Person","name":"宋春桥","en_name":"","@id":"13a025e4-dc75-4dec-97d4-8e26b12b4fbe","email":"cqsong@niglas.ac.cn"}]'::jsonb, '中国科学院南京地理与湖泊研究所', '江苏省', '2020年', '10.11971/lim.2024.134.db.lwdc', 'CC BY-NC-SA 4.0', 'condition', '需要用户提交申请表进行离线申请', 2654778, 1, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/909445f385154c5a829137af048aa745.png', '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":2654778,"name":"zip"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-07', '2026-05-07'),
  ('f71e6cb93b934031a93a4b3b7f079607', 'e1d9b2d1ab6643b993abcb66ca8fb008', '长江沿岸重点城市取水口数据集（2016年）', '', '该数据集为长江流域沿岸重点城市取水地数据，根据2016年长江流域及西南诸河水资源公报公布的40余个水源地数据，提取1:25万基础地理数据中所需水库数据；根据百度等搜索到资料，结合网络地图，查找定位各水源地位置，最终得到长江流域部分重点城市取水水源地空间分布数据。数据集为点图层的shp矢量数据，按照各市分别存放，包含了15个shp矢量文件，每个矢量文件包含取水单位、所属城市、取水水源等指标信息。', '数据来源：长江流域及西南诸河水资源公报（2016），水利部长江水利委员会
数据加工方法：根据2016年长江流域及西南诸河水资源公报公布的40余个水源地数据，提取1:25万基础地理数据中所需水库数据；根据百度等搜索到资料，结合网络地图，查找定位各水源地位置，最终得到长江流域部分重点城市取水水源地空间分布数据
质量控制：最终得到点位数据与网络地图结合，以期对数据的二次校对，数据完整性、逻辑一致性、位置精度、属性精度、接边精度、现势性均符合国家测绘局制定的有关技术规定和标准的要求，质量优良可靠
投影坐标：空间范围为长江流域成都、贵阳、合肥、景德镇、九江、昆明、南昌等15个城市，为WGS84坐标系', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['长江','重点城市','取水口'], '[{"@type":"Organization","name":"江苏省水域生态科学数据中心","@id":"f1fc1653-1256-4f93-9a2e-1258542a80d2"}]'::jsonb, '江苏省水域生态科学数据中心', '长江', '2016年', '10.12041/geodata.170823495785052.ver1.db', 'CC BY-NC-SA 4.0', 'condition', '需要用户提交申请表进行离线申请', 66923, 1, NULL, 2, 0, 0, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/f71e6cb93b934031a93a4b3b7f079607.png', '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":66923,"name":"zip"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-07', '2026-05-07'),
  ('590ffe206cb7408e83720d4940e5bc96', '3e0345b4d3c14e0aaeda09406acb1c6c', '长江沿岸码头数据集（2010-2015年）', NULL, '该数据集为长江沿岸码头数据集，主要内容为沿长江地区港口码头数据，包含了沿江30多个各港口码头的名称及经纬度等信息。在相关资料基础上，得到沿长江地区所有港口名称及经纬度信息，对数据进行人工数字化，并进行相应拓扑检查得到对应港口码头数据。数据集包含1个shp矢量文件，“长江沿岸港口.shp”', '数据来源：中国航运数据库—交通科学数据共享平台水运科学数据分中心
数据加工方法：搜集相关资料，得到沿长江地区所有港口名称及经纬度信息，对数据进行人工数字化，并进行相应拓扑检查得到对应港口码头数据。
质量控制：搜集相关资料，得到沿长江地区所有港口名称及经纬度信息，对数据进行人工数字化，得到数据。在数据处理过程中，利用arcgis软件进行规范化操作，对数据进行相应拓扑检查，保证数据完整性、逻辑一致性、位置精度、属性精度、接边精度、现势性均符合国家测绘局制定的有关技术规定和标准的要求，质量优良可靠。
