  ('86c89f4600ab46c19b9ece897c579cca', 'b53531247c794f4fa813ecf614da165e', '洪泽湖环湖水文站日水位数据集（2006-2021年）', NULL, '该数据集在2006-2021年代洪泽湖区水文年鉴的基础上进行人工整理，得到包含了洪泽湖环湖15个水文水位站点日均水位数据。包含了所属河流、站点名称、时间、水位等指标。 数据集为1个excel表格文件，日水位.xlsx。', '数据来源：淮河流域水文资料 第3册 淮河中游区（涡河、洪泽湖水系）（2006-2021年）
数据加工方法：提取《淮河流域水文资料 第3册 淮河中游区（涡河、洪泽湖水系）》中水文站及日均水位指标，对相关要素整理、扫描数字化，再按照标准格式，将水位及相关站点信息摘录成表格格式
质量控制：在人工摘录、加工过程中进行了两轮与原始数据的人工比对校核，纠正错误信息，数据质量可靠', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['洪泽湖','水文站','日水位'], '[{"@type":"Organization","name":"中国科学院南京地理与湖泊研究所科学数据中心","@id":"89f025a69e3042e2b749ba960c897091"}]'::jsonb, '中国科学院南京地理与湖泊研究所科学数据中心', '洪泽湖', '2006-2021年', '10.11971/lim.2025.077.db.lwdc', 'CC BY-NC-SA 4.0', 'condition', '需要用户提交申请表进行离线申请', 4860901, 2, 1, 21, 0, 1, 'adopt', 'release', 'V1', 'https://kxsj.jssic.cn/api/datasetLogo/2026/86c89f4600ab46c19b9ece897c579cca.png', '[{"name":"zip","count":1},{"name":"xlsx","count":1}]'::jsonb, '[{"storageNum":2365520,"name":"zip"},{"storageNum":2495381,"name":"xlsx"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-07', '2026-05-07'),
  ('c509627c13e947c498c2b9aec201cf89', '1f62e88d05764549a002d4ba16453697', '江苏省海岸带多功能类型坑塘水面空间分布数据集（2022年）', NULL, '该数据集为2022年江苏省海岸带多功能类型坑塘水面空间分布数据，以江苏省海岸带坑塘水面为研究对象，利用2022年的Sentinel-2高分辨率数据，基于GEE绘制了多功能类型坑塘水面的空间分布图，总体分类准确率达到80%以上。', '数据来源：基于Sentinel-2地表反射率数据
数据加工方法：本研究以江苏省海岸带坑塘水面为研究对象，构建了海岸带坑塘水面解译标志，首次提出了包含陆域养殖坑塘、海域养殖水面，盐田，天然坑塘和景观坑塘的海岸带坑塘水面多功能分类体系，通过多遥感特征与面向对象分层分类方法，实现10 m分辨率的江苏省海岸带多功能类型坑塘水面的空间分布制图，总体分类准确率达到80%以上。具体研究方法见参考论文:
Yijun Tong, Chen Lin *, Ke Song., et al. (2025). Reconstructing coastal ponds functional classification: Integration of multi-feature remote sensing. Ecological Informatics, 91, 103370.
质量控制： 10m分辨率 Sentinel-2 影像数据源。研究提出了一种基于 GEE 的多特征融合面向对象（MFFO）分类方法。主要包括六个步骤：（1）预处理；（2）水体提取。 (3) 干扰消除；(4) 池塘分类；(5) 精度评估；(6) 产品化；总体精度为90%
投影坐标：空间范围为江苏省海岸带坑塘水面，投影方式为WGS84', '11', '数据集', '水域生态数据集', ARRAY['自然地理学（包括生态地理学、冰川学、冻土学、沙漠学、岩溶学等）'], ARRAY['江苏省','海岸带','坑塘'], '[{"Organization":{"@type":"Organization","name":"中国科学院南京地理与湖泊研究所","en_name":"Nanjing Institute of Geography and Limnology","@id":"7599508ada754b5d83a2760af4e3f9ce"},"@type":"Person","name":"林晨","en_name":"","@id":"4376ddb4-ccca-4a07-a764-48d06249909d","email":"clin@niglas.ac.cn"}]'::jsonb, '中国科学院南京地理与湖泊研究所', '江苏省', '2022年', '10.11971/lim.2025.057.db.lwdc', 'CC BY-NC-SA 4.0', 'condition', '需要用户提交申请表进行离线申请', 14216830, 1, NULL, 4, 0, 1, 'adopt', 'release', 'V2', 'https://kxsj.jssic.cn/api/datasetLogo/2026/c509627c13e947c498c2b9aec201cf89.png', '[{"name":"zip","count":1}]'::jsonb, '[{"storageNum":14216830,"name":"zip"}]'::jsonb, '江苏省水域生态科学数据中心', 'lwdc@niglas.ac.cn', NULL, NULL, NULL, '2026-05-07', '2026-05-07')
